const P={cod:[],desc:[],vl:[],n:[],comp:[]}, pIdx=new Map();
function loadP(txt,lista){const ant=new Map(),antU=new Map();P.cod.forEach((c,i)=>{if(P.comp[i])ant.set(c,P.comp[i]);if(P.un&&P.un[i])antU.set(c,P.un[i]);});if(!P.un)P.un=[];P.cod.length=P.desc.length=P.vl.length=P.n.length=P.comp.length=P.un.length=0;pIdx.clear();
  txt.split("\n").forEach(l=>{if(!l)return;const [c,d,v,cp,un]=l.split("\t");if(!c||pIdx.has(c))return;pIdx.set(c,P.cod.length);P.cod.push(c);P.desc.push(d||"");P.vl.push(parseFloat(v)||0);P.n.push(norm(d||""));P.un.push(un?String(un).trim().toUpperCase():(antU.get(c)||""));
    P.comp.push(cp==null||cp===""?(ant.get(c)||""):lista&&/^\d+$/.test(cp)?(lista[+cp]||ant.get(c)||""):cp);});}
