  box.querySelectorAll("[data-cvok]").forEach(b=>b.onclick=()=>cmud(b.dataset.cvok,"Emitido","Confirmar que o VALE DE MERCADORIAS FOI EMITIDO?"));
  box.querySelectorAll("[data-cvno]").forEach(b=>b.onclick=()=>cmud(b.dataset.cvno,"Não emitido","Confirmar que o vale NÃO foi emitido?"));
  box.querySelectorAll("[data-cvpe]").forEach(b=>b.onclick=()=>cmud(b.dataset.cvpe,"Pendente","Voltar este vale para PENDENTE de emissão?"));
