const CE_FST=[["","Todas as situações"],["presente","Presentes"],["folga","Folga"],["ferias","Férias"],["falta","Faltas"],["atestado","Atestado"],["sem","Sem registro"]];
const ceStDe=(r,f)=>r[f.mat]&&r[f.mat].s||"sem";
const ceFSt=(r,L)=>CE.fSt?L.filter(f=>ceStDe(r,f)===CE.fSt):L;
const ceFStNome=()=>{const x=CE_FST.find(([k])=>k===(CE.fSt||""));return CE.fSt&&x?x[1]:"";};
