const CE_DBT=[["total","Total"],["presente","Presentes"],["esc","Escalados"],["falta","Faltas"],["folga","Folgas"],["ferias","Férias"],["atestado","Atestados"]];
const CE_AUS=[["ferias","Férias","#1F5DB8"],["folga","Folga","#94580A"],["falta","Falta","#B3261E"],["atestado","Atestado","#6E3FB8"]];
function ceBoard(d){const list=ceLista(),r=ceRegs(d),c=ceStats(r,list),aus=CE_AUS.map(a=>a[0]);const reg=list.filter(f=>!aus.includes(r[f.mat]&&r[f.mat].s));
  const now=new Date(),nowH=now.getHours()+now.getMinutes()/60;reg.sort((a,b)=>((r[a.mat]&&r[a.mat].s==="presente"?0:1)-(r[b.mat]&&r[b.mat].s==="presente"?0:1))||(a.turno||"99").localeCompare(b.turno||"99")||a.nome.localeCompare(b.nome,"pt-BR"));
  const stl=f=>{if(r[f.mat]&&r[f.mat].s==="presente")return '<span class="db-st ok">Presente</span>';const h=parseInt(f.turno,10)||8;if(d>todayISO()||(d===todayISO()&&nowH<h))return '<span class="db-st wait">Entrada '+ceTL(f.turno)+'</span>';return '<span class="db-st none">Sem registro</span>';};
  const filtro=[CE.fSub,CE.fTurno?"Entrada "+ceTL(CE.fTurno):"",CE.q?"Busca: "+CE.q:"",ceFStNome()?"Situação: "+ceFStNome():""].filter(Boolean).join(" | ");
  const stB=f=>{const k=ceStDe(r,f);return k==="sem"?stl(f):'<span class="db-st '+(k==="presente"?"ok":"none")+'">'+esc(CE_ST[k]?CE_ST[k][0]:k)+'</span>';};
  const sel=CE.fSt?ceFSt(r,list):null;
  return '<div class="ce-db"><div class="ce-dbh"><div><h2>'+CE_SETOR+'</h2><p>Relatório de presença | '+ceCap(ceWd(d))+', '+ceBr(d)+(filtro?" | "+esc(filtro):"")+'</p></div><img src="'+LOGO_WHITE_SRC()+'" alt="Santa Therezinha"></div><div class="ce-dbb">'+
    '<div class="ce-tiles">'+CE_DBT.map(([k,l])=>'<div class="ce-tile t-'+k+(k!=="esc"&&(CE.fSt||"")===(k==="total"?"":k)&&CE.fSt?" on":"")+'"'+(k==="esc"?'':' data-cest="'+(k==="total"?"":k)+'" role="button" tabindex="0" title="Filtrar: '+l+'" style="cursor:pointer"')+'><b>'+c[k]+'</b><span>'+l+'</span></div>').join("")+'</div>'+
    (sel?'<h3 class="ce-sec"><i class="ce-dot"></i>'+esc(ceFStNome())+' ('+sel.length+')</h3><table class="ce-tbl"><thead><tr><th>Nome</th><th>Código</th><th>Subsetor</th><th>Entrada</th><th>Situação</th><th>Observação</th></tr></thead><tbody>'+
      (sel.map(f=>'<tr><td class="n">'+esc(f.nome)+'</td><td>'+esc(f.mat)+'</td><td>'+esc(f.subsetor||"—")+'</td><td>'+ceTL(f.turno)+'</td><td>'+stB(f)+'</td><td>'+esc(r[f.mat]&&r[f.mat].obs||"")+'</td></tr>').join("")||'<tr><td colspan="6" style="text-align:center;padding:18px">Ninguém nesta situação.</td></tr>')+'</tbody></table></div>':
    '<h3 class="ce-sec">Ausências do dia</h3><div class="ce-aus">'+CE_AUS.map(([k,l,col])=>{const a=list.filter(f=>r[f.mat]&&r[f.mat].s===k);return '<div class="ce-box" style="--c:'+col+'"><h4>'+l+' ('+a.length+')</h4>'+(a.length?'<ul>'+a.map(f=>'<li>'+esc(f.nome)+(r[f.mat].obs?'<small>'+esc(r[f.mat].obs)+'</small>':'')+'</li>').join("")+'</ul>':'<span class="nada">Nenhum</span>')+'</div>';}).join("")+'</div>'+
    '<h3 class="ce-sec"><i class="ce-dot"></i>Registro de presença ('+reg.length+')</h3><table class="ce-tbl"><thead><tr><th>Nome</th><th>Código</th><th>Subsetor</th><th>Entrada</th><th>Status</th><th>Data</th></tr></thead><tbody>'+
    (reg.map(f=>'<tr><td class="n">'+esc(f.nome)+'</td><td>'+esc(f.mat)+'</td><td>'+esc(f.subsetor||"—")+'</td><td>'+ceTL(f.turno)+'</td><td>'+stl(f)+'</td><td>'+ceBr(d)+'</td></tr>').join("")||'<tr><td colspan="6" style="text-align:center;padding:18px">Ninguém neste filtro.</td></tr>')+'</tbody></table></div>')+
    '<div class="ce-dbf"><span>'+CE_SETOR+' | Painel de gestão | Taxa de presença '+cePct(c.taxa)+'</span><span>Gerado em '+fmtDT(new Date())+'</span></div></div>';}

async function ceExportImg(fmt){const jpgEsc=3;try{toast("Gerando imagem da chamada…");if(!window.html2canvas)await loadScript("lib/html2canvas.min.js");
    const box=document.createElement("div");box.style.cssText="position:fixed;left:-12000px;top:0;width:1120px;background:#F4F7FC;z-index:-1";box.innerHTML=ceBoard(CE.d);document.body.appendChild(box);
    await new Promise(r=>setTimeout(r,80));const el=box.firstElementChild;el.style.minWidth="0";el.style.width="1120px";
    const cv=await window.html2canvas(el,{scale:jpgEsc,backgroundColor:"#F4F7FC",useCORS:true,logging:false,imageTimeout:0});box.remove();
    const jpg=fmt==="jpg",mime=jpg?"image/jpeg":"image/png",nome="Chamada_"+CE.d+(CE.fSub?"_"+CE.fSub.replace(/\W+/g,"_"):"")+(CE.fTurno?"_"+CE.fTurno.replace(":","h"):"")+(jpg?".jpg":".png");
    const blob=await new Promise(r=>cv.toBlob(r,mime,jpg?.97:undefined));const file=new File([blob],nome,{type:mime});
    if(document.documentElement.classList.contains("mob")&&navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:"Chamada "+ceBr(CE.d)});return;}catch(e){if(e&&e.name==="AbortError")return;}}
    const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=nome;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},1500);toast("Imagem salva: "+nome);}
  catch(e){toast("Não consegui gerar a imagem: "+(e.message||e));}}
