  const tabs=[["painel","Dashboard"],["chamada","Chamada"],["periodo","Relatório por período"],["historico","Histórico"]].concat(ceCom()?[["equipe","Montar equipe"]]:[]);let h=ceTopo()+ceSub(tabs,CE.tab,"cet");
