/* ===== Inventário: ajustes de inventário (sobras e perdas) por dia, mês, ano e comparativo.
   Importação em Bases e planilhas (e no próprio setor); base compartilhada pelo painel "inv". ===== */
const INV={rows:[],src:"",em:"",por:"",nome:"",ver:0,ld:false,tab:"dia",dep:"",dia:"",mes:"",ano:"",cA:"",cB:"",yA:"",yB:"",q:"",pend:null,sync:""};
const INV_MES=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"],INV_MC=["jan","fev","mar","abr","mai","jun","jul","ago","set","out","nov","dez"],INV_SD="Sem departamento";
const INV_C={pos:"#16A34A",neg:"#DC2626",net:"#103F79",sel:"#F59E0B"};
const invPode=()=>gPerm("ce_est")||temPerm("ce_bas")||temPerm("ce_inv");
const invML=ym=>{const [y,m]=ym.split("-");return INV_MES[+m-1]+" de "+y;},invMS=ym=>{const [y,m]=ym.split("-");return INV_MC[+m-1]+"/"+y.slice(2);},invBr=iso=>iso?iso.split("-").reverse().join("/"):"—";
const invPct=(a,b)=>b===0?null:(a-b)/Math.abs(b)*100;
const invK=v=>{const a=Math.abs(v),s=v<0?"−":"";return a>=1e6?s+cvFmt(a/1e6,1)+" mi":a>=1e3?s+cvFmt(a/1e3,1)+" mil":s+cvFmt(a,0);};
function invFrom(o){if(!o||!o.rows)return [];return o.rows.map(r=>({c:String(r[0]),d:o.desc[String(r[0])]||"",e:r[1]===1,dt:r[2],q:r[3],v:r[4],dep:o.depts[r[5]]||INV_SD}));}
function invTo(rows){const desc={},depts=[],out=[];rows.forEach(r=>{desc[r.c]=r.d;let i=depts.indexOf(r.dep);if(i<0){depts.push(r.dep);i=depts.length-1;}out.push([isNaN(+r.c)?r.c:+r.c,r.e?1:0,r.dt,r.q,r.v,i]);});return {desc,depts,rows:out};}
async function invLoad(){if(INV.ld)return;INV.ld=true;let o=null;try{o=await cvGet("inv");}catch(e){}
  if(o&&o.rows){INV.rows=invFrom(o);INV.src=o.src||"import";INV.em=o.em||"";INV.por=o.por||"";INV.nome=o.nome||"";INV.ver=o.ver||0;return;}
  try{const r=await fetch("inventario_base.json",{cache:"force-cache"});if(r.ok){const b=await r.json();INV.rows=invFrom(b);INV.src="base";INV.nome="Planilha original do painel de inventário";}}catch(e){}}
async function invGuarda(){try{await cvSet("inv",Object.assign(invTo(INV.rows),{src:INV.src,em:INV.em,por:INV.por,nome:INV.nome,ver:INV.ver}));}catch(e){}}
async function invPublicar(){if(DEMO||!LOGIN||!navigator.onLine)return false;try{const z=await rzZip(Object.assign(invTo(INV.rows),{em:INV.em,nome:INV.nome}));const j=await ppPost({acao:"painel_salvar",painel:"inv",dados:Object.assign(z,{n:INV.rows.length,em:INV.em,nome:INV.nome})});if(!j||!j.ok)return false;INV.ver=j.versao;INV.por=j.por||"";await invGuarda();return true;}catch(e){INV.sync=/inv|desconh|permiss|a[cç][aã]o/i.test(e.message)?"Atualize o Apps Script (versão 90) para a base de inventário ser compartilhada.":"";return false;}}
async function invSync(){if(DEMO||!LOGIN||!navigator.onLine)return false;try{const v=await ppPost({acao:"painel_ver",painel:"inv"});if(!v||!v.versao||(INV.ver&&INV.ver>=v.versao))return false;const j=await ppPost({acao:"painel_ler",painel:"inv"});if(!j||!j.dados)return false;const d=await rzUnzip(j.dados);if(!d||!d.rows)return false;
  INV.rows=invFrom(d);INV.src="import";INV.em=d.em||j.em||"";INV.nome=d.nome||"";INV.por=j.por||"";INV.ver=j.versao||v.versao;await invGuarda();return true;}catch(e){if(/inv|desconh|a[cç][aã]o/i.test(e.message||""))INV.sync="Atualize o Apps Script (versão 90) para a base de inventário ser compartilhada.";return false;}}
/* ---------- leitura da planilha ---------- */
function invISO(v){if(v instanceof Date&&!isNaN(v))return v.getFullYear()+"-"+String(v.getMonth()+1).padStart(2,"0")+"-"+String(v.getDate()).padStart(2,"0");
  if(typeof v==="number"){const d=XLSX.SSF.parse_date_code(v);if(d)return d.y+"-"+String(d.m).padStart(2,"0")+"-"+String(d.d).padStart(2,"0");}
  if(typeof v==="string"){let m=v.trim().match(/^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})/);if(m)return (m[3].length===2?"20"+m[3]:m[3])+"-"+m[2].padStart(2,"0")+"-"+m[1].padStart(2,"0");m=v.trim().match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return m[1]+"-"+m[2]+"-"+m[3];}return null;}
const invNum=v=>{if(typeof v==="number")return v;if(v==null||v==="")return 0;let s=String(v).replace(/[R$\s]/g,"");if(s.includes(","))s=s.replace(/\./g,"").replace(",",".");const n=parseFloat(s);return isNaN(n)?0:n;};
function invParse(wb){const nn=s=>String(s||"").normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase().trim();
  for(const name of wb.SheetNames){const A=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,raw:true,defval:null});
    for(let h=0;h<Math.min(A.length,20);h++){const hd=(A[h]||[]).map(nn),f=(...k)=>hd.findIndex(x=>k.some(t=>x.includes(t)));const ix={c:f("codigo","cod"),d:f("descri","produto"),op:f("opera"),dt:f("data"),q:f("quant","qtd"),v:f("vlr","valor"),dep:f("depart","setor")};
      if(ix.c<0||ix.dt<0||ix.v<0)continue;const out=[];
      for(let i=h+1;i<A.length;i++){const r=A[i];if(!r)continue;const dt=invISO(r[ix.dt]);if(!dt||r[ix.c]==null)continue;const v=invNum(r[ix.v]),q=ix.q>=0?invNum(r[ix.q]):0,op=ix.op>=0?nn(r[ix.op]):"",e=op.includes("entr")?true:op.includes("sai")?false:v>=0;
        out.push({c:String(r[ix.c]).trim().replace(/\.0$/,""),d:ix.d>=0&&r[ix.d]!=null?String(r[ix.d]).trim():"",e,dt,q:Math.round(q*1000)/1000,v:Math.round(v*10000)/10000,dep:ix.dep>=0&&r[ix.dep]!=null&&String(r[ix.dep]).trim()?String(r[ix.dep]).trim():INV_SD});}
      if(out.length)return out;}}return null;}
async function invImport(file){const m=$("binv-msg");if(m)m.textContent="Lendo "+file.name+"…";
  try{await invLoad();if(!window.XLSX){try{await loadScript(XLSX_URL_LOCAL());}catch(e){throw new Error("Para ler o Excel é preciso internet na primeira vez.");}}
    const wb=XLSX.read(await file.arrayBuffer(),{type:"array",cellDates:true,dense:true,cellFormula:false,cellHTML:false,cellText:false}),rows=invParse(wb);
    if(!rows)throw new Error("Não encontrei as colunas Código, Data Inventário e Vlr. de Ajuste nesse arquivo.");
    const ds=[...new Set(rows.map(r=>r.dt))].sort();if(m)m.textContent="";invDlgImport(file.name,rows,ds);}
  catch(e){if(m)m.textContent="Não importou: "+(e.message||e);toast("Não importou: "+(e.message||e));}}
function invDlgImport(nome,rows,ds){const ov=document.createElement("div");ov.className="pcg-ov";
  ov.innerHTML='<div class="pcg-dlg inv-imp" role="dialog" aria-modal="true" aria-labelledby="inv-it"><header><div><h3 id="inv-it">Atualizar a base de inventário</h3><p class="pcg-dp">'+esc(nome)+'</p></div><button type="button" class="pcg-dx" data-x aria-label="Fechar">×</button></header>'+
    '<div class="inv-ib"><p><b>'+cvFmt(rows.length)+'</b> lançamentos de <b>'+invBr(ds[0])+'</b> a <b>'+invBr(ds[ds.length-1])+'</b>.</p><p class="pcg-sm"><b>Substituir</b> troca toda a base por este arquivo. <b>Somar</b> junta os dois e ignora lançamentos repetidos: use para acrescentar um mês ou um ano novo.</p>'+(INV.rows.length?'<p class="pcg-sm">Base atual: '+cvFmt(INV.rows.length)+' lançamentos.</p>':'')+'</div>'+
    '<footer><button type="button" class="btn sm" data-x>Cancelar</button><span></span><button type="button" class="btn" data-m="1">Somar aos dados atuais</button><button type="button" class="save pcg-bt" data-m="0">Substituir dados</button></footer></div>';
  document.body.appendChild(ov);const fecha=()=>ov.remove();ov.addEventListener("click",async e=>{if(e.target===ov||e.target.closest("[data-x]")){fecha();return;}const b=e.target.closest("[data-m]");if(!b)return;const merge=b.dataset.m==="1";let add=rows.length;
    if(merge){const key=r=>[r.c,r.e?1:0,r.dt,r.q,(+r.v).toFixed(2)].join("|"),seen=new Set(INV.rows.map(key)),nv=rows.filter(r=>!seen.has(key(r)));add=nv.length;INV.rows=INV.rows.concat(nv);}else INV.rows=rows;
    INV.src="import";INV.em=fmtDT(new Date());INV.nome=nome;INV.por=(LOGIN&&LOGIN.nome)||"";INV.dia=INV.mes=INV.ano=INV.cA=INV.cB=INV.yA=INV.yB="";await invGuarda();fecha();
    const msg="✓ "+(merge?cvFmt(add)+" lançamentos novos somados":"Base substituída")+" · base com "+cvFmt(INV.rows.length)+" lançamentos.";const m=$("binv-msg");if(m)m.textContent=msg;toast(merge?"Lançamentos somados à base de inventário.":"Base de inventário substituída.");invBasesPaint();if($("v-inv")&&!$("v-inv").hidden)invPaint();
    invPublicar().then(ok=>{const mm=$("binv-msg");if(mm)mm.textContent=msg+(ok?" Publicada para todos do setor.":" (Ficou só neste aparelho: não foi possível publicar agora.)");invBasesPaint();});});}
function invBasesPaint(){const s=$("binv-src"),n=$("binv-n");if(!s)return;if(!INV.rows.length){s.textContent="Nenhum arquivo importado";if(n)n.textContent="0";return;}const ds=[...new Set(INV.rows.map(r=>r.dt))].sort();
  s.textContent=(INV.src==="base"?"Planilha original do painel":"Atualizada em "+INV.em+(INV.por?" por "+INV.por:""))+" · "+invBr(ds[0])+" a "+invBr(ds[ds.length-1]);if(n)n.textContent=cvFmt(INV.rows.length);}
/* ---------- cálculos ---------- */
const invF=()=>INV.dep?INV.rows.filter(r=>r.dep===INV.dep):INV.rows;
function invSum(rows){let ent=0,sai=0,qE=0,qS=0;const sk=new Set();rows.forEach(r=>{if(r.v>=0)ent+=r.v;else sai+=r.v;if(r.q>=0)qE+=r.q;else qS+=r.q;sk.add(r.c);});return {ent,sai,net:ent+sai,abs:ent-sai,n:rows.length,skus:sk.size,qE,qS};}
function invGB(rows,key){const m=new Map();rows.forEach(r=>{const k=key(r);if(!m.has(k))m.set(k,[]);m.get(k).push(r);});return m;}
function invProd(rows){const m=new Map();rows.forEach(r=>{let p=m.get(r.c);if(!p){p={c:r.c,d:r.d,dep:r.dep,v:0,q:0,n:0};m.set(r.c,p);}p.v+=r.v;p.q+=r.q;p.n++;});return [...m.values()];}
const invMeses=rows=>[...new Set(rows.map(r=>r.dt.slice(0,7)))].sort(),invAnos=rows=>[...new Set(rows.map(r=>r.dt.slice(0,4)))].sort(),invDias=rows=>[...new Set(rows.map(r=>r.dt))].sort();
function invSerie(rows,y){return Array.from({length:12},(_,i)=>{const k=y+"-"+String(i+1).padStart(2,"0"),rr=rows.filter(r=>r.dt.startsWith(k));return Object.assign({k,has:rr.length>0},invSum(rr));});}
/* ---------- gráficos ---------- */
function invCols(L,o){o=o||{};const W=o.w||900,H=o.h||280,pl=56,pr=12,pt=22,pb=o.pb||32,n=Math.max(1,L.length),vals=L.flatMap(x=>[x.e||0,x.s||0,x.n||0]),hi=Math.max(0,...vals),lo=Math.min(0,...vals),span=(hi-lo)||1,top=hi+span*0.14,bot=lo-(lo<0?span*0.1:0),Y=v=>pt+(top-v)/(top-bot)*(H-pt-pb),bw=(W-pl-pr)/n;
  let s='<svg class="rz-svg" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="xMidYMid meet">';const step=(top-bot)/4;
  for(let i=0;i<=4;i++){const v=bot+step*i,y=Y(v);s+='<line x1="'+pl+'" x2="'+(W-pr)+'" y1="'+y.toFixed(1)+'" y2="'+y.toFixed(1)+'" stroke="var(--line,#E2E8F0)"/><text x="'+(pl-6)+'" y="'+(y+3).toFixed(1)+'" text-anchor="end" class="rz-ax">'+invK(v)+'</text>';}
  const y0=Y(0);s+='<line x1="'+pl+'" x2="'+(W-pr)+'" y1="'+y0.toFixed(1)+'" y2="'+y0.toFixed(1)+'" stroke="#64748B" stroke-width="1.2"/>';
  const lab=n<=16,rot=n>16&&!o.norot,ev=o.step||Math.ceil(n/(o.norot?40:18));
  L.forEach((x,i)=>{const bx=pl+i*bw+bw*0.16,w=bw*0.68,att=(x.k?' data-invk="'+esc(x.k)+'"':'')+' data-rztip="'+esc(x.t||x.l)+'"',sel=x.sel?' stroke="#0F172A" stroke-width="1.5"':'';
    if(o.single){const v=x.n||0,c=x.sel?INV_C.sel:v>=0?INV_C.pos:INV_C.neg,yy=Math.min(Y(v),y0),hh=Math.abs(Y(v)-y0);s+='<rect class="rz-hd inv-hb" x="'+bx.toFixed(1)+'" y="'+yy.toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+Math.max(1,hh).toFixed(1)+'" rx="3" fill="'+c+'" fill-opacity="'+(x.sel?1:.82)+'"'+sel+att+'/>';
      if(lab&&v)s+='<text x="'+(bx+w/2).toFixed(1)+'" y="'+(v>=0?Y(v)-5:Y(v)+12).toFixed(1)+'" text-anchor="middle" class="inv-vl" fill="'+c+'">'+invK(v)+'</text>';}
    else{if(x.e){const yy=Y(x.e);s+='<rect class="rz-hd inv-hb" x="'+bx.toFixed(1)+'" y="'+yy.toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+Math.max(1,y0-yy).toFixed(1)+'" rx="3" fill="'+INV_C.pos+'" fill-opacity=".82"'+att+'/>';}
      if(x.s){const yy=Y(x.s);s+='<rect class="rz-hd inv-hb" x="'+bx.toFixed(1)+'" y="'+y0.toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+Math.max(1,yy-y0).toFixed(1)+'" rx="3" fill="'+INV_C.neg+'" fill-opacity=".78"'+att+'/>';}}
    if(i%ev===0||o.todos)s+=rot?'<text transform="translate('+(bx+w/2+3).toFixed(1)+','+(H-pb+8)+') rotate(-45)" text-anchor="end" class="rz-ax">'+esc(x.l)+'</text>':'<text x="'+(bx+w/2).toFixed(1)+'" y="'+(H-pb+14)+'" text-anchor="middle" class="rz-ax">'+esc(x.l)+'</text>';});
  if(!o.single){const P=L.map((x,i)=>x.n==null?null:[pl+i*bw+bw/2,Y(x.n),x]).filter(Boolean);if(P.length){s+='<polyline points="'+P.map(p=>p[0].toFixed(1)+","+p[1].toFixed(1)).join(" ")+'" fill="none" stroke="'+INV_C.net+'" stroke-width="2.4" stroke-linejoin="round"/>';
    P.forEach(p=>{s+='<circle class="rz-hd" cx="'+p[0].toFixed(1)+'" cy="'+p[1].toFixed(1)+'" r="3.6" fill="'+INV_C.net+'" stroke="#fff" stroke-width="1.4" data-rztip="'+esc(p[2].t||"")+'"'+(p[2].k?' data-invk="'+esc(p[2].k)+'"':'')+'/>';if(lab)s+='<text x="'+p[0].toFixed(1)+'" y="'+(p[1]-8).toFixed(1)+'" text-anchor="middle" class="inv-nl">'+invK(p[2].n)+'</text>';});}}
  return s+'</svg>'+(o.single?'':'<p class="pcg-lg"><i style="background:'+INV_C.pos+'"></i>Entradas (sobras) <i style="background:'+INV_C.neg+'"></i>Saídas (perdas) <i style="background:'+INV_C.net+';height:3px"></i>Resultado líquido</p>');}
function invDep(rows,modo){const g=invGB(rows,r=>r.dep);let D=[...g.keys()].map(k=>{const rr=g.get(k),e=rr.filter(r=>r.v>=0).reduce((a,r)=>a+r.v,0),s=rr.filter(r=>r.v<0).reduce((a,r)=>a+r.v,0);return {l:k,e,s,n:e+s,c:rr.length};});
  if(!D.length)return '<p class="note">Sem lançamentos.</p>';D.sort((a,b)=>modo==="split"?(b.e-b.s)-(a.e-a.s):a.n-b.n);const mx=Math.max(1,...D.map(d=>modo==="split"?Math.max(d.e,-d.s):Math.abs(d.n)));
  return '<div class="inv-hb2">'+D.map(d=>{const t=d.l+" · entradas "+BRL.format(d.e)+" · saídas "+BRL.format(d.s)+" · resultado "+BRL.format(d.n)+" · "+d.c+" lançamento(s)";
    return '<div class="rz-hd" data-rztip="'+esc(t)+'"><span>'+esc(d.l)+'</span><div class="inv-tr"><div class="l">'+(modo==="split"?(d.s?'<i style="width:'+(-d.s/mx*100).toFixed(1)+'%;background:'+INV_C.neg+'"></i>':''):(d.n<0?'<i style="width:'+(-d.n/mx*100).toFixed(1)+'%;background:'+INV_C.neg+'"></i>':''))+'</div><div class="r">'+(modo==="split"?(d.e?'<i style="width:'+(d.e/mx*100).toFixed(1)+'%;background:'+INV_C.pos+'"></i>':''):(d.n>0?'<i style="width:'+(d.n/mx*100).toFixed(1)+'%;background:'+INV_C.pos+'"></i>':''))+'</div></div><b class="'+(d.n>=0?"inv-p":"inv-n")+'">'+invK(d.n)+'</b></div>';}).join("")+'</div>';}
