const INV_CN={h:"Lançam.",f:p=>cvFmt(p.n)},INV_CQ={h:"Qtd.",f:p=>cvFmt(p.q)},INV_CV={h:"Resultado",f:p=>BRL.format(p.v),cls:p=>p.v>=0?"inv-p":"inv-n"};
