  let h='<div class="cv-fonte"><span>Ajustes de inventário: <b>'+(INV.rows.length?cvFmt(INV.rows.length)+' lançamentos de '+invBr(D[0])+' a '+invBr(D[D.length-1]):'nenhuma base importada')+'</b>'+(INV.rows.length?' · '+(INV.src==="base"?"planilha original do painel":"atualizada em "+esc(INV.em)+(INV.por?" por "+esc(INV.por):"")):"")+'</span>'+(INV.sync?'<span>'+esc(INV.sync)+'</span>':'')+(ed?'<label class="link inv-up">Importar planilha<input type="file" id="inv-file" accept=".xlsx,.xls,.csv" hidden></label>':'')+(pb?'<button type="button" class="link" data-cvgo="bases">Bases e planilhas →</button>':'')+'</div>';
  if(!INV.rows.length){box.innerHTML=h+'<div class="block"><p class="note">'+(ed?'Importe a planilha de ajustes de inventário (colunas Código, Descrição, Operação, Data Inventário, Quantidade, Vlr. de Ajuste e Departamento) em <b>Bases e planilhas</b>.':'O painel aparece aqui assim que a base de inventário for importada.')+'</p></div>';return;}
  const deps=[...new Set(INV.rows.map(r=>r.dep))].sort((a,b)=>a===INV_SD?1:b===INV_SD?-1:a.localeCompare(b,"pt-BR"));if(INV.dep&&!deps.includes(INV.dep))INV.dep="";
