function cbMerge(A,B){const o=Object.assign({},A);["cestas","cfg"].forEach(k=>{if(B[k]&&(!A[k]||(B[k].t||0)>(A[k].t||0)))o[k]=B[k];});CB_COLS.forEach(k=>{o[k]=Object.assign({},A[k]||{});Object.entries(B[k]||{}).forEach(([id,v])=>{if(v&&(!o[k][id]||(v.t||0)>(o[k][id].t||0)))o[k][id]=v;});});return o;}
