function cbSet(col,id,obj){obj.t=Date.now();obj.por=(LOGIN&&LOGIN.nome)||meuMat()||"";if(col==="cestas"||col==="cfg")CB.d[col]=obj;else CB.d[col][id]=obj;return cbGuarda();}
function cbAviso(er){if(CB.av)return;CB.av=true;toast(/inv|desconh|permiss|a[cç][aã]o/i.test(String(er||""))?"Cesta salva só neste aparelho: atualize o Apps Script (versão 86) para compartilhar.":"Cesta salva neste aparelho; não foi possível compartilhar agora.");}
async function cbPub(){if(DEMO||!LOGIN||!navigator.onLine)return;try{const j=await ppPost({acao:"painel_ler",painel:"cesta2"}).catch(e=>({ok:false,erro:e.message}));if(j&&!j.ok&&!/n[aã]o h[aá]|vazio/i.test(j.erro||"")){cbAviso(j.erro);return;}if(j&&j.dados){const d=await rzUnzip(j.dados);if(d&&d.d)CB.d=cbMerge(CB.d,d.d);}
  const z=await rzZip({d:CB.d});const w=await ppPost({acao:"painel_salvar",painel:"cesta2",dados:Object.assign(z,{em:fmtDT(new Date())})}).catch(e=>({ok:false,erro:e.message}));if(w&&w.ok){CB.ver=w.versao||CB.ver;await cvSet("cb",{d:CB.d,ver:CB.ver});}else cbAviso(w&&w.erro);}catch(e){cbAviso(e.message);}}
async function cbSync(forca){if(DEMO||!LOGIN||!navigator.onLine)return false;try{const v=await ppPost({acao:"painel_ver",painel:"cesta2"});if(!v||!v.ok||!v.versao||(!forca&&v.versao<=CB.ver))return false;const j=await ppPost({acao:"painel_ler",painel:"cesta2"});if(!j||!j.ok||!j.dados)return false;const d=await rzUnzip(j.dados);if(!d||!d.d)return false;CB.d=cbMerge(CB.d,d.d);CB.ver=j.versao||v.versao;await cvSet("cb",{d:CB.d,ver:CB.ver});return true;}catch(e){return false;}}
/* migra o que já existia no painel antigo (remontes, colaboradores, itens e composição) */
function cbMigra(get){const d=cbSeed();let ok=false;const J=k=>{try{return JSON.parse(get(k)||"null");}catch(e){return null;}};
  const c=J("cesta-basica-comissao-v1");if(c){ok=true;if(Array.isArray(c.colaboradores)){d.colab={};c.colaboradores.forEach(x=>{d.colab[x.mat]={mat:x.mat,nome:x.nome,porPalete:+x.porPalete||0,t:2};});}
    (c.remontes||[]).forEach(r=>{d.rem[r.id]={id:r.id,data:r.data,ids:r.ids||[],t:2};});const ym=cbHoje().slice(0,7);d.fer={};Object.entries(c.status||{}).forEach(([m,s])=>{if(s==="ferias")d.fer[ym+"|"+m]={v:1,t:2};});}
  const it=J("cesta-basica-itens-v1");if(it&&it.itens&&it.itens.length){ok=true;d.itens={};it.itens.forEach(i=>{d.itens[i.codigo]={codigo:String(i.codigo),descricao:i.descricao,quantidade:+i.quantidade||0,total:+i.total||0,t:2};});}
  const cp=J("cesta-basica-composicao-v1");if(cp&&Object.keys(cp).length){ok=true;d.comp={};Object.entries(cp).forEach(([k,v])=>{d.comp[k]=Object.assign({},v,{t:2});});}
  return ok?d:null;}
async function cbLoad(){if(CB.ld)return;CB.ld=true;CB.mes=cbHoje().slice(0,7);let o=null;try{o=await cvGet("cb");}catch(e){}if(o&&o.d){CB.d=o.d;CB.ver=o.ver||0;}
  else{CB.d=cbMigra(k=>localStorage.getItem(k));if(!CB.d&&!DEMO&&LOGIN&&navigator.onLine){try{const v=await ppPost({acao:"painel_ver",painel:"cesta2"});if(!(v&&v.versao)){const j=await ppPost({acao:"painel_ler",painel:"cesta"});if(j&&j.dados)CB.d=cbMigra(k=>j.dados[k]);}}catch(e){}}if(!CB.d)CB.d=cbSeed();}
  CB_COLS.forEach(k=>{if(!CB.d[k])CB.d[k]={};});if(!CB.d.cfg)CB.d.cfg={t:1,valorRemonte:25,diasAlvo:30,limItem:30};}
/* ---------- leitura da planilha (Cesta 10/15, Produção, Projeção, Itens) ---------- */
function cbDate(v){if(v==null||v==="")return null;if(typeof v==="number"){const d=new Date(Math.round((v-25569)*864e5));return d.toISOString().slice(0,10);}const m=String(v).match(/(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);if(m)return (m[3].length===2?"20"+m[3]:m[3])+"-"+String(m[2]).padStart(2,"0")+"-"+String(m[1]).padStart(2,"0");const d=new Date(v);return isNaN(d)?null:d.toISOString().slice(0,10);}
function cbParse(wb){const ces={},prod=[],ped={};let itens=null;
  wb.SheetNames.forEach(name=>{const n=cbN(name),rows=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,raw:true,defval:null}),m=n.match(/(\d+)/);
    if(n.includes("proje")){let k=null,h=null;rows.forEach(r=>{if(!r)return;const t=cbN(r[0]);const mk=t.match(/cesta.*?(\d+)/);if(mk){k=mk[1];h=null;return;}if(r.some(v=>cbN(v)==="filial")){h=r.map(cbN);return;}
        if(k&&h&&r[h.indexOf("filial")]){const iP=h.findIndex(x=>x.includes("pedido")&&!x.includes("pos")),q=iP>=0?cbNum(r[iP]):null;if(q!=null)ped[k+"|"+cbLoja(r[h.indexOf("filial")])]=q;}});return;}
    if(n.includes("produ")&&m){const k=m[1],hi=rows.findIndex(r=>r&&r.some(v=>cbN(v).includes("palete")));if(hi<0)return;const h=rows[hi].map(cbN),f=fn=>h.findIndex(fn);
      const iP=f(x=>x.includes("palete")),iM=f(x=>x.startsWith("multiplo")),iQ=f(x=>x==="quantidade"),iD=f(x=>x.includes("data")),iV=f(x=>x.includes("vlr")||x.includes("produzido")||x.includes("valor"));
      rows.slice(hi+1).forEach(r=>{if(!r)return;const p=cbNum(r[iP]),mu=cbNum(r[iM]);let q=iQ>=0?cbNum(r[iQ]):null;if(!q&&p&&mu)q=p*mu;const d=cbDate(r[iD]);if(!q||!d)return;prod.push({key:k,paletes:p||0,multiplo:mu||0,quantidade:q,data:d,valor:iV>=0?cbNum(r[iV]):null});});return;}
    const hi=rows.findIndex(r=>r&&r.some(v=>cbN(v)==="filial"));
    if(hi>=0&&m){const k=m[1],raw=rows[hi],h=raw.map(cbN),f=fn=>h.findIndex(fn),c=ces[k]=ces[k]||{key:k,filiais:[],meses:[]};
      const iF=f(x=>x==="filial"),iC=f(x=>x.startsWith("codigo")),iDs=f(x=>x.startsWith("descri")),iFi=f(x=>x.startsWith("fisico")),iDi=f(x=>x.startsWith("disponivel")||x.startsWith("estoque")),iV=f(x=>x.includes("vlr")||x.includes("entrada")),iVM=f(x=>x.startsWith("venda mes"));
      const iMs=h.map((x,i)=>/^mes \d+$/.test(x)?i:-1).filter(i=>i>=0).sort((a,b)=>parseInt(h[a].slice(4))-parseInt(h[b].slice(4)));c.meses=iMs.map(i=>String(raw[i]));
      rows.slice(hi+1).forEach(r=>{if(!r||r[iF]==null||r[iF]==="")return;if(iC>=0&&r[iC]!=null)c.codigo=r[iC];if(iDs>=0&&r[iDs])c.descricao=r[iDs];const di=cbNum(r[iDi])||0;
        c.filiais.push({filial:String(r[iF]).trim(),fisico:iFi>=0?(cbNum(r[iFi])||0):di,disponivel:di,vlr:iV>=0?cbNum(r[iV]):null,vendaMes:iVM>=0?(cbNum(r[iVM])||0):null,meses:iMs.map(i=>cbNum(r[i])||0)});});return;}
    if(!itens){const hj=rows.findIndex(r=>r&&r.some(v=>cbN(v).startsWith("descri"))&&r.some(v=>cbN(v)==="quantidade")&&r.some(v=>cbN(v).startsWith("codigo")));if(hj>=0&&!n.includes("consumo")){const h=rows[hj].map(cbN),iC=h.findIndex(x=>x.startsWith("codigo")),iD=h.findIndex(x=>x.startsWith("descri")),iQ=h.findIndex(x=>x==="quantidade"),iU=h.findIndex(x=>x.includes("ult")||x.includes("entrada")),iT=h.findIndex(x=>x.includes("total"));
      const L=rows.slice(hj+1).filter(r=>r&&r[iC]!=null&&r[iD]&&!cbN(rows[0]&&rows[0][0]).includes("consumo")).map(r=>{const q=cbNum(r[iQ])||0,t=iT>=0?cbNum(r[iT]):null,u=iU>=0?cbNum(r[iU]):null;return {codigo:String(r[iC]).trim(),descricao:String(r[iD]).trim(),quantidade:q,total:t!=null?t:(u||0)*q};});if(L.length&&!cbN(rows[0]&&rows[0][0]).includes("consumo"))itens=L;}}});
  Object.values(ces).forEach(c=>{const vs=c.filiais.map(f=>f.vlr).filter(v=>v!=null),avg=vs.length?cbSum(vs)/vs.length:null;prod.forEach(p=>{if(p.key===c.key&&p.valor==null&&avg)p.valor=p.quantidade*avg;});});
  return {ces,prod,ped,itens};}
async function cbImport(file){const m=$("bcb-msg");if(m)m.textContent="Lendo "+file.name+"…";
  try{await cbLoad();if(!window.XLSX){try{await loadScript(XLSX_URL_LOCAL());}catch(e){throw new Error("Para ler o Excel é preciso internet na primeira vez.");}}
    const wb=XLSX.read(await file.arrayBuffer(),{type:"array"}),P=cbParse(wb),ks=Object.keys(P.ces).filter(k=>P.ces[k].filiais.length);
    if(!ks.length&&!P.prod.length&&!P.itens)throw new Error("Não encontrei as abas da cesta (Cesta 10, Cesta 15, Produção Cesta …).");
    const t=Date.now(),por=(LOGIN&&LOGIN.nome)||meuMat()||"";
    if(ks.length){const data=Object.assign({},(CB.d.cestas&&CB.d.cestas.data)||{});ks.forEach(k=>{data[k]=P.ces[k];});CB.d.cestas={t,por,data,imp:file.name+" · "+fmtDT(new Date())};}
    if(P.prod.length){const novos={},cnt={};P.prod.forEach(p=>{const k=p.key+"|"+p.data,i=cnt[k]=(cnt[k]||0)+1,id="imp-"+p.key+"-"+p.data+"-"+i;novos[id]=Object.assign({id,src:"imp",t,por},p);});
      const kd=new Set(P.prod.map(p=>p.key+"|"+p.data));Object.values(CB.d.prod).forEach(x=>{if(x.src==="imp"&&kd.has(x.key+"|"+x.data)&&!novos[x.id])CB.d.prod[x.id]=Object.assign({},x,{del:1,t});});Object.assign(CB.d.prod,novos);}
    Object.entries(P.ped).forEach(([k,q])=>{CB.d.ped[k]={q,t,por};});
    if(P.itens){P.itens.forEach(i=>{CB.d.itens[i.codigo]=Object.assign({},i,{t,por});});}
    await cbGuarda();const msg="✓ "+(ks.length?"Estoque e vendas da(s) cesta(s) "+ks.join(" e ")+" · ":"")+P.prod.length+" lote(s) de produção"+(Object.keys(P.ped).length?" · "+Object.keys(P.ped).length+" pedido(s) da projeção":"")+(P.itens?" · "+P.itens.length+" itens":"")+". Publicado para todos do setor.";
    if(m)m.textContent=msg;toast("Planilha da cesta importada.");cbBasesPaint();if($("v-cesta")&&!$("v-cesta").hidden)cbPaint();}
  catch(e){if(m)m.textContent="Não importou: "+(e.message||e);toast("Não importou: "+(e.message||e));}}
function cbBasesPaint(){const s=$("bcb-src");if(!s||!CB.d)return;s.textContent=CB.d.cestas&&CB.d.cestas.imp?"Última importação: "+CB.d.cestas.imp+(CB.d.cestas.por?" · "+CB.d.cestas.por:""):"Nenhum arquivo importado";}
/* foto da tabela de itens (OCR) */
function cbOcr(text){const out=[];text.split(/\n+/).forEach(line=>{let s=line.replace(/R\s*\$|R\s*S(?=\s|\d)/gi," ").replace(/[|\[\]{}“”"'_]/g," ").replace(/\s+/g," ").trim();const tk=s.split(" ");if(!/^\d{3,7}$/.test(tk[0]))return;const nums=[];while(tk.length>2&&nums.length<3&&/^[\d.,]+$/.test(tk[tk.length-1]))nums.unshift(tk.pop());if(nums.length<2)return;const codigo=tk.shift(),descricao=tk.join(" ").trim(),quantidade=Math.round(cbNum(nums[0])||0),total=nums.length===3?cbNum(nums[2]):cbNum(nums[1]);out.push({codigo,descricao,quantidade,total:total||0});});return out;}
async function cbFoto(file){const m=$("bcb-msg");if(m)m.textContent="Lendo a foto dos itens… (pode levar alguns segundos)";try{await cbLoad();if(!window.Tesseract)await loadScript("https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js");const r=await Tesseract.recognize(file,"por");const L=cbOcr(r.data.text);if(m)m.textContent=L.length?"Li "+L.length+" item(ns): confira antes de salvar.":"Não consegui ler itens nessa foto: ajuste à mão.";cbItensDlg(L.length?L:cbViv("itens").map(i=>Object.assign({},i)),!L.length);}catch(e){if(m)m.textContent="Não li a foto: "+(e.message||e);}}
function cbItensDlg(L,vazio){const ov=document.createElement("div");ov.className="pcg-ov";const row=i=>'<tr><td><input class="pcg-in" data-f="codigo" value="'+esc(i.codigo)+'" style="width:90px"></td><td><input class="pcg-in" data-f="descricao" value="'+esc(i.descricao)+'" style="min-width:240px"></td><td><input class="pcg-in" data-f="quantidade" value="'+cbF(i.quantidade)+'" style="width:100px;text-align:right"></td><td><input class="pcg-in" data-f="total" value="'+cbF(i.total,2)+'" style="width:120px;text-align:right"></td><td><button type="button" class="pcg-x" data-rm aria-label="Remover linha">✕</button></td></tr>';
  ov.innerHTML='<div class="pcg-dlg" role="dialog" aria-modal="true" aria-labelledby="cb-it-t" style="width:min(900px,100%)"><header><div><h3 id="cb-it-t">Confira os itens lidos da foto</h3><p class="pcg-dp">'+(vazio?"A leitura não encontrou itens: ajuste os valores abaixo.":"A leitura pode errar números: confira antes de salvar.")+'</p></div><button type="button" class="pcg-dx" data-x aria-label="Fechar">×</button></header><div class="pcg-db" style="display:block"><div class="cv-tw"><table class="pcg-t"><thead><tr><th>Código</th><th>Descrição</th><th>Quantidade</th><th>Vlr. total</th><th></th></tr></thead><tbody>'+L.map(row).join("")+'</tbody></table></div><button type="button" class="btn sm" data-add style="margin-top:8px">+ Linha</button></div><footer><label class="pcg-sm"><input type="checkbox" data-keep checked> Manter os itens que não estão na foto</label><span></span><button type="button" class="btn sm" data-x>Cancelar</button><button type="button" class="save pcg-bt" data-ok>Salvar itens</button></footer></div>';
  document.body.appendChild(ov);const tb=ov.querySelector("tbody");ov.addEventListener("click",async e=>{if(e.target.closest("[data-x]")){ov.remove();return;}if(e.target.closest("[data-rm]")){e.target.closest("tr").remove();return;}if(e.target.closest("[data-add]")){tb.insertAdjacentHTML("beforeend",row({codigo:"",descricao:"",quantidade:0,total:0}));return;}
    if(e.target.closest("[data-ok]")){const N=[...tb.querySelectorAll("tr")].map(tr=>{const g=f=>tr.querySelector('[data-f="'+f+'"]').value;return {codigo:g("codigo").trim(),descricao:g("descricao").trim().toUpperCase(),quantidade:Math.round(cbNum(g("quantidade"))||0),total:cbNum(g("total"))||0};}).filter(i=>i.codigo&&i.descricao);if(!N.length){toast("Nenhum item válido.");return;}
      const t=Date.now();if(!ov.querySelector("[data-keep]").checked)Object.values(CB.d.itens).forEach(i=>{if(!N.some(n=>n.codigo===i.codigo))CB.d.itens[i.codigo]=Object.assign({},i,{del:1,t});});N.forEach(i=>{CB.d.itens[i.codigo]=Object.assign({},i,{t});});await cbGuarda();ov.remove();toast(N.length+" itens salvos.");if($("v-cesta")&&!$("v-cesta").hidden){CB.tab="itens";cbPaint();}}});}
/* ---------- cálculos ---------- */
function cbTrend(ys){const n=ys.length;if(n<2)return {pct:0,cls:"flat",label:"Estável"};const xm=(n-1)/2,ym=cbSum(ys)/n;let a=0,b=0;ys.forEach((y,x)=>{a+=(x-xm)*(y-ym);b+=(x-xm)**2;});const pct=ym?(b?a/b:0)/ym:0,cls=pct>0.05?"up":pct<-0.05?"down":"flat";return {pct,cls,label:cls==="up"?"Em alta":cls==="down"?"Em queda":"Estável"};}
const cbSt=d=>d==null?{c:"#B45309",l:"Sem venda"}:d<=15?{c:"#DC2626",l:"Crítico"}:d<=30?{c:"#F59E0B",l:"Atenção"}:{c:"#16A34A",l:"Confortável"};
const cbCorDias=d=>d==null?"#94A3B8":d<7?"#DC2626":d<15?"#F97316":d<30?"#F59E0B":"#16A34A";
function cbAn(k){const c=CB.d.cestas.data[k];if(!c||!c.filiais||!c.filiais.length)return null;const labels=c.meses&&c.meses.length?c.meses:(c.filiais[0].meses||[]).map((_,i)=>"Mês "+(i+1)),cd=c.filiais.find(cbCD);
  const lojas=c.filiais.filter(f=>!cbCD(f)).map(f=>{const tot=cbSum(f.meses),avg=tot/(f.meses.length||1);return Object.assign({},f,{nome:cbLoja(f.filial),avg,trend:cbTrend(f.meses),dias:avg?f.disponivel/avg*30:null});});
  const totMes=labels.map((_,i)=>cbSum(lojas.map(f=>f.meses[i]))),media=cbSum(totMes)/(labels.length||1),est=cd?(cd.fisico!=null?cd.fisico:cd.disponivel):0,dias=cd&&media?est/media*30:null;
  return {k,c,labels,cd,lojas,ranking:lojas.slice().sort((a,b)=>b.avg-a.avg),totMes,media,est,disp:cd?cd.disponivel:0,dias,st:cd?cbSt(dias):{c:"#B45309",l:"CD não encontrado"},valor:cd?est*(cd.vlr||0):0,trend:cbTrend(totMes),vendaMes:cbSum(lojas.map(f=>f.vendaMes||0)),estLojas:cbSum(lojas.map(f=>f.disponivel))};}
const cbKeys=()=>Object.keys((CB.d.cestas&&CB.d.cestas.data)||{}).filter(k=>cbAn(k)).sort((a,b)=>a-b);
const cbProd=()=>cbViv("prod").sort((a,b)=>String(a.data).localeCompare(String(b.data)));
const cbMult=k=>{const L=cbProd().filter(p=>p.key===k&&p.multiplo);return L.length?L[L.length-1].multiplo:k==="15"?56:60;};
const cbComp=(cod,k)=>{const c=CB.d.comp[cod];return c&&!c.del&&c[k]!=null?+c[k]:1;};
function cbItens(){const ks=cbKeys(),v={};ks.forEach(k=>{v[k]=cbAn(k).media;});const lim=+CB.d.cfg.limItem||30;
  return {v,ks,L:cbViv("itens").map(i=>{const consumo=cbSum(ks.map(k=>cbComp(i.codigo,k)*v[k])),dias=consumo?i.quantidade/consumo*30:null;return Object.assign({},i,{consumo,dias,unit:i.quantidade?i.total/i.quantidade:0,baixo:dias!=null&&dias<lim,atencao:dias!=null&&dias>=lim&&dias<lim*1.5});})};}
function cbFerias(ym,mat){const f=CB.d.fer[ym+"|"+mat];if(f&&!f.del)return f.v?"manual":"";let ch=false;try{ch=(CE.cha||[]).some(r=>r.Matricula===mat&&CE_LAB2K[r.Status]==="ferias"&&ceIso(r.Data).slice(0,7)===ym);}catch(e){}return ch?"chamada":"";}
function cbCom(ym){const no=d=>ym==="todos"||String(d).startsWith(ym),P=cbProd().filter(p=>no(p.data)),pal=cbSum(P.map(p=>p.paletes)),R=cbViv("rem").filter(r=>no(r.data)).sort((a,b)=>a.data.localeCompare(b.data)),vr=+CB.d.cfg.valorRemonte||0;
  const L=cbViv("colab").sort((a,b)=>a.nome.localeCompare(b.nome)).map(c=>{const fe=ym==="todos"?"":cbFerias(ym,c.mat),p=fe?0:pal,nR=R.filter(r=>r.ids.includes(c.mat)).length;return Object.assign({},c,{fe,pal:p,vPal:p*(+c.porPalete||0),nRem:nR,vRem:nR*vr,total:p*(+c.porPalete||0)+nR*vr});});
  return {P,pal,R,L,vr,totPal:cbSum(L.map(l=>l.vPal)),totRem:cbSum(L.map(l=>l.vRem)),total:cbSum(L.map(l=>l.total))};}
/* ---------- gráficos ---------- */
function cbBars(labels,S,o){o=o||{};const W=o.w||640,H=o.h||250,pl=44,pr=10,pt=26,pb=34,n=labels.length,mx=rzNice(Math.max(1,...S.flatMap(s=>s.v.map(x=>+x||0)))*1.1).top,bw=(W-pl-pr)/n,g=bw*0.78/S.length,fm=o.money?rzK:cvFmt;
  let s='<svg class="rz-svg" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="xMidYMid meet">';[0,.5,1].forEach(f=>{const y=H-pb-(H-pt-pb)*f;s+='<line x1="'+pl+'" x2="'+(W-pr)+'" y1="'+y+'" y2="'+y+'" stroke="var(--line)"/><text x="'+(pl-6)+'" y="'+(y+4)+'" text-anchor="end" class="rz-ax">'+fm(mx*f)+'</text>';});
  labels.forEach((l,i)=>{const x0=pl+i*bw+bw*0.11;S.forEach((se,j)=>{const v=+se.v[i]||0,h=(H-pt-pb)*v/mx,x=x0+j*g,y=H-pb-h;s+='<rect class="rz-hd" x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+(g*0.92).toFixed(1)+'" height="'+Math.max(0,h).toFixed(1)+'" rx="3" fill="'+se.c+'"'+(se.op?' opacity="'+se.op+'"':'')+' data-rztip="'+esc(l+" · "+se.n+": "+(o.money?BRL.format(v):cvFmt(v)+(o.un||"")))+'"/>';if(v&&(S.length*n<=24))s+='<text x="'+(x+g*0.46).toFixed(1)+'" y="'+(y-4).toFixed(1)+'" text-anchor="middle" class="cb-lb">'+fm(v)+'</text>';});
    s+='<text x="'+(pl+i*bw+bw/2).toFixed(1)+'" y="'+(H-12)+'" text-anchor="middle" class="rz-ax">'+esc(l)+'</text>';});
  return s+'</svg>'+(S.length>1?'<p class="pcg-lg">'+S.map(se=>'<i style="background:'+se.c+'"></i>'+esc(se.n)).join(" ")+'</p>':'');}
/* ---------- telas ---------- */
const CB_TABS=[["geral","Visão geral"],["lojas","Lojas e pedido"],["prod","Produção"],["itens","Itens"],["com","Comissão"]];
function cbHero(a){const t=a.trend;return '<div class="cb-hero" style="--c:'+cbCor(a.k)+'"><div class="cb-hh"><b>Cesta '+a.k+' itens</b><span>cód. '+esc(a.c.codigo||"–")+'</span></div><div class="cb-hb"><div class="cb-big"><span>Estoque no CD</span><b>'+cbF(a.est)+'</b><small>'+(a.disp!==a.est?cbF(a.disp)+' disponíveis · ':'')+rzBRL(a.valor)+'</small></div>'+
  '<div class="cb-cob" style="--s:'+a.st.c+'"><span>Cobertura</span><b>'+(a.dias==null?"–":cbF(a.dias)+" dias")+'</b><em>'+a.st.l+'</em></div></div><div class="cb-hf"><div><span>Lojas vendem/mês</span><b>'+cbF(a.media)+'</b></div><div><span>Tendência</span><b class="cb-t-'+t.cls+'">'+(t.cls==="up"?"▲":t.cls==="down"?"▼":"■")+' '+(t.pct>0?"+":"")+cbF(t.pct*100,1)+'%</b></div><div><span>Mês atual</span><b>'+cbF(a.vendaMes)+'</b></div><div><span>Estoque nas lojas</span><b>'+cbF(a.estLojas)+'</b></div></div></div>';}
function cbVGeral(){const ks=cbKeys(),A=ks.map(cbAn);if(!A.length)return '<div class="block"><p class="note">Importe a planilha da cesta em <b>Bases e planilhas</b>.</p></div>';
  const ym=CB.mes,C=cbCom(ym),I=cbItens(),crit=I.L.filter(i=>i.baixo).sort((a,b)=>a.dias-b.dias),Pm=cbProd().filter(p=>p.data.startsWith(ym));
  let h='<div class="cb-heros">'+A.map(cbHero).join("")+'</div>';
  h+='<div class="cv-kpis pcg-kp">'+[["Produção em "+cbMesTxt(ym),cbF(cbSum(Pm.map(p=>p.quantidade)))+" cestas","#103F79",cbF(cbSum(Pm.map(p=>p.paletes)))+" paletes · "+rzBRL(cbSum(Pm.map(p=>p.valor)))],["Comissão do mês",BRL.format(C.total),"#16A34A",C.L.filter(l=>l.total).length+" colaborador(es)"],["Itens abaixo de "+(CB.d.cfg.limItem||30)+" dias",cbF(crit.length),crit.length?"#DC2626":"#16A34A",crit.length?crit.slice(0,3).map(i=>i.descricao.split(" ")[0]).join(", "):"todos cobertos"],["Acaba primeiro",crit.length||I.L.length?(()=>{const p=I.L.filter(i=>i.dias!=null).sort((a,b)=>a.dias-b.dias)[0];return p?cbF(p.dias)+" dias":"–";})():"–","#B45309",(I.L.filter(i=>i.dias!=null).sort((a,b)=>a.dias-b.dias)[0]||{}).descricao||""]].map(([t,v,c,s])=>'<div class="cv-k"><span>'+t+'</span><b style="color:'+c+'">'+v+'</b>'+(s?'<small class="muted">'+esc(s)+'</small>':'')+'</div>').join("")+'</div>';
  const lab=A[0].labels.concat(["Mês atual"]);h+='<div class="rz-two"><div class="block"><h3>Vendas das lojas por mês <small>· sem o CD</small></h3>'+cbBars(lab,A.map(a=>({n:"Cesta "+a.k,c:cbCor(a.k),v:a.totMes.concat([a.vendaMes])})),{un:" cestas"})+'</div>';
  const meses=[...new Set(cbProd().map(p=>p.data.slice(0,7)))].sort().slice(-6);h+='<div class="block"><h3>Produção por mês <small>· cestas</small></h3>'+(meses.length?cbBars(meses.map(m=>cbMesTxt(m).replace(/^(\w{3})\w*/,"$1")),ks.map(k=>({n:"Cesta "+k,c:cbCor(k),v:meses.map(m=>cbSum(cbProd().filter(p=>p.key===k&&p.data.startsWith(m)).map(p=>p.quantidade)))})),{un:" cestas"}):'<p class="note">Sem produção lançada.</p>')+'</div></div>';
  /* estoque nas lojas (quantidade) */
  const lojas=[...new Set(A.flatMap(a=>a.lojas.map(f=>f.nome)))].sort();
  h+='<div class="block"><h3>Estoque nas lojas <small>· quantidade de cestas em estoque em cada loja</small></h3><div class="cb-heat" style="grid-template-columns:150px repeat('+(lojas.length+1)+',minmax(70px,1fr))"><div></div>'+lojas.map(l=>'<div class="cb-hl">'+esc(l)+'</div>').join("")+'<div class="cb-hl">TOTAL</div>'+
    A.map(a=>'<div class="cb-hk" style="--c:'+cbCor(a.k)+'">Cesta '+a.k+'</div>'+lojas.map(l=>{const f=a.lojas.find(x=>x.nome===l);if(!f)return '<div class="cb-hc vz">–</div>';return '<div class="cb-hc rz-hd" style="--c:'+cbCor(a.k)+'" data-rztip="'+esc(l+" · cesta "+a.k+" · estoque "+cbF(f.disponivel)+" un")+'"><b>'+cbF(f.disponivel)+'</b><small>un</small></div>';}).join("")+'<div class="cb-hc cb-ht" style="--c:'+cbCor(a.k)+'"><b>'+cbF(a.estLojas)+'</b><small>un</small></div>').join("")+'</div></div>';
  h+='<div class="rz-two">'+A.map(a=>'<div class="block"><h3>Ranking das lojas · cesta '+a.k+' <small>· venda média por mês</small></h3>'+rzSvgCols(a.ranking.map((f,i)=>({l:f.nome.length>10?f.nome.slice(0,9)+"…":f.nome,v:Math.round(f.avg),lb:cbF(f.avg),c:i===0?"#16A34A":i===a.ranking.length-1?"#94A3B8":cbCor(a.k),t:f.nome+" · média "+cbF(f.avg)+"/mês · "+f.meses.map((v,j)=>a.labels[j]+": "+cbF(v)).join(" · ")+" · estoque "+cbF(f.disponivel)})),{h:250,w:560,todos:true,norot:true,pb:40})+'</div>').join("")+'</div>';
  return h;}
function cbVLojas(){const ks=cbKeys(),alvo=+CB.d.cfg.diasAlvo||30,ed=cbPode();
  let h='<div class="block pcg-hh"><div><h3 style="margin:0">Pedido das lojas</h3><p class="pcg-sm" style="margin:2px 0 0">Sugestão = o que falta para cada loja ter '+alvo+' dias de venda. Paletes = estoque depois do pedido ÷ cestas por palete.</p></div><div class="pcg-ctl"><label class="pcg-sm">Dias de cobertura <input class="pcg-in" id="cb-alvo" type="number" min="1" max="120" value="'+alvo+'" style="width:80px"'+(ed?'':' disabled')+'></label></div></div>';
  ks.forEach(k=>{const a=cbAn(k),mu=cbMult(k);let tp=0,tq=0,ts=0;const rows=a.lojas.slice().sort((x,y)=>x.nome.localeCompare(y.nome)).map(f=>{const pk=k+"|"+f.nome,pd=CB.d.ped[pk],q=pd&&!pd.del?+pd.q||0:0,sug=Math.max(0,Math.ceil(f.avg*alvo/30-f.disponivel)),pos=f.disponivel+q,pal=pos/mu;tp+=pal;tq+=q;ts+=sug;
      return '<tr><td><b>'+esc(f.nome)+'</b></td><td class="n">'+cbF(f.disponivel)+'</td>'+f.meses.map(v=>'<td class="n">'+cbF(v)+'</td>').join("")+'<td class="n">'+cbF(f.avg)+'</td><td class="n">'+cbF(f.vendaMes)+'</td><td class="cb-t-'+f.trend.cls+'">'+(f.trend.cls==="up"?"▲":f.trend.cls==="down"?"▼":"■")+' '+(f.trend.pct>0?"+":"")+cbF(f.trend.pct*100,1)+'%</td><td><span class="cb-dc" style="--c:'+cbCorDias(f.dias)+'">'+(f.dias==null?"–":cbF(f.dias)+" d")+'</span></td><td class="n">'+(sug?'<button type="button" class="link" data-cbsug="'+esc(pk)+'" data-q="'+sug+'"'+(ed?'':' disabled')+'>'+cbF(sug)+'</button>':'—')+'</td><td><input class="pcg-in cb-qi" data-cbped="'+esc(pk)+'" inputmode="numeric" value="'+(q||"")+'" placeholder="0"'+(ed?'':' disabled')+'></td><td class="n"><b>'+cbF(pos)+'</b></td><td class="n">'+cbF(pal,2)+'</td></tr>';}).join("");
    h+='<div class="block"><div class="pcg-hh"><h3 style="margin:0;color:'+cbCor(k)+'">Cesta '+k+' itens <small>· '+mu+' cestas por palete</small></h3>'+(ed?'<button type="button" class="btn sm" data-cbsugall="'+k+'">Usar todas as sugestões</button>':'')+'</div><div class="cv-tw"><table class="pcg-t"><thead><tr><th>Loja</th><th>Estoque</th>'+a.labels.map(l=>'<th>'+esc(l)+'</th>').join("")+'<th>Média/mês</th><th>Mês atual</th><th>Tendência</th><th>Cobertura</th><th>Sugestão</th><th>Qtd. pedido</th><th>Pós pedido</th><th>Paletes</th></tr></thead><tbody>'+rows+'</tbody><tfoot><tr><td><b>Total</b></td><td class="n">'+cbF(a.estLojas)+'</td>'+a.totMes.map(v=>'<td class="n">'+cbF(v)+'</td>').join("")+'<td class="n">'+cbF(a.media)+'</td><td class="n">'+cbF(a.vendaMes)+'</td><td></td><td></td><td class="n">'+cbF(ts)+'</td><td class="n"><b>'+cbF(tq)+'</b></td><td class="n">'+cbF(a.estLojas+tq)+'</td><td class="n"><b>'+cbF(tp,2)+'</b></td></tr></tfoot></table></div>'+
      '<p class="pcg-sm">CD '+esc(a.cd?cbLoja(a.cd.filial):"STA")+': '+cbF(a.est)+' cestas'+(a.disp!==a.est?' ('+cbF(a.disp)+' disponíveis)':'')+' · pedido total '+cbF(tq)+' · '+(tq>a.est?'<b style="color:#DC2626">pedido maior que o estoque do CD</b>':'sobram '+cbF(a.est-tq)+' no CD')+'</p></div>';});
  return h;}
function cbVProd(){const ks=cbKeys().length?cbKeys():["10","15"],ed=cbPode(),P=cbProd(),ym=CB.mes,meses=[...new Set(P.map(p=>p.data.slice(0,7)))].sort(),PM=ym==="todos"?P:P.filter(p=>p.data.startsWith(ym));
  let h='<div class="block pcg-hh"><div class="pcg-ctl"><span class="pcg-sm">Mês</span><select class="pcg-in" id="cb-mes">'+meses.concat(meses.includes(cbHoje().slice(0,7))?[]:[cbHoje().slice(0,7)]).sort().map(m=>'<option value="'+m+'"'+(m===ym?' selected':'')+'>'+cbMesTxt(m)+'</option>').join("")+'<option value="todos"'+(ym==="todos"?' selected':'')+'>Todo o período</option></select></div>'+(ed?'<div class="pcg-ctl cb-novo"><select class="pcg-in" id="cb-pk">'+ks.map(k=>'<option value="'+k+'">Cesta '+k+'</option>').join("")+'</select><input class="pcg-in" type="date" id="cb-pd" value="'+cbHoje()+'"><input class="pcg-in" id="cb-pp" inputmode="numeric" placeholder="Paletes" style="width:90px"><input class="pcg-in" id="cb-pm" inputmode="numeric" placeholder="Cestas/palete" style="width:120px" value="'+cbMult(ks[0])+'"><button type="button" class="save pcg-bt" data-cba="lote">+ Lançar lote</button></div>':'')+'</div>';
  h+='<div class="cv-kpis pcg-kp">'+ks.map(k=>{const L=PM.filter(p=>p.key===k);return '<div class="cv-k" style="border-top:4px solid '+cbCor(k)+'"><span>Cesta '+k+' · '+cbMesTxt(ym)+'</span><b style="color:'+cbCor(k)+'">'+cbF(cbSum(L.map(p=>p.quantidade)))+' cestas</b><small class="muted">'+cbF(cbSum(L.map(p=>p.paletes)))+' paletes · '+L.length+' lote(s) · '+rzBRL(cbSum(L.map(p=>p.valor)))+'</small></div>';}).join("")+'<div class="cv-k"><span>Total de paletes</span><b style="color:#103F79">'+cbF(cbSum(PM.map(p=>p.paletes)))+'</b><small class="muted">base da comissão</small></div></div>';
  const dias=[...new Set(PM.map(p=>p.data))].sort();if(dias.length)h+='<div class="block"><h3>Paletes por dia</h3>'+cbBars(dias.map(d=>d.slice(8)+"/"+d.slice(5,7)),ks.map(k=>({n:"Cesta "+k,c:cbCor(k),v:dias.map(d=>cbSum(PM.filter(p=>p.key===k&&p.data===d).map(p=>p.paletes)))})),{w:900,h:240,un:" paletes"})+'</div>';
  h+='<div class="block"><h3>Lotes de produção <small>· '+PM.length+(ed?' · edite direto na tabela':'')+'</small></h3><div class="cv-tw" style="max-height:560px"><table class="pcg-t"><thead><tr><th>Cesta</th><th>Data</th><th>Paletes</th><th>Cestas/palete</th><th>Quantidade</th><th>Valor</th><th>Origem</th><th></th></tr></thead><tbody>'+
    (PM.length?PM.slice().reverse().map(p=>{const dif=p.paletes&&p.multiplo&&Math.abs(p.paletes*p.multiplo-p.quantidade)>0.5;return '<tr data-cbl="'+esc(p.id)+'"><td><span class="cb-k" style="--c:'+cbCor(p.key)+'">'+p.key+'</span></td><td>'+(ed?'<input class="pcg-in" type="date" data-f="data" value="'+esc(p.data)+'">':cbBr(p.data))+'</td><td>'+(ed?'<input class="pcg-in cb-qi" data-f="paletes" inputmode="numeric" value="'+cbF(p.paletes)+'">':cbF(p.paletes))+'</td><td>'+(ed?'<input class="pcg-in cb-qi" data-f="multiplo" inputmode="numeric" value="'+cbF(p.multiplo)+'">':cbF(p.multiplo))+'</td><td class="n">'+cbF(p.quantidade)+(dif?' <span class="cb-warn" title="Paletes × cestas por palete = '+cbF(p.paletes*p.multiplo)+'">⚠</span>':'')+'</td><td class="n">'+BRL.format(+p.valor||0)+'</td><td class="pcg-sm">'+(p.src==="imp"?"planilha":"lançado")+(p.por?" · "+esc(curto(p.por)):"")+'</td><td>'+(ed?'<button type="button" class="pcg-x" data-cbdl="'+esc(p.id)+'" aria-label="Excluir lote">✕</button>':'')+'</td></tr>';}).join(""):'<tr><td colspan="8" class="pcg-sm">Sem lotes neste mês.</td></tr>')+'</tbody></table></div><p class="pcg-sm">⚠ = a quantidade da planilha não bate com paletes × cestas por palete. Ao mudar paletes ou cestas por palete, a quantidade e o valor são recalculados.</p></div>';
  return h;}
function cbVItens(){const I=cbItens(),ed=cbPode(),lim=+CB.d.cfg.limItem||30,o=CB.sort,K={codigo:i=>+i.codigo||0,descricao:i=>i.descricao,quantidade:i=>i.quantidade,consumo:i=>i.consumo,dias:i=>i.dias==null?1e12:i.dias,unit:i=>i.unit,total:i=>i.total},f=K[o.c]||K.dias;
  const L=I.L.slice().sort((a,b)=>{const x=f(a),y=f(b);return (typeof x==="string"?x.localeCompare(y,"pt-BR"):x-y)*o.d;}),tv=cbSum(L.map(i=>i.total)),bx=L.filter(i=>i.baixo);
  const th=(k,t)=>'<th class="cv-th'+(o.c===k?" on":"")+'" data-cbs="'+k+'">'+t+'<i>'+(o.c===k?(o.d>0?"▲":"▼"):"⇅")+'</i></th>';
  let h='<div class="cv-kpis pcg-kp">'+[["Abaixo de "+lim+" dias",bx.length+" item(ns)",bx.length?"#DC2626":"#16A34A",bx.map(i=>i.descricao.split(" ")[0]).join(", ")||"todos acima"],["Ritmo de venda usado",I.ks.map(k=>cbF(I.v[k])).join(" + "),"#103F79","cestas/mês ("+I.ks.map(k=>k+" itens").join(" + ")+")"],["Valor em estoque",rzBRL(tv),"#16A34A",L.length+" itens · último custo de entrada"]].map(([t,v,c,s])=>'<div class="cv-k"><span>'+t+'</span><b style="color:'+c+'">'+v+'</b><small class="muted">'+esc(s)+'</small></div>').join("")+'</div>';
  h+='<div class="block"><div class="pcg-hh"><h3 style="margin:0">Itens da cesta <small>· estoque, unidades por cesta e dias de estoque'+(ed?' · edite direto na tabela':'')+'</small></h3><div class="pcg-ctl"><label class="pcg-sm">Alerta abaixo de <input class="pcg-in" id="cb-lim" type="number" min="1" value="'+lim+'" style="width:70px"'+(ed?'':' disabled')+'> dias</label>'+(ed?'<button type="button" class="btn sm" data-cba="item">+ Item</button>':'')+'</div></div><div class="cv-tw"><table class="pcg-t"><thead><tr>'+th("codigo","Código")+th("descricao","Descrição")+th("quantidade","Estoque (un)")+I.ks.map(k=>'<th>Un. cesta '+k+'</th>').join("")+th("consumo","Consumo/mês")+th("dias","Dias de estoque")+th("unit","Custo un.")+th("total","Valor total")+(ed?'<th></th>':'')+'</tr></thead><tbody>'+
    L.map(i=>'<tr data-cbi="'+esc(i.codigo)+'"'+(i.baixo?' class="cb-crit"':'')+'><td><b>'+esc(i.codigo)+'</b></td><td class="cvl-td">'+(ed?'<input class="pcg-in" data-f="descricao" value="'+esc(i.descricao)+'" style="min-width:220px">':esc(i.descricao))+'</td><td>'+(ed?'<input class="pcg-in cb-qi" data-f="quantidade" inputmode="numeric" value="'+cbF(i.quantidade)+'" style="width:100px">':cbF(i.quantidade))+'</td>'+I.ks.map(k=>'<td>'+(ed?'<input class="pcg-in cb-qi" data-comp="'+k+'" inputmode="numeric" value="'+cbComp(i.codigo,k)+'" style="width:60px">':cbComp(i.codigo,k))+'</td>').join("")+'<td class="n">'+cbF(i.consumo)+'</td><td><span class="cb-dc" style="--c:'+(i.baixo?"#DC2626":i.atencao?"#F59E0B":"#16A34A")+'">'+(i.dias==null?"–":cbF(i.dias)+" dias")+'</span></td><td class="n">'+BRL.format(i.unit)+'</td><td>'+(ed?'<input class="pcg-in pcg-money" data-f="total" inputmode="decimal" value="'+BRL.format(i.total)+'" style="width:130px">':BRL.format(i.total))+'</td>'+(ed?'<td><button type="button" class="pcg-x" data-cbdi="'+esc(i.codigo)+'" aria-label="Excluir item">✕</button></td>':'')+'</tr>').join("")+'</tbody></table></div><p class="pcg-sm">Dias de estoque = estoque do item ÷ consumo mensal × 30. Consumo = venda média das lojas × unidades do item em cada cesta (0 = o item não vai naquela cesta).</p></div>';
  return h;}
function cbVCom(){const ym=CB.mes,C=cbCom(ym),ed=cbPode(),meses=[...new Set(cbProd().map(p=>p.data.slice(0,7)).concat(cbViv("rem").map(r=>r.data.slice(0,7))).concat([cbHoje().slice(0,7)]))].sort();
  let h='<div class="block pcg-hh"><div class="pcg-ctl"><span class="pcg-sm">Mês</span><select class="pcg-in" id="cb-mes">'+meses.map(m=>'<option value="'+m+'"'+(m===ym?' selected':'')+'>'+cbMesTxt(m)+'</option>').join("")+'<option value="todos"'+(ym==="todos"?' selected':'')+'>Todo o período</option></select></div><div class="pcg-ctl"><label class="pcg-sm">Remonte por dia <input class="pcg-in pcg-money" id="cb-vr" inputmode="decimal" value="'+BRL.format(C.vr)+'" style="width:120px"'+(ed?'':' disabled')+'></label></div></div>';
  h+='<div class="cv-kpis pcg-kp">'+[["Paletes produzidos",cbF(C.pal),"#103F79",new Set(C.P.map(p=>p.data)).size+" dia(s) de produção"],["Comissão de paletes",BRL.format(C.totPal),"#0369A1","colaboradores ativos"],["Remontes",BRL.format(C.totRem),"#B45309",C.R.length+" dia(s) × "+BRL.format(C.vr)],["Total a pagar",BRL.format(C.total),"#16A34A",cbMesTxt(ym)]].map(([t,v,c,s])=>'<div class="cv-k"><span>'+t+'</span><b style="color:'+c+'">'+v+'</b><small class="muted">'+esc(s)+'</small></div>').join("")+'</div>';
  h+='<div class="block"><div class="pcg-hh"><h3 style="margin:0">Comissão dos colaboradores</h3>'+(ed?'<div class="pcg-ctl"><input class="pcg-in" id="cb-cm" inputmode="numeric" placeholder="Matrícula" style="width:120px"><input class="pcg-in" id="cb-cn" placeholder="Nome (vem da matrícula)" style="min-width:240px"><input class="pcg-in pcg-money" id="cb-cv" inputmode="decimal" placeholder="R$/palete" style="width:110px"><button type="button" class="save pcg-bt" data-cba="colab">+ Colaborador</button></div>':'')+'</div><div class="cv-tw"><table class="pcg-t"><thead><tr><th>Colaborador</th><th>Situação no mês</th><th>R$ por palete</th><th>Paletes</th><th>Valor paletes</th><th>Remontes</th><th>Valor remonte</th><th>Total</th>'+(ed?'<th></th>':'')+'</tr></thead><tbody>'+
    (C.L.length?C.L.map(l=>'<tr data-cbc="'+esc(l.mat)+'"'+(l.fe?' class="cb-off"':'')+'><td><b>'+esc(l.nome)+'</b><br><small class="pcg-sm">matrícula '+esc(l.mat)+'</small></td><td>'+(ym==="todos"?'—':'<button type="button" class="cb-stb'+(l.fe?' fe':'')+'" data-cbfe="'+esc(l.mat)+'"'+(ed&&l.fe!=="chamada"?'':' disabled')+' title="'+(l.fe==="chamada"?'Férias registrada na chamada':'Clique para alternar')+'">'+(l.fe?'Férias'+(l.fe==="chamada"?' (chamada)':''):'Ativo')+'</button>')+'</td><td>'+(ed?'<input class="pcg-in pcg-money" data-cbpp="'+esc(l.mat)+'" inputmode="decimal" value="'+BRL.format(+l.porPalete||0)+'" style="width:110px">':BRL.format(+l.porPalete||0))+'</td><td class="n">'+cbF(l.pal)+'</td><td class="n">'+BRL.format(l.vPal)+'</td><td class="n">'+l.nRem+'</td><td class="n">'+BRL.format(l.vRem)+'</td><td class="n"><b style="color:#15803D">'+BRL.format(l.total)+'</b></td>'+(ed?'<td><button type="button" class="pcg-x" data-cbdc="'+esc(l.mat)+'" aria-label="Excluir '+esc(l.nome)+'">✕</button></td>':'')+'</tr>').join(""):'<tr><td colspan="9" class="pcg-sm">Nenhum colaborador cadastrado.</td></tr>')+'</tbody><tfoot><tr><td><b>Total</b></td><td></td><td></td><td class="n">'+cbF(C.pal)+'</td><td class="n">'+BRL.format(C.totPal)+'</td><td></td><td class="n">'+BRL.format(C.totRem)+'</td><td class="n"><b>'+BRL.format(C.total)+'</b></td>'+(ed?'<td></td>':'')+'</tr></tfoot></table></div><p class="pcg-sm">Cada colaborador ativo recebe pelos paletes produzidos no mês (cestas de 10 e 15). Em férias, no mês ou na chamada, não recebe a comissão de paletes.</p></div>';
  const ativos=C.L.filter(l=>!l.fe);h+='<div class="rz-two"><div class="block"><h3>Remonte de cesta básica <small>· '+BRL.format(C.vr)+' por pessoa por dia</small></h3>'+(ed?'<div class="pcg-ctl pcg-fr"><label>Data do remonte<input class="pcg-in" type="date" id="cb-rd" value="'+cbHoje()+'"></label></div><div class="cb-chk">'+cbViv("colab").sort((a,b)=>a.nome.localeCompare(b.nome)).map(c=>'<label><input type="checkbox" class="cb-rw" value="'+esc(c.mat)+'"'+(ativos.some(a=>a.mat===c.mat)?' checked':'')+'> '+esc(curto(c.nome))+'</label>').join("")+'</div><button type="button" class="btn" data-cba="rem" style="margin-top:8px">Incluir remonte</button>':'')+
    '<div class="cv-tw" style="margin-top:10px;max-height:300px"><table class="pcg-t"><tbody>'+(C.R.length?C.R.map(r=>'<tr><td>'+cbBr(r.data)+'</td><td class="cvl-td">'+r.ids.map(id=>esc(curto((CB.d.colab[id]||{}).nome||id))).join(", ")+'</td><td class="n">'+BRL.format(r.ids.length*C.vr)+'</td>'+(ed?'<td><button type="button" class="pcg-x" data-cbdr="'+esc(r.id)+'" aria-label="Excluir remonte">✕</button></td>':'')+'</tr>').join(""):'<tr><td class="pcg-sm">Nenhum remonte neste mês.</td></tr>')+'</tbody></table></div></div>';
  const dias=[...new Set(C.P.map(p=>p.data))].sort(),ks=cbKeys();h+='<div class="block"><h3>Paletes por dia de produção</h3><div class="cv-tw" style="max-height:380px"><table class="pcg-t"><thead><tr><th>Data</th>'+ks.map(k=>'<th>Cesta '+k+'</th>').join("")+'<th>Total</th></tr></thead><tbody>'+(dias.length?dias.map(d=>'<tr><td>'+cbBr(d)+'</td>'+ks.map(k=>'<td class="n">'+cbF(cbSum(C.P.filter(p=>p.data===d&&p.key===k).map(p=>p.paletes)))+'</td>').join("")+'<td class="n"><b>'+cbF(cbSum(C.P.filter(p=>p.data===d).map(p=>p.paletes)))+'</b></td></tr>').join(""):'<tr><td class="pcg-sm" colspan="4">Sem produção neste mês.</td></tr>')+'</tbody></table></div></div></div>';
  return h;}
function cbPaint(){const box=$("cb");if(!box||!CB.d)return;const imp=CB.d.cestas&&CB.d.cestas.imp,pb=podeVer("bases");
  let h='<div class="pcg-top"><div class="pcg-tabs" role="tablist">'+CB_TABS.map(([id,l])=>'<button type="button" role="tab" aria-selected="'+(CB.tab===id)+'" data-cbtab="'+id+'"'+(CB.tab===id?' class="on"':'')+'>'+l+'</button>').join("")+'</div><div class="pcg-ctl"><span class="pcg-sm">'+(imp?"Base: "+esc(imp):"")+'</span>'+(cbPode()?'<label class="btn sm cb-up">Importar planilha<input type="file" id="cb-imp" accept=".xlsx,.xls" hidden></label><label class="btn sm cb-up">Foto dos itens<input type="file" id="cb-impf" accept="image/*" hidden></label>':'')+(pb?'<button type="button" class="btn sm" data-cvgo="bases">Bases e planilhas →</button>':'')+'<button type="button" class="btn sm" data-cba="sync">↻ Atualizar</button></div></div>';
  if(!cbPode())h+='<p class="pcg-gs">Você está acompanhando a cesta básica: só o setor altera os dados.</p>';
  h+=({geral:cbVGeral,lojas:cbVLojas,prod:cbVProd,itens:cbVItens,com:cbVCom}[CB.tab]||cbVGeral)();
  const ae=document.activeElement,keep=ae&&ae.id&&box.contains(ae)?ae.id:null;box.innerHTML=h;if(keep&&$(keep))$(keep).focus();}
async function cbAbrir(){await cbLoad();cbPaint();if(await cbSync())cbPaint();clearInterval(CB.tm);CB.tm=setInterval(async()=>{const v=$("v-cesta");if(!v||v.hidden){clearInterval(CB.tm);return;}const ae=document.activeElement;if(document.hidden||(ae&&ae.closest&&ae.closest("#cb")&&/INPUT|SELECT/.test(ae.tagName)))return;if(await cbSync())cbPaint();},45000);}
(function(){const box=$("cb");if(!box)return;
  const upd=async(col,id,patch)=>{const o=Object.assign({},col==="cfg"?CB.d.cfg:CB.d[col][id],patch);delete o.del;await cbSet(col,id,o);};
  box.addEventListener("click",async e=>{const t=e.target.closest("[data-cbtab]");if(t){CB.tab=t.dataset.cbtab;cvTipHide();cbPaint();return;}
    const g=e.target.closest("[data-cvgo]");if(g){go(g.dataset.cvgo);return;}
    const s=e.target.closest("[data-cbs]");if(s){const k=s.dataset.cbs;CB.sort=CB.sort.c===k?{c:k,d:-CB.sort.d}:{c:k,d:["descricao","codigo","dias"].includes(k)?1:-1};cbPaint();return;}
    if(!cbPode())return;
    const sg=e.target.closest("[data-cbsug]");if(sg){await cbSet("ped",sg.dataset.cbsug,{q:+sg.dataset.q});cbPaint();return;}
    const sa=e.target.closest("[data-cbsugall]");if(sa){const k=sa.dataset.cbsugall,a=cbAn(k),alvo=+CB.d.cfg.diasAlvo||30;for(const f of a.lojas){const q=Math.max(0,Math.ceil(f.avg*alvo/30-f.disponivel));CB.d.ped[k+"|"+f.nome]={q,t:Date.now(),por:(LOGIN&&LOGIN.nome)||""};}await cbGuarda();cbPaint();toast("Sugestões aplicadas na cesta "+k+".");return;}
    const fe=e.target.closest("[data-cbfe]");if(fe){const k=CB.mes+"|"+fe.dataset.cbfe,cur=cbFerias(CB.mes,fe.dataset.cbfe);await cbSet("fer",k,{v:cur?0:1});cbPaint();return;}
    const dl=e.target.closest("[data-cbdl]");if(dl){const p=CB.d.prod[dl.dataset.cbdl];if(!p||!confirm("Excluir o lote de "+cbBr(p.data)+" (cesta "+p.key+", "+cbF(p.paletes)+" paletes)?"))return;await cbSet("prod",p.id,Object.assign({},p,{del:1}));cbPaint();return;}
    const di=e.target.closest("[data-cbdi]");if(di){const i=CB.d.itens[di.dataset.cbdi];if(!i||!confirm("Excluir o item "+i.descricao+"?"))return;await cbSet("itens",i.codigo,Object.assign({},i,{del:1}));cbPaint();return;}
    const dc=e.target.closest("[data-cbdc]");if(dc){const c=CB.d.colab[dc.dataset.cbdc];if(!c||!confirm("Excluir "+c.nome+" da comissão da cesta?"))return;await cbSet("colab",c.mat,Object.assign({},c,{del:1}));cbPaint();return;}
    const dr=e.target.closest("[data-cbdr]");if(dr){const r=CB.d.rem[dr.dataset.cbdr];if(!r||!confirm("Excluir o remonte de "+cbBr(r.data)+"?"))return;await cbSet("rem",r.id,Object.assign({},r,{del:1}));cbPaint();return;}
    const a=e.target.closest("[data-cba]");if(!a)return;const ac=a.dataset.cba;
    if(ac==="sync"){a.disabled=true;const ok=await cbSync(true);await cbPub();cbPaint();toast(ok?"Cesta atualizada.":"Cesta já está atualizada.");}
    else if(ac==="lote"){const k=$("cb-pk").value,d=$("cb-pd").value,p=cbNum($("cb-pp").value),mu=cbNum($("cb-pm").value);if(!d||!(p>0)||!(mu>0)){toast("Informe data, paletes e cestas por palete.");return;}const a2=cbAn(k),vu=a2&&a2.cd?a2.cd.vlr||0:0,id=cbId("man-");await cbSet("prod",id,{id,src:"man",key:k,data:d,paletes:p,multiplo:mu,quantidade:p*mu,valor:p*mu*vu});CB.mes=d.slice(0,7);cbPaint();toast("Lote lançado.");}
    else if(ac==="item"){const cod=(prompt("Código do item")||"").trim();if(!cod)return;const ki=pIdx.get(cod.replace(/^0+/,"")),desc=(prompt("Descrição",ki!=null?P.desc[ki]:"")||"").trim().toUpperCase();if(!desc)return;await cbSet("itens",cod,{codigo:cod,descricao:desc,quantidade:0,total:0});cbPaint();}
    else if(ac==="colab"){const mat=($("cb-cm").value||"").replace(/\D/g,""),nome=(($("cb-cn").value||"").trim()||(()=>{try{return ceNomeMat(mat);}catch(x){return "";}})()).toUpperCase(),v=cbNum($("cb-cv").value);if(!mat||!nome||nome===mat){toast("Informe matrícula e nome.");return;}if(CB.d.colab[mat]&&!CB.d.colab[mat].del){toast("Essa matrícula já está na comissão.");return;}if(!(v>=0)){toast("Informe o valor por palete.");return;}await cbSet("colab",mat,{mat,nome,porPalete:v});cbPaint();toast(nome+" incluído.");}
    else if(ac==="rem"){const d=$("cb-rd").value,ids=[...box.querySelectorAll(".cb-rw:checked")].map(x=>x.value);if(!d){toast("Escolha a data.");return;}if(!ids.length){toast("Marque quem trabalhou.");return;}if(cbViv("rem").some(r=>r.data===d)){toast("Já existe remonte em "+cbBr(d)+".");return;}const id=cbId("r");await cbSet("rem",id,{id,data:d,ids});CB.mes=d.slice(0,7);cbPaint();toast("Remonte incluído.");}});
  box.addEventListener("change",async e=>{const t=e.target;
    if(t.id==="cb-mes"){CB.mes=t.value;cbPaint();return;}
    if(t.id==="cb-imp"||t.id==="cb-impf"){const f=t.files[0];t.value="";if(f&&cbPode())(t.id==="cb-imp"?cbImport:cbFoto)(f);return;}
    if(t.id==="cb-pk"){const m=$("cb-pm");if(m)m.value=cbMult(t.value);return;}
    if(!cbPode())return;
    if(t.id==="cb-alvo"){await upd("cfg",0,{diasAlvo:Math.max(1,+t.value||30)});cbPaint();return;}
    if(t.id==="cb-lim"){await upd("cfg",0,{limItem:Math.max(1,+t.value||30)});cbPaint();return;}
    if(t.id==="cb-vr"){await upd("cfg",0,{valorRemonte:cbNum(t.value)||0});cbPaint();return;}
    if(t.dataset.cbped){await cbSet("ped",t.dataset.cbped,{q:Math.max(0,Math.round(cbNum(t.value)||0))});cbPaint();return;}
    if(t.dataset.cbpp){await upd("colab",t.dataset.cbpp,{porPalete:cbNum(t.value)||0});cbPaint();return;}
    const tl=t.closest("[data-cbl]");if(tl){const p=CB.d.prod[tl.dataset.cbl],f=t.dataset.f;if(!p)return;const o=Object.assign({},p);if(f==="data")o.data=t.value;else o[f]=cbNum(t.value)||0;if(f==="paletes"||f==="multiplo"){const vu=o.quantidade?(+o.valor||0)/o.quantidade:0;o.quantidade=o.paletes*o.multiplo;o.valor=o.quantidade*vu;}o.src=o.src||"man";await cbSet("prod",o.id,o);cbPaint();return;}
    const ti=t.closest("[data-cbi]");if(ti){const i=Object.assign({},CB.d.itens[ti.dataset.cbi]);if(t.dataset.comp){const c=Object.assign({},CB.d.comp[i.codigo]||{});delete c.del;c[t.dataset.comp]=Math.max(0,Math.round(cbNum(t.value)||0));await cbSet("comp",i.codigo,c);cbPaint();return;}const f=t.dataset.f;if(f==="descricao")i.descricao=t.value.trim().toUpperCase();else i[f]=cbNum(t.value)||0;await cbSet("itens",i.codigo,i);cbPaint();}});
  box.addEventListener("input",e=>{if(e.target.id==="cb-cm"){const m=e.target.value.replace(/\D/g,""),n=$("cb-cn");if(n&&m.length>=7){let nm="";try{nm=ceNomeMat(m);}catch(x){}if(nm&&nm!==m)n.value=nm;}}});})();
{const i=$("bcb-file");if(i)i.addEventListener("change",e=>{const f=e.target.files[0];e.target.value="";if(f)cbImport(f);});const j=$("bcb-foto");if(j)j.addEventListener("change",e=>{const f=e.target.files[0];e.target.value="";if(f)cbFoto(f);});}
