let vlcEnviando=false;const VH={rows:null,busy:false,msg:"",de:"",ate:"",st:"",q:""};
async function vlcHistCarregar(){if(VH.busy||DEMO||!SHEET_URL)return;if(!navigator.onLine){VH.msg="Sem internet: o histórico aparece quando a conexão voltar.";vlcHist();return;}VH.busy=true;vlcHist();
  try{const j=await ppPost({acao:"vlc_pul_hist"});VH.rows=ceRows(j).filter(r=>r.ID);VH.msg="";}catch(e){VH.msg=/desconhecida|inválida|acao/i.test(e.message)?"Implante o Apps Script versão 52 para ver o histórico de pulados.":e.message;}VH.busy=false;vlcHist();}
function vlcHist(){const box=$("v-phist");if(!box)return;if(VH.rows==null&&!VH.busy&&!VH.msg){vlcHistCarregar();}
  const pend=new Set((VC.itens||[]).map(i=>String(i.id))),L=(VH.rows||[]).filter(r=>{const d=ceIso(r.DataHora);return (!VH.de||d>=VH.de)&&(!VH.ate||d<=VH.ate)&&(!VH.st||r.Status===VH.st)&&(!VH.q||norm([r.Endereco,r.Codigo_Produto,r.Descricao,r.Nome,r.Motivo].join(" ")).includes(norm(VH.q)));}).sort((a,b)=>(rotDt(b.DataHora)||0)-(rotDt(a.DataHora)||0));
  const nP=L.filter(r=>r.Status==="Pulado").length;
  box.innerHTML='<div class="block" style="margin-top:14px"><div class="ce-th"><h3>Histórico de pulados <small>'+L.length+'</small></h3><button type="button" class="btn sm" id="vh-upd"'+(VH.busy?" disabled":"")+'>'+(VH.busy?"Carregando…":"Atualizar")+'</button></div>'+
    '<div class="ce-filters"><label class="ce-fld"><span>De</span><input type="date" id="vh-de" value="'+VH.de+'"></label><label class="ce-fld"><span>Até</span><input type="date" id="vh-ate" value="'+VH.ate+'"></label><label class="ce-fld"><span>Situação</span><select id="vh-st"><option value="">Todas</option><option'+(VH.st==="Pulado"?" selected":"")+'>Pulado</option><option'+(VH.st==="Auditado depois"?" selected":"")+'>Auditado depois</option></select></label><label class="ce-fld grow"><span>Buscar</span><input type="search" id="vh-q" value="'+esc(VH.q)+'" placeholder="Endereço, item, auditor, motivo"></label></div>'+
    (VH.msg?'<p class="note" style="color:#B45309">'+esc(VH.msg)+'</p>':'')+(VH.rows?'<p class="note" style="margin:0 0 8px">'+nP+' ainda pulado(s) · '+(L.length-nP)+' auditado(s) depois</p>':'')+'</div>'+
    L.slice(0,300).map(r=>{const ab=r.Status==="Pulado",pode=ab&&pend.has(String(r.ID_Item));return '<div class="block vl-it"><div class="top"><span>'+esc(r.DataHora)+' · '+esc(curto(r.Nome||r.Matricula||""))+'</span><span class="'+(ab?"ro-no":"ro-ok")+'">'+esc(r.Status)+(r.Vezes>1?" · "+esc(r.Vezes)+"x":"")+'</span></div>'+
      '<div class="addr">'+esc(r.Endereco)+' <small class="muted">'+esc(r.Tipo||"")+' · '+esc(r.Operacao||"")+'</small></div><div class="desc">'+esc(r.Codigo_Produto)+' – '+esc(r.Descricao||"")+'</div><div class="tags"><span class="tag nc">'+esc(r.Motivo||"Sem motivo")+'</span>'+(r.Resolvido_Em?'<span class="tag ok">auditado '+esc(String(r.Resolvido_Em).slice(0,16))+(r.Resolvido_Por?' por '+esc(curto(r.Resolvido_Por)):'')+'</span>':'')+'</div>'+
      (pode?'<div class="vl-b"><button type="button" class="save" data-ph="'+esc(r.ID_Item)+'">Auditar agora</button></div>':'')+'</div>';}).join("");
  const up=()=>{VH.de=$("vh-de").value;VH.ate=$("vh-ate").value;VH.st=$("vh-st").value;VH.q=$("vh-q").value;vlcHist();};["vh-de","vh-ate","vh-st"].forEach(id=>$(id).onchange=up);$("vh-q").onchange=up;
  $("vh-upd").onclick=()=>{VH.rows=null;VH.msg="";vlcHistCarregar();};
  box.querySelectorAll("[data-ph]").forEach(b=>b.onclick=()=>{const i=(VC.itens||[]).find(x=>String(x.id)===b.dataset.ph);if(!i)return;VC.pulInfo[i.id]=VC.pulInfo[i.id]||{m:"",em:"",v:1};VC.pulados.add(String(i.id));VC.soPul=true;VC.pulSessao=new Set();VC.tela="auditar";VC.itens=[i].concat(VC.itens.filter(x=>x!==i));vlcProximo();});}
let vlcDeNovo=false;
async function vlcFlush(silencioso){if(vlcEnviando){vlcDeNovo=true;return 0;}if(DEMO||!SHEET_URL||!LOGIN||!navigator.onLine)return 0;const L=vlcFilaLer();if(!L.length)return 0;vlcEnviando=true;let ok=0,perd=[],div=[];
  const meus=L.filter(x=>x.auditor===auditor);let lote=VLC_LOTE_OK;
  for(let i=0;lote&&i<meus.length;i+=25){const parte=meus.slice(i,i+25);
    try{const j=await ppPost({acao:"vlc_lote",itens:parte.map(x=>{const p=Object.assign({},x);delete p.auditor;delete p.desc;delete p.acao;return p;})});
      if(!Array.isArray(j.resultados))throw new Error("Ação desconhecida (Apps Script antigo)");
      const res=new Map(j.resultados.map(r=>[String(r.idCliente),r]));const tirar=new Set();
      parte.forEach(x=>{const r=res.get(String(x.idCliente));if(!r)return;if(r.ok){ok++;tirar.add(x.idCliente);if(r.divergencia)div.push((x.desc||x.idItem)+": "+r.divergencia);}
        else if(/já foi auditado|não encontrado/i.test(r.erro||"")){perd.push((x.desc||x.idItem)+": "+r.erro);tirar.add(x.idCliente);}});
      vlcFilaGravar(vlcFilaLer().filter(y=>!tirar.has(y.idCliente)));}
    catch(e){if(/desconhecid|Ação|acao/i.test(e.message||"")){lote=false;VLC_LOTE_OK=false;break;}vlcEnviando=false;paintVlcFila();return ok;}}
  if(!lote)for(const x of vlcFilaLer().filter(x=>x.auditor===auditor)){if(x.auditor!==auditor)continue;try{const p=Object.assign({},x);delete p.auditor;delete p.desc;await ppPost(p);ok++;vlcFilaGravar(vlcFilaLer().filter(y=>y.idCliente!==x.idCliente));}
    catch(e){if(e instanceof TypeError||/não respondeu/i.test(e.message))break;
      if(/já foi auditado|não encontrado/i.test(e.message)){perd.push((x.desc||x.idItem)+": "+e.message);vlcFilaGravar(vlcFilaLer().filter(y=>y.idCliente!==x.idCliente));}else continue;}}
  vlcEnviando=false;if(ok&&!silencioso)toast(ok+" baixa(s) de validade feitas sem internet foram enviadas à planilha.");if(silencioso&&div.length===1&&ok===1)toast("Baixa enviada · divergência: "+div[0].split(": ").slice(1).join(": "));
  if(vlcDeNovo){vlcDeNovo=false;setTimeout(()=>vlcFlush(true),100);}
  if(perd.length)alert("Baixas de validade não aceitas pela planilha:\n\n"+perd.join("\n"));paintVlcFila();return ok;}
function paintVlcFila(){const n=vlcFilaLer().filter(x=>x.auditor===auditor).length;let el=$("v-cfila");if(!el){const box=$("v-conv");if(!box||!box.parentNode)return;el=document.createElement("p");el.id="v-cfila";el.className="note";el.style.cssText="margin:0 0 10px;font-weight:700;color:#B45309";box.parentNode.insertBefore(el,box);}
  el.hidden=!n;el.textContent=n?"⏳ "+n+" baixa(s) de validade guardada(s) no aparelho — serão enviadas à planilha quando houver internet.":"";}
window.addEventListener("online",()=>setTimeout(()=>vlcFlush().then(n=>{if(n&&$("v-vla")&&!$("v-vla").hidden&&!VC.conv)vlcCarregar();}),1500));
setInterval(()=>{if(navigator.onLine&&vlcFilaLer().length)vlcFlush();},60000);setTimeout(()=>vlcFlush(),5000);
const vlcEnd=i=>[i.rua,i.predio,i.nivel,i.apto].join("-");
const vlcNum=x=>parseInt(String(x).replace(/\D/g,""),10)||0;
function vlcFila(){const F=VC.filtro;if(VC.soPul)return (VC.itens||[]).filter(i=>VC.pulados.has(String(i.id))&&!(VC.pulSessao||new Set()).has(String(i.id)));let L=(VC.itens||[]).filter(i=>(!F.op||i.op===F.op)&&(F.tipo==="TODOS"||i.tipo===F.tipo));
  if(F.rua){const r=vlcNum(F.rua);L=L.filter(i=>vlcNum(i.rua)>=r).concat(L.filter(i=>vlcNum(i.rua)<r));}
  return L.filter(i=>!VC.pulados.has(String(i.id)));}
/* pulados de hoje contam como concluídos */
function vlcPulHoje(){const h=fmtDT(new Date()).slice(0,10);return Object.values(VC.pulInfo||{}).filter(x=>String(x.em||"").slice(0,10)===h).length;}
/* lista dos endereços pendentes da convocação: o auditor escolhe qual auditar */
function vlcPendLista(){const F=VC.filtro,q=norm(VC.pq||"").trim();let L=(VC.itens||[]).filter(i=>!VC.pulados.has(String(i.id))&&(!F.op||i.op===F.op)&&(F.tipo==="TODOS"||i.tipo===F.tipo));
  if(q)L=L.filter(i=>norm([vlcEnd(i),i.cod,i.desc,"RUA "+vlcNum(i.rua)].join(" ")).includes(q));
  return L.sort((a,b)=>vlcNum(a.rua)-vlcNum(b.rua)||vlcNum(a.predio)-vlcNum(b.predio)||vlcNum(a.nivel)-vlcNum(b.nivel)||vlcNum(a.apto)-vlcNum(b.apto));}
function vlcPendHTML(){if(!(VC.itens||[]).length)return "";const L=vlcPendLista(),N=VC.pn||60;
  return '<div class="block" id="v-pend"><div class="ce-th"><h3>Endereços pendentes <small>'+L.length+'</small></h3></div><input class="in" type="search" id="v-pq" placeholder="Buscar rua, endereço, código ou descrição" value="'+esc(VC.pq||"")+'" style="margin-bottom:8px">'+
    (L.length?L.slice(0,N).map(i=>'<div class="vl-it vc-pi"><div><div class="addr">'+esc(vlcEnd(i))+' <small class="muted">'+esc(i.tipo)+'</small></div><div class="desc">'+esc(i.cod)+' – '+esc(String(i.desc||"").slice(0,48))+'</div><small class="muted">Validade no sistema: '+esc(i.dtval||"—")+(i.qtde?' · Qtde '+esc(i.qtde):'')+'</small></div><button type="button" class="btn sm" data-vpi="'+esc(i.id)+'">Auditar</button></div>').join("")+(L.length>N?'<button type="button" class="btn" id="v-pmais" style="width:100%;margin-top:8px">Mostrar mais ('+(L.length-N)+')</button>':''):'<p class="note">Nenhum endereço pendente neste filtro.</p>')+'</div>';}
function vlcPendBind(){const q=$("v-pq");if(q)q.oninput=()=>{VC.pq=q.value;VC.pn=60;const p=$("v-pend");if(p){p.outerHTML=vlcPendHTML();vlcPendBind();const n=$("v-pq");if(n){n.focus();n.setSelectionRange(n.value.length,n.value.length);}}};
  const m=$("v-pmais");if(m)m.onclick=()=>{VC.pn=(VC.pn||60)+60;const p=$("v-pend");p.outerHTML=vlcPendHTML();vlcPendBind();};
  document.querySelectorAll("[data-vpi]").forEach(b=>b.onclick=()=>{const i=(VC.itens||[]).find(x=>String(x.id)===b.dataset.vpi);if(!i)return;VC.soPul=false;VC.tela="auditar";VC.itens=[i].concat(VC.itens.filter(x=>x!==i));VC.filtro.rua="";vlcProximo();});}
function vlcProximo(){const L=vlcFila();VC.conv=L[0]||null;if(!VC.conv){const sp=VC.soPul;VC.tela=sp?"pulados":"inicio";VC.soPul=false;toast(sp?"Revisão dos pulados concluída.":"Fila concluída para este filtro.");}
  else{const i=VC.conv;VA.tipo=i.tipo==="AP"?"AP":"AE";$("v-os").value=i.id;$("v-end").value=vlcEnd(i);const k=pIdx.get(String(i.cod))??pIdx.get(String(i.cod).replace(/^0+/,""));if(k!=null)vProd.pick(k);else{vProd.clear();VA.prod=null;}
    VA.lotes=[{v:"",q:""}];lotesRender();VA.oc=null;VA.sug=false;}
  paintVLA();window.scrollTo(0,0);}
function vlcLista(){const box=$("v-conv");if(!box)return;paintVlcFila();const L=VC.itens||[],F=VC.filtro;
  if(VC.conv){const i=VC.conv,fila=vlcFila(),dv=(()=>{const m=String(i.dtval||"").match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/)||String(i.dtval||"").match(/(\d{4})-(\d{2})-(\d{2})/);if(!m)return null;const d=m[1].length===4?new Date(+m[1],+m[2]-1,+m[3]):new Date(+m[3],+m[2]-1,+m[1]);return Math.round((d-new Date(todayISO()+"T00:00:00"))/864e5);})();
    box.innerHTML='<div class="block vc-card"><div class="vc-top"><span class="vc-tp">'+esc(i.tipo)+'</span><span class="muted">'+fila.length+' pendente(s)</span><button type="button" class="btn sm" id="v-filtro">Trocar filtro</button></div>'+
      '<div class="vc-end">'+[["Rua",i.rua],["Prédio",i.predio],["Nível",i.nivel],["Apto",i.apto]].map(([l,v])=>'<div><span>'+l+'</span><b>'+esc(v)+'</b></div>').join("")+'</div>'+
      '<div class="vc-cod">'+esc(i.cod)+'</div><div class="vc-desc">'+esc(i.desc||"")+'</div>'+
      '<div class="vc-info"><div><span>Validade no sistema</span><b>'+esc(i.dtval||"—")+'</b></div><div><span>Dias para vencer</span><b>'+(dv==null?"—":dv)+'</b></div><div><span>Qtde no endereço</span><b>'+esc(i.qtde||"—")+'</b></div><div><span>Operação</span><b>'+esc(i.opNome||i.op)+'</b></div></div></div>';
    $("v-filtro").onclick=()=>{VC.conv=null;VC.tela="inicio";vlaReset();paintVLA();};return;}
  if(VC.tela==="pulados"){const P=L.filter(i=>VC.pulados.has(String(i.id))),pm={};P.forEach(i=>{const m=(VC.pulInfo[i.id]||{}).m||"Sem motivo";pm[m]=(pm[m]||0)+1;});
    box.innerHTML='<p class="note" style="margin:0 0 10px"><button type="button" class="link" id="v-pvolta">‹ Voltar para meus endereços</button></p><h2 class="vc-h">Endereços pulados <small>'+P.length+'</small></h2>'+
      (P.length?'<div class="tags" style="margin-bottom:10px">'+Object.entries(pm).sort((a,b)=>b[1]-a[1]).map(([m,n])=>'<span class="tag"><b>'+n+'</b> · '+esc(m)+'</span>').join("")+'</div><button type="button" class="save" id="v-paud">Auditar os pulados ('+P.length+')</button>':'<p class="note">Nenhum endereço pulado pendente.</p>')+
      P.map(i=>{const x=VC.pulInfo[i.id]||{};return '<div class="block vl-it"><div class="top"><span>'+esc(i.tipo)+' · '+esc(i.opNome||i.op)+(x.n?' · '+esc(curto(x.n)):'')+'</span><span>pulado '+esc(x.em||"")+(x.v>1?" · "+x.v+"x":"")+'</span></div><div class="addr" style="font-size:1.15rem">'+esc(vlcEnd(i))+'</div><div class="desc">'+esc(i.cod)+' – '+esc(i.desc||"")+'</div><div class="tags"><span class="tag nc">'+esc(x.m||"Sem motivo")+'</span></div><div class="vl-b" style="grid-template-columns:1fr 1fr"><button type="button" class="save" data-pa="'+esc(i.id)+'">Auditar agora</button><button type="button" class="btn" data-pv="'+esc(i.id)+'">Voltar para a fila</button></div></div>';}).join("")+'<div id="v-phist"></div>';
    vlcHist();
    $("v-pvolta").onclick=()=>{VC.tela="inicio";vlcLista();};if($("v-paud"))$("v-paud").onclick=()=>{VC.soPul=true;VC.pulSessao=new Set();VC.tela="auditar";vlcProximo();};
    box.querySelectorAll("[data-pa]").forEach(b=>b.onclick=()=>{const i=P.find(x=>String(x.id)===b.dataset.pa);if(!i)return;VC.soPul=true;VC.pulSessao=new Set();VC.tela="auditar";VC.itens=[i].concat(VC.itens.filter(x=>x!==i));vlcProximo();});
    box.querySelectorAll("[data-pv]").forEach(b=>b.onclick=()=>{vlcPulTirar(b.dataset.pv);vlcLista();toast("Endereço voltou para a fila normal.");});return;}
  if(VC.tela==="avulsa"){box.innerHTML=L.length?'<p class="note" style="margin:0 0 10px"><button type="button" class="link" id="v-voltar">‹ Voltar para meus endereços</button> · auditoria avulsa (sem convocação)</p>':'';if($("v-voltar"))$("v-voltar").onclick=()=>{VC.tela="inicio";paintVLA();};return;}
  if(VC.itens!=null&&!L.length&&!VC.msg){box.innerHTML='<p class="note" style="margin:0 0 10px">Nenhum endereço convocado para você agora'+(VC.recebido?" (lista recebida em "+esc(VC.recebido)+")":"")+'. <button type="button" class="link" id="v-cupd">Atualizar</button></p>';$("v-cupd").onclick=vlcCarregar;return;}
  const ops=[...new Map(L.map(i=>[i.op,i.opNome||i.op])).entries()];if(F.op&&!ops.some(o=>o[0]===F.op))F.op="";
  const base=L.filter(i=>!F.op||i.op===F.op),ruas=[...new Set(base.filter(i=>F.tipo==="TODOS"||i.tipo===F.tipo).map(i=>String(vlcNum(i.rua))))].sort((a,b)=>a-b);
  box.innerHTML='<h2 class="vc-h">Meus endereços</h2>'+(VC.msg?'<p class="note" style="color:#B91C1C">'+esc(VC.msg)+'</p>':'')+
    '<div class="vc-kpi"><div><b>'+(VC.busy&&!VC.itens?"…":base.filter(i=>!VC.pulados.has(String(i.id))).length)+'</b><span>Pendentes</span></div><div><b>'+(vlaHoje().length+vlcPulHoje())+'</b><span>Concluídos hoje</span></div><div><b>'+vlaHoje().length+'</b><span>Auditados hoje</span></div></div>'+
    '<div class="block"><div class="field"><label for="v-fop">Operação</label><select class="in" id="v-fop">'+(ops.length>1?'<option value="">Todas as operações ('+L.length+')</option>':'')+(ops.map(([id,n])=>'<option value="'+esc(id)+'"'+(id===F.op?" selected":"")+'>'+esc(n)+' ('+L.filter(i=>i.op===id).length+')</option>').join("")||'<option value="">—</option>')+'</select></div>'+
    '<div class="field"><span class="lbl">Tipo de endereço</span><div class="seg vc-seg">'+["AE","AP","TODOS"].map(t=>'<button type="button" data-ft="'+t+'" aria-pressed="'+(F.tipo===t)+'">'+(t==="TODOS"?"Todos":t)+'</button>').join("")+'</div></div>'+
    '<div class="field"><label for="v-frua">Começar pela rua</label><select class="in" id="v-frua"><option value="">Primeira rua com pendência</option>'+ruas.map(r=>'<option value="'+r+'"'+(String(F.rua)===r?" selected":"")+'>Rua '+r+'</option>').join("")+'</select></div>'+
    '<button type="button" class="save" id="v-ini"'+(base.length?"":" disabled")+'>'+(VC.feitos||VC.pulados.size?"Retomar":"Começar")+'</button>'+
    (ehAdm()?'<label class="muted" style="display:block;margin-top:8px"><input type="checkbox" id="v-todos"'+(VC.todos?" checked":"")+'> ver convocações de todos os auditores</label>':'')+'</div>'+
    '<p class="note">'+(VC.busy?"Carregando…":"Lista recebida em "+esc(VC.recebido||"—")+".")+' <button type="button" class="link" id="v-cupd">Atualizar</button> · <button type="button" class="link" id="v-avulsa">Auditoria avulsa (sem convocação)</button></p>'+vlcPendHTML();
  $("v-fop").onchange=e=>{F.op=e.target.value;F.rua="";vlcLista();};box.querySelectorAll("[data-ft]").forEach(b=>b.onclick=()=>{F.tipo=b.dataset.ft;F.rua="";vlcLista();});$("v-frua").onchange=e=>{F.rua=e.target.value;};
  $("v-ini").onclick=()=>{VC.tela="auditar";VC.soPul=false;vlcProximo();};vlcPendBind();$("v-cupd").onclick=vlcCarregar;$("v-avulsa").onclick=()=>{VC.tela="avulsa";vlaReset();paintVLA();};if($("v-todos"))$("v-todos").onchange=e=>{VC.todos=e.target.checked;vlcCarregar();};}
