// ===================== Gestão Controle de Estoque: acessos, senha, metas, feedback e NC dos auditores =====================
function gestMats(){return ["10002001","10002939"];}
function meuMat(){return String((LOGIN&&(LOGIN.mat||LOGIN.matricula))||"");}
function ehGest(){return gestMats().indexOf(meuMat())>=0;}
function gPerm(p){return ehGest()||temPerm(p);}
/* regras de acesso das abas novas e das abas exclusivas dos gestores (não basta ser ADM) */
function podeVerG(v){switch(v){
  case "rot":return gPerm("ce_est")||temPerm("aud_rot");
  case "lib":return gPerm("ce_est")||temPerm("aud_lib");
  case "rtz":return true;
  case "pcg":return true;
  case "shl":return true;
  case "inv":return invPode();
  case "curva":case "curvaa":return true;
  case "cha":return gPerm("ce_gest")||temPerm("aud_cha");
  case "com":return gPerm("ce_gest")||temPerm("aud_com");
  case "registros":return gPerm("ce_gest")||temPerm("aud_reg");
  case "painel":case "metas":case "feedback":case "ncaud":case "spkh":case "ocio":case "desemp":return gPerm("ce_gest");
  case "fechamento":return gPerm("ce_gest")?true:undefined;
  case "bases":return gPerm("ce_bas");}
  return undefined;}
/* senha extra para Gestão Controle de Estoque e Bases (vale até fechar o app) */
function gateGrupo(v){if(v==="bases")return "b";if(({cha:"aud_cha",com:"aud_com",registros:"aud_reg"})[v]&&!gPerm("ce_gest"))return "";if(["cha","com","registros","painel","metas","feedback","ncaud","spkh","ocio","desemp"].indexOf(v)>=0)return "g";if(v==="fechamento"&&gPerm("ce_gest"))return "g";return "";}
function gateHash(g){return {g:"1526e9e952db756cc962825dd6ce63b29b9e6ada2a1f35ef2e1656d607844cf2",b:"1526e9e952db756cc962825dd6ce63b29b9e6ada2a1f35ef2e1656d607844cf2"}[g];}
var GATE_OK=GATE_OK||{};
function gateNeed(v){const g=gateGrupo(v);return !!(g&&!GATE_OK[g]&&!DEMO);}
async function sha256hex(t){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(t));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("");}
function gateAsk(v){const g=gateGrupo(v),tit=g==="b"?"Bases e planilha":"Gestão Controle de Estoque";let m=$("gate");if(!m){m=document.createElement("div");m.id="gate";document.body.appendChild(m);}
  m.innerHTML='<div class="gt-bg"></div><form class="gt-box" autocomplete="off"><div class="gt-ic"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg></div><h2>'+tit+'</h2><p>Área restrita aos gestores. Digite a senha de acesso.</p>'+
    '<input class="in" type="password" id="gt-s" placeholder="Senha de acesso" autocomplete="off"><p class="gt-e" id="gt-e" hidden>Senha incorreta.</p><div class="gt-b"><button type="button" class="btn" id="gt-x">Cancelar</button><button type="submit" class="save" id="gt-ok">Entrar</button></div></form>';
  m.hidden=false;setTimeout(()=>$("gt-s").focus(),50);const fe=()=>{m.hidden=true;};$("gt-x").onclick=fe;m.querySelector(".gt-bg").onclick=fe;
  m.querySelector("form").onsubmit=async e=>{e.preventDefault();const h=await sha256hex($("gt-s").value.trim());if(h===gateHash(g)){GATE_OK[g]=true;fe();go(v);}else{$("gt-e").hidden=false;$("gt-s").select();}};}
function gestAplicar(){const G=gPerm("ce_gest");document.querySelectorAll("#dk-g-gest .dk-gh, #dk-g-gest .dk-gh span").forEach(h=>{if(!h.querySelector("span"))h.textContent=G?"Gestão Controle de Estoque":"Meus fechamentos";});
  document.querySelectorAll("nav .dk-g").forEach(g=>{const bs=[...g.querySelectorAll("button[data-v]")];if(bs.length)g.hidden=!bs.some(b=>!b.hidden);});}

