/* convocação ativa da validade: base informada pelo gestor + auditorias e pulados (pulado = concluído) do responsável depois da base */
function gmVldConv(D){const c=gmCfg(),END=+c.vldConvEnd||0;if(!END)return null;const base=+c.vldConvBase||0,t0=Date.parse(c.vldConvBaseEm||"")||0,R=new Set(gmRespMats("vld"));
  const eh=(m,n)=>{const p=gmPessoa(m,n);return p&&R.has(String(p.mat));};const vis=new Set();let audApp=0,audConv=0,pul=0,ult=0;
  gmRows(D,"validade").forEach(r=>{if(!r.Codigo_Produto||!eh(r.Matricula_Auditor,r.Nome_Auditor))return;if(r.ts>ult)ult=r.ts;if(!(r.ts>t0))return;const k=String(r.ID_Auditoria);if(vis.has(k))return;vis.add(k);audApp++;});
  if(GM.vm&&GM.vm.itens){const nm=GM.vm.nomes||{},ok={};GM.vm.itens.forEach(([lg,i0,tf,st])=>{if(st!=="A"||!tf)return;if(ok[lg]==null)ok[lg]=!!(eh(/^\d{6,}$/.test(lg)?lg:"",nm[lg]||lg));if(!ok[lg])return;if(tf>ult)ult=tf;if(tf>t0)audConv++;});}
  const aud=Math.max(audApp,audConv);
  ((VAL.dados&&VAL.dados.pul)||[]).forEach(x=>{const t=(rotDt(x.DataHora)||new Date(0)).getTime();if(x.Status==="Pulado"&&t>t0&&eh(x.Matricula,x.Nome))pul++;});
  /* prazo em dias úteis (seg a sex, ou seg a sáb conforme "Dias úteis na semana"), contados a partir da data de início */
  const iniS=c.vldConvIni||GM_DEF.vldConvIni,real=base+aud+pul,ini=iniS?new Date(iniS+"T00:00:00").getTime():0,dias=+c.vldConvDias||0,ds=+c.diasSemana||5,now=Date.now();
  let fim=0;if(ini&&dias){const d=new Date(ini);let n=0;while(n<dias){const w=d.getDay();if(w>=1&&w<=ds)n++;d.setDate(d.getDate()+1);}fim=d.getTime();}
  const rit=fim?Math.min(1,Math.max(.02,gmDiasUteis(ini,Math.min(now,fim),ds)/dias)):1;return {END,base,aud,audApp,audConv,ult,pul,real,pct:real/END,rit,ini,fim,dias,restam:Math.max(0,END-real),diasRest:fim?gmDiasUteis(now,fim,ds):null};}
var GM={cfg:null,per:"semana",off:0,users:null,vm:null,vmEm:0,busy:false,msg:""};
function gmCfg(){return Object.assign({},GM_DEF,GM.cfg||{});}
async function gmCarregarCfg(){if(GM.cfg||DEMO||!SHEET_URL)return;try{const j=await ppPost({acao:"painel_ler",painel:"metas"});if(j&&j.dados)GM.cfg=j.dados;else GM.cfg={};}catch(e){GM.cfg={};}}
const gmNk=s=>{const p=String(s||"").normalize("NFD").replace(/[̀-ͯ]/g,"").toUpperCase().replace(/[^A-Z ]/g," ").trim().split(/\s+/).filter(Boolean);return p.length?p[0]+" "+p[p.length-1]:"";};
/* nome pela matrícula: cadastro de colaboradores, quadro e lançamentos da planilha */
function gmNomeDe(mat){mat=String(mat||"").trim();if(!mat)return "";try{const i=cIdx.get(mat);if(i!=null&&C.nome[i])return C.nome[i];}catch(e){}
  try{const q=(QUADRO||[]).find(x=>x.mat===mat);if(q&&q.nome)return q.nome;}catch(e){}
  const D=FECH.dados||{};if(!GM.nm||GM.nmD!==D){GM.nmD=D;GM.nm={};Object.keys(D).forEach(a=>{try{fxRows(D[a]).forEach(r=>{[["Matricula_Auditor","Nome_Auditor"],["Matricula_Colaborador_NC","Nome_Colaborador_NC"],["Matricula_Colaborador","Nome_Colaborador"],["Matricula_Conferente","Nome_Conferente"]].forEach(([m,n])=>{const k=String(r[m]||"").trim();if(k&&r[n]&&!/^\d+$/.test(r[n])&&!GM.nm[k])GM.nm[k]=r[n];});});}catch(e){}});}
  return GM.nm[mat]||"";}
function gmTitulo(s){return String(curto(s)||"").toLowerCase().replace(/(^|\s)\S/g,c=>c.toUpperCase());}
/* período: semana (seg a dom) ou mês, com deslocamento */
function gmPeriodo(per,off){const h=new Date();h.setHours(0,0,0,0);let de,ate,lab;
  if(per==="mes"){de=new Date(h.getFullYear(),h.getMonth()+off,1);ate=new Date(de.getFullYear(),de.getMonth()+1,1);lab=de.toLocaleDateString("pt-BR",{month:"long",year:"numeric"});lab=lab.charAt(0).toUpperCase()+lab.slice(1);}
  else{de=new Date(h);de.setDate(de.getDate()-((de.getDay()+6)%7)+7*off);ate=new Date(de);ate.setDate(ate.getDate()+7);const f=new Date(ate-864e5);lab="Semana de "+de.toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"})+" a "+f.toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit",year:"numeric"});}
  return {de:de.getTime(),ate:ate.getTime(),lab,per};}
function gmDiasUteis(a,b,ds){let n=0;const d=new Date(a);d.setHours(0,0,0,0);while(d.getTime()<b){const w=d.getDay();if(w>=1&&w<=ds)n++;d.setDate(d.getDate()+1);}return n;}
/* semanas do mês = quantas quintas-feiras o mês tem (padrão ISO: novembro/2026 = 4) */
function gmSemanasMes(y,m){let n=0;const d=new Date(y,m,1);while(d.getMonth()===m){if(d.getDay()===4)n++;d.setDate(d.getDate()+1);}return n;}
function gmFator(P){const c=gmCfg();if(P.per==="mes"){const d=new Date(P.de);return gmSemanasMes(d.getFullYear(),d.getMonth());}return 1;}
function gmRitmo(P){const c=gmCfg(),now=Date.now();if(now>=P.ate)return 1;if(now<P.de)return 0;const t=gmDiasUteis(P.de,P.ate,c.diasSemana)||1,h=new Date();h.setHours(0,0,0,0);const f=gmDiasUteis(P.de,h.getTime()+864e5,c.diasSemana);return Math.min(1,f/t);}
function gmTotPicking(){return Object.entries(RUA_ENDS).filter(([r])=>!RUAS_FORA.has(r)).reduce((s,[,v])=>s+v,0);}
