// ===================== NC dos auditores: textos prontos por situação e medida =====================
const NCA_TIPOS=["Meta não atingida","Erro identificado pelo gestor","Erro de lançamento na auditoria","Prazo não cumprido","Descumprimento de procedimento","Ociosidade acima do esperado"];
const NCA_MEDIDAS=["Orientação e plano de ação","Advertência verbal","Advertência escrita","Solicitação de advertência ao RH"];
const NCA_FATO={
  "Meta não atingida":"No período {periodo}, o(a) colaborador(a) {colab} não atingiu a meta estabelecida para o indicador {meta}, conforme os resultados registrados no sistema de auditoria e as metas previamente comunicadas à equipe.",
  "Erro identificado pelo gestor":"Em {data}, a gestão identificou falha na execução das atividades do(a) colaborador(a) {colab}: [descreva o fato, o local (rua/endereço/carga) e o impacto para o estoque].",
  "Erro de lançamento na auditoria":"Em {data}, foi identificado lançamento incorreto na auditoria realizada pelo(a) colaborador(a) {colab} — registro divergente da conferência física [informe o item, o endereço e a divergência], comprometendo a confiabilidade das informações de estoque.",
  "Prazo não cumprido":"O(A) colaborador(a) {colab} não concluiu dentro do prazo estabelecido a atividade sob sua responsabilidade [descreva a atividade e o prazo], sem justificativa prévia à gestão.",
  "Descumprimento de procedimento":"Em {data}, o(a) colaborador(a) {colab} deixou de seguir o procedimento operacional [descreva o procedimento], no qual foi previamente treinado(a) e que foi comunicado ao setor.",
  "Ociosidade acima do esperado":"No período {periodo}, foi verificado tempo sem registro de atividades acima do esperado para a jornada do(a) colaborador(a) {colab}, conforme os horários dos lançamentos no sistema de auditoria."};
const NCA_MED={
  "Orientação e plano de ação":"O(A) colaborador(a) foi orientado(a) sobre o padrão esperado e sobre a importância do indicador para o resultado do Controle de Estoque. Fica estabelecido plano de ação, com acompanhamento até o prazo definido neste documento. Esta orientação tem caráter educativo e não constitui penalidade.",
  "Advertência verbal":"Diante do ocorrido, o(a) colaborador(a) recebe advertência verbal, registrada neste documento para fins de histórico. Foi orientado(a) a corrigir a conduta, ciente de que a reincidência poderá resultar em advertência escrita, conforme o regulamento interno.",
  "Advertência escrita":"Pelo presente, o(a) colaborador(a) é advertido(a) por escrito em razão do fato descrito, nos termos do regulamento interno e do poder disciplinar do empregador. A reincidência poderá ensejar medidas disciplinares mais severas, observada a legislação trabalhista.",
  "Solicitação de advertência ao RH":"Considerando a reincidência registrada, a gestão encaminha o caso ao Departamento Pessoal / RH para análise e eventual aplicação de medida disciplinar, conforme o regulamento interno."};
function ncaTexto(tipo,colab,extra){extra=extra||{};return String(NCA_FATO[tipo]||"").replace(/\{colab\}/g,gmTitulo(colab||"")||"[colaborador]").replace(/\{periodo\}/g,extra.periodo||"[período]").replace(/\{meta\}/g,extra.meta||"[indicador]").replace(/\{data\}/g,extra.data||new Date().toLocaleDateString("pt-BR"));}

// ===================== Desempenho dos auditores (painel de gestão) =====================
BAND.desemp=["Desempenho dos auditores","Produção, qualidade, metas, ociosidade e histórico de cada auditor."];
function dsRowsDe(x,P){const D=FECH.dados||{},out=[];const nk=gmNk(x.nome);
  OC_ABAS.forEach(a=>fxRows(D[a]).forEach(r=>{if(!r.ts||r.ts<P.de||r.ts>=P.ate)return;const m=String(r.Matricula_Auditor||"").trim();if((x.mat&&m===x.mat)||(!m&&gmNk(r.Nome_Auditor)===nk)||(m&&!x.mat&&gmNk(r.Nome_Auditor)===nk))out.push(Object.assign({_a:a},r));}));return out;}
const DS_NOME={ruas:"Ruas",retorno:"Retorno",cargas:"Cargas",procura:"Procura",saldo:"Saldo de picking",validade:"Validade",contagem:"Contagem/Aéreo",aero:"Aéreo (NC)",sac:"SAC",adega:"ADEGA",pp:"Prevenção",solicit:"Solicitações"};
function dsResumo(P){const R=gmCalc(P),O={};try{ocCalc(P).forEach(o=>{O[o.mat||gmNk(o.nome)]=o;});}catch(e){}const NC=ncaTodas(),FB=fxRows(FECH.dados&&FECH.dados.feedback);
  return R.L.map(x=>{const rs=dsRowsDe(x,P),it=gmFbDados(R,x),g=it.filter(i=>i.ref!=null),meta=g.length?g.reduce((s,i)=>s+Math.min(1.2,i.ref),0)/g.length:null,o=O[x.mat]||O[gmNk(x.nome)];
    const meus=NC.filter(r=>(x.mat&&String(r.Matricula_Colaborador)===x.mat)||gmNk(r.Nome_Colaborador)===gmNk(x.nome)),fb=FB.filter(r=>(x.mat&&String(r.Matricula_Colaborador)===x.mat)||gmNk(r.Nome_Colaborador)===gmNk(x.nome));
    const dias=new Set(rs.map(r=>fxDiaKey(r.ts))).size,achados=rs.filter(r=>pbool(r.Possui_NC)||(r._a==="saldo"&&r.Situacao&&r.Situacao!=="OK")).length;
    return {x,rs,it,meta,oc:o?o.pct:null,ocH:o?o.ociT:0,dias,lanc:rs.length,media:dias?rs.length/dias:0,achados,nc:meus.filter(r=>r.Tipo!==NCA_TIPO_ADV),adv:meus.filter(r=>r.Tipo===NCA_TIPO_ADV),fb};}).sort((a,b)=>(b.meta==null?-1:b.meta)-(a.meta==null?-1:a.meta)||b.lanc-a.lanc);}
function paintDesemp(){const box=$("gm-desemp");if(!box)return;gmPrep(paintDesemp);
  if(!FECH.dados){box.innerHTML=gmPerBar()+'<div class="nw-sk">'+'<div></div>'.repeat(4)+'</div>';gmBindBar(paintDesemp);return;}
  const P=gmPeriodo(GM.per,GM.off),L=dsResumo(P),sel=GM.dsel&&L.find(d=>d.x.k===GM.dsel);
  const pct=v=>v==null?'–':Math.round(v*100)+'%',corM=v=>gmSit(v,P.ate>Date.now()).c;
  let html=gmPerBar()+'<div class="ds-sel"><label>Auditor <select class="in" id="ds-a"><option value="">Todos os auditores</option>'+L.map(d=>'<option value="'+esc(d.x.k)+'"'+(sel&&sel.x.k===d.x.k?" selected":"")+'>'+esc(gmTitulo(d.x.nome))+'</option>').join("")+'</select></label></div>';
  if(!sel){html+=L.length?'<div class="fx-c"><h3>Ranking do período</h3><div class="tw"><table class="gm-t ds-t"><thead><tr><th>#</th><th>Auditor</th><th>Lançamentos</th><th>Dias</th><th>Média/dia</th><th>NCs encontradas</th><th>Metas</th><th>Ociosidade</th><th>NCs recebidas</th><th>Advertências</th></tr></thead><tbody>'+
      L.map((d,i)=>'<tr data-ds="'+esc(d.x.k)+'"><td><span class="hm-eqn">'+(i+1)+'</span></td><td><b>'+esc(String(d.x.nome).toUpperCase())+'</b><small>Matrícula '+esc(d.x.mat||"–")+'</small></td><td>'+d.lanc.toLocaleString("pt-BR")+'</td><td>'+d.dias+'</td><td>'+d.media.toFixed(1).replace(".",",")+'</td><td>'+d.achados+'</td><td><b style="color:'+corM(d.meta)+'">'+pct(d.meta)+'</b></td><td><b style="color:'+(d.oc==null?"#64748B":ocCor(d.oc))+'">'+pct(d.oc)+'</b></td><td>'+d.nc.length+'</td><td>'+(d.adv.length?'<b style="color:#B91C1C">'+d.adv.length+'</b>':'0')+'</td></tr>').join("")+'</tbody></table></div></div>'+
      '<div class="fx-row" style="grid-template-columns:1fr 1fr;margin-top:14px">'+fxCard("Lançamentos por auditor",fxCols(L.slice().sort((a,b)=>b.lanc-a.lanc).slice(0,12).map(d=>({l:gmTitulo(d.x.nome).split(" ")[0],t:gmTitulo(d.x.nome)+": "+d.lanc,v:d.lanc,txt:String(d.lanc),c:"#103F79"}))))+
        fxCard("Atingimento das metas por auditor",fxCols(L.filter(d=>d.meta!=null).map(d=>({l:gmTitulo(d.x.nome).split(" ")[0],t:gmTitulo(d.x.nome)+": "+pct(d.meta),v:Math.round(d.meta*100),txt:pct(d.meta),c:corM(d.meta)}))))+'</div>':'<p class="fx-e">Nenhum auditor com lançamentos no período.</p>';}
  else{const d=sel,porD={},porA={};d.rs.forEach(r=>{const k=fxDiaKey(r.ts);(porD[k]=porD[k]||{ts:r.ts,n:0}).n++;porA[r._a]=(porA[r._a]||0)+1;});
    const sem=[5,4,3,2,1,0].map(i=>{const PP=gmPeriodo("semana",GM.per==="semana"?GM.off-i:-i);let v=null;try{const RR=gmCalc(PP),xx=RR.L.find(y=>(d.x.mat&&y.mat===d.x.mat)||gmNk(y.nome)===gmNk(d.x.nome));if(xx){const g=gmFbDados(RR,xx).filter(t=>t.ref!=null);v=g.length?g.reduce((s,t)=>s+Math.min(1.2,t.ref),0)/g.length:null;}}catch(e){}return {l:new Date(PP.de).toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"}),v};});
    html+='<div class="ds-head"><div><b>'+esc(String(d.x.nome).toUpperCase())+'</b><span>Matrícula '+esc(d.x.mat||"–")+' · '+esc(P.lab)+'</span></div><button type="button" class="btn sm" id="ds-fb">Imprimir feedback</button></div>'+
      fxKpis([{t:"Lançamentos",v:d.lanc.toLocaleString("pt-BR"),c:"#103F79",s:d.dias+" dia(s) · "+d.media.toFixed(1).replace(".",",")+"/dia"},{t:"NCs encontradas",v:d.achados,c:"#B45309",s:"nas auditorias do período"},{t:"Metas",v:pct(d.meta),c:corM(d.meta),s:gmSit(d.meta,P.ate>Date.now()).t},
        {t:"Ociosidade",v:pct(d.oc),c:d.oc==null?"#64748B":ocCor(d.oc),s:d.ocH?ocH(d.ocH)+" sem lançamento":""},{t:"NCs recebidas",v:d.nc.length,c:"#DC2626",s:d.nc.filter(r=>r.Status==="Aplicada").length+" aplicada(s)"},{t:"Advertências",v:d.adv.length,c:d.adv.length?"#B91C1C":"#16A34A",s:d.fb.length+" feedback(s) emitido(s)"}])+
      '<div class="fx-row" style="grid-template-columns:1.4fr 1fr">'+fxCard("Lançamentos por dia",fxCols(Object.keys(porD).sort().map(k=>({l:fxDia(porD[k].ts),v:porD[k].n,txt:String(porD[k].n),c:"#103F79"}))))+
        fxCard("Por tipo de auditoria",fxBars(Object.entries(porA).sort((a,b)=>b[1]-a[1]).map(([a,n])=>({l:DS_NOME[a]||a,v:n,txt:String(n),c:"#2563EB"}))))+'</div>'+
      '<div class="fx-row" style="grid-template-columns:1fr 1fr;margin-top:10px">'+fxCard("Metas no período",d.it.length?fxBars(d.it.map(i=>({l:i.m.t,v:Math.round((i.pct||0)*100),txt:i.pct==null?(i.txt||"–"):Math.round(i.pct*100)+"% · "+i.si.t+(i.k==="vld"&&i.txt?" · "+i.txt:""),c:i.si.c}))):'<p class="fx-e">Sem metas no período.</p>')+
        fxCard("Evolução das metas (últimas 6 semanas)",fxCols(sem.map(w=>({l:w.l,v:w.v==null?0:Math.round(w.v*100),txt:w.v==null?"–":Math.round(w.v*100)+"%",c:w.v==null?"#CBD5E1":corM(w.v)}))))+'</div>'+
      '<div class="fx-row" style="grid-template-columns:1fr 1fr;margin-top:10px">'+fxCard("Histórico de não conformidades",d.nc.length+d.adv.length?fxTable([{t:"Data"},{t:"Tipo"},{t:"Medida"},{t:"Situação"}],d.nc.concat(d.adv).sort((a,b)=>(b.ts||0)-(a.ts||0)).slice(0,12).map(r=>[esc(String(r.DataHora||"").slice(0,10)),esc(r.Tipo||""),esc(r.Medida||""),esc(r.Status||"")])):'<p class="fx-e">Nenhuma não conformidade registrada.</p>')+
        fxCard("Feedbacks emitidos",d.fb.length?fxTable([{t:"Data"},{t:"Período"},{t:"Resumo"}],d.fb.sort((a,b)=>(b.ts||0)-(a.ts||0)).slice(0,10).map(r=>[esc(String(r.DataHora||"").slice(0,10)),esc(r.Periodo||""),esc(String(r.Resumo||"").slice(0,90))])):'<p class="fx-e">Nenhum feedback emitido.</p>')+'</div>';}
  box.innerHTML=html;gmBindBar(paintDesemp);$("ds-a").onchange=e=>{GM.dsel=e.target.value||null;paintDesemp();};
  box.querySelectorAll("[data-ds]").forEach(t=>t.onclick=()=>{GM.dsel=t.dataset.ds;paintDesemp();box.scrollIntoView({block:"start"});});
  const fb=$("ds-fb");if(fb&&sel)fb.onclick=()=>gmFbAbrir(gmCalc(P),[sel.x]);}
(function(){const s=document.createElement("style");s.textContent=`.ds-sel{margin:-4px 0 12px}.ds-sel label{display:flex;flex-direction:column;gap:4px;font-weight:600;font-size:.85rem;max-width:360px}
.ds-t tbody tr{cursor:pointer}.ds-t tbody tr:hover{background:var(--surface-2,#F1F5F9)}.ds-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px}.ds-head b{font-size:1.15rem;display:block}.ds-head span{color:var(--muted);font-size:.85rem}
.nca-med{margin-top:4px;font-size:.8rem;color:var(--muted);line-height:1.35}`;document.head.appendChild(s);})();

// ===== Saldo de picking: itens de dias anteriores ao app (lançamento manual do gestor) =====
const SPKH_COLS=["ID_Auditoria","Data","DataHora","Data_Referencia","Quantidade_Itens","Matricula_Colaborador","Nome_Colaborador","Observacao","Lancado_Em","Matricula_Auditor","Nome_Auditor"];
function spkhLista(){const s=fxRows(FECH.dados&&FECH.dados.spkh),ids=new Set(s.map(r=>String(r.ID_Auditoria)));return s.concat(allRecs().filter(r=>r._aba==="spkh"&&!ids.has(String(r.ID_Auditoria))).map(r=>Object.assign({},r,{ts:r.ts}))).sort((a,b)=>(b.ts||0)-(a.ts||0));}
function spkhQtd(r){return pnum(r.Quantidade_Itens)||0;}
async function spkhExcluir(r,id){if(!confirm("Apagar o lançamento de "+spkhQtd(r).toLocaleString("pt-BR")+" itens em "+(fdISO(r.Data_Referencia)||r.Data_Referencia)+"? Ele sai do app e da planilha Google. Não dá para desfazer."))return;
  const ID=String(r.ID_Auditoria),naFila=queue.some(x=>x.rec.ID_Auditoria===ID);
  if(!naFila&&!DEMO&&SHEET_URL){if(!navigator.onLine){toast("Sem internet: não dá para apagar da planilha agora.");return;}
    try{const q=await fetch(SHEET_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({acao:"admin_excluir",token:LOGIN.token,aba:"spkh",id:ID}),redirect:"follow",cache:"no-store"});const j=await q.json();if(!j.ok){toast(j.erro||"Não foi possível apagar na planilha.");return;}}catch(e){toast("Não foi possível falar com a planilha.");return;}}
  HIST.delete(ID);IDB.del(ID).catch(()=>{});const qi=queue.findIndex(x=>x.rec.ID_Auditoria===ID);if(qi>=0){queue.splice(qi,1);saveQueue();}
  try{const b=FECH.dados&&FECH.dados.spkh;if(b&&b.colunas){const i=b.colunas.indexOf("ID_Auditoria");b.registros=b.registros.filter(x=>String(x[i])!==ID);}}catch(e){}
  toast("Lançamento apagado.");spkhUI(id);try{if(!$("v-fechamento").hidden)renderFech();}catch(e){}}
function spkhUI(id){const box=$(id||"k-hist");if(!box)return;{const o=$(id?"k-hist":"k-hist2");if(o&&o!==box)o.innerHTML="";}const pode=gPerm("ce_gest")||ehAdm(),bt=document.querySelector('#k-modo [data-km="hist"]');if(bt)bt.hidden=!pode;if(!pode){if(!id&&KS.modo==="hist"){KS.modo="cont";paintSPK();}return;}const L=spkhLista(),tot=L.reduce((s,r)=>s+spkhQtd(r),0),hoje=todayISO();
  box.innerHTML='<div class="kh"><h3 style="margin:14px 0 2px">Ou só a quantidade total de itens de um dia</h3><small class="note">'+(L.length?L.length+' lançamento(s) · '+tot.toLocaleString("pt-BR")+' itens':'lançamento manual do gestor')+'</small>'+
    
    '<form class="kh-f" id="kh-f"><label>Data<input class="in" type="date" id="kh-d" max="'+hoje+'" required></label><label>Quantidade de itens<input class="in" type="number" id="kh-q" min="1" step="1" inputmode="numeric" required></label>'+
    '<label>Auditor <small>(opcional)</small><input class="in" id="kh-m" inputmode="numeric" placeholder="Matrícula"><small id="kh-mn" class="note"></small></label><label class="kh-w">Observação <small>(opcional)</small><input class="in" id="kh-o" maxlength="200"></label>'+
    '<button type="submit" class="save">Salvar quantidade do dia</button></form>'+
    (L.length?'<div class="tw"><table class="gm-t"><thead><tr><th>Data</th><th>Itens</th><th>Auditor</th><th>Observação</th><th></th></tr></thead><tbody>'+L.slice(0,120).map((r,ix)=>'<tr><td>'+esc(fdISO(r.Data_Referencia)||r.Data_Referencia||"")+(r._pend?' <small>(enviando)</small>':'')+'</td><td><b>'+spkhQtd(r).toLocaleString("pt-BR")+'</b></td><td>'+esc(r.Nome_Colaborador||r.Matricula_Colaborador||"–")+'</td><td>'+esc(r.Observacao||"")+'</td><td><button type="button" class="btn sm kh-del" data-khx="'+ix+'">Apagar</button></td></tr>').join("")+'</tbody></table></div><p class="note">Para corrigir um lançamento, apague e lance de novo.</p>':'')+'</div>';
  box.querySelectorAll("[data-khx]").forEach(b=>b.onclick=()=>spkhExcluir(L[+b.dataset.khx],id));
  const m=$("kh-m");m.oninput=()=>{const n=gmNomeDe(m.value.trim());$("kh-mn").textContent=n?gmTitulo(n):(m.value.trim()?"Matrícula não encontrada no cadastro":"");};
  $("kh-f").onsubmit=async e=>{e.preventDefault();const dt=$("kh-d").value,q=Math.round(+$("kh-q").value);if(!dt||!(q>0)){toast("Informe a data e a quantidade.");return;}if(dt>todayISO()){toast("A data não pode ser futura.");return;}
    const dup=L.find(r=>String(r.Data_Referencia).slice(0,10)===dt||fdISO(r.Data_Referencia)===fdISO(dt));if(dup&&!confirm("Já existe um lançamento de "+spkhQtd(dup)+" itens em "+fdISO(dt)+". Lançar mais este também?"))return;
    const ref=new Date(dt+"T12:00:00"),now=new Date(),mat=m.value.trim();
    await saveRec({_aba:"spkh",ID_Auditoria:newId("SPH"),Data:fdISO(dt),DataHora:fmtDT(ref),ts:ref.getTime(),Data_Referencia:dt,Quantidade_Itens:q,Matricula_Colaborador:mat,Nome_Colaborador:mat?gmNomeDe(mat):"",Observacao:$("kh-o").value.trim(),Lancado_Em:fmtDT(now),Matricula_Auditor:meuMat(),Nome_Auditor:nomeAud()});
    toast(q.toLocaleString("pt-BR")+" itens lançados em "+fdISO(dt)+".");box.dataset.open="1";spkhUI(id);};}
