  const por={};L.forEach(r=>{const p=(typeof gmPessoa==="function"&&gmPessoa(r.Matricula_Auditor,r.Nome_Auditor))||{mat:r.Matricula_Auditor,nome:r.Nome_Auditor};const k=p.mat||p.nome;(por[k]=por[k]||{n:0,nome:p.nome||p.mat,ult:""}).n++;por[k].ult=r.Data;});
