  on("[data-cvgo]",b=>b.onclick=()=>go(b.dataset.cvgo));on("[data-cvpz]",b=>b.onclick=()=>{const d=+b.dataset.cvpz,pw=box.querySelector(".cv-plw"),cx=pw?(pw.scrollLeft+pw.clientWidth/2)/pw.scrollWidth:0.5,cy=pw?(pw.scrollTop+pw.clientHeight/2)/Math.max(1,pw.scrollHeight):0.5;CV.pz=d===0?1:Math.max(1,Math.min(4,Math.round(((CV.pz||1)+d*0.5)*10)/10));cvPaintPick();const n=box.querySelector(".cv-plw");if(n){n.scrollLeft=cx*n.scrollWidth-n.clientWidth/2;n.scrollTop=cy*n.scrollHeight-n.clientHeight/2;}});
  on(".cv-plw.zoom",pw=>{let d=null;pw.onpointerdown=e=>{if(e.pointerType!=="mouse"||e.button!==0)return;d={x:e.clientX,y:e.clientY,l:pw.scrollLeft,t:pw.scrollTop,m:0};};pw.onpointermove=e=>{if(!d)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;d.m+=Math.abs(dx)+Math.abs(dy);if(d.m>4){pw.scrollLeft=d.l-dx;pw.scrollTop=d.t-dy;pw.classList.add("drag");}};pw.onpointerup=pw.onpointerleave=()=>{setTimeout(()=>pw.classList.remove("drag"),0);d=null;};});on("[data-cvs]",th=>th.onclick=()=>{const [t,k]=th.dataset.cvs.split("|"),o=CV.srt[t];CV.srt[t]=o&&o.c===k?{c:k,d:-o.d}:{c:k,d:["desc","est","dpt","sit","dest","dd","mot","end","cod","n"].includes(k)?1:-1};CV.ipag=100;cvPaintPick();});on("[data-cvrx]",b=>b.onclick=()=>{CV.selRua=null;cvPaintPick();});
