  x.font=f;x.fillStyle=o.fg||"#0F172A";x.textAlign="center";x.textBaseline="middle";x.fillText(t,w/2,h/2+fs*0.04);const tx=new THREE.CanvasTexture(c);tx.minFilter=THREE.LinearFilter;
