/* ===== Prévia de Cargas (Transportes): cargas do dia, metas por rota, registro de faturadas e fechamentos.
   Dados compartilhados pelo painel "pcg" (cada item tem data de alteração; a versão mais nova vence). ===== */
const PCG={ld:false,d:{rotas:{},cargas:{},reg:{}},ver:0,tab:"prev",ui:{t:"diario",m:"",sl:"big",q:"",rq:"",rm:""},pubT:null,av:false,tm:null,dlg:null,regDirty:false,regMsg:""};
const PCG_RN="GOIANIA,BOM JESUS,PATOS,SUL DE MINAS,JUAZEIRO,EXTREMO SUL/VITORIA,BARBACENA,CARATINGA,JOÃO MONLEVADE,CURVELO,JANAUBA,ANAPOLIS,IRECE,CACU,JATAI,SÃO MIGUEL,POSSE,PASSOS,MANHUAÇU,BELO HORIZONTE,BOM JARDIM".split(",");
const PCG_META0={GOIANIA:60000,"BOM JESUS":40000,JUAZEIRO:35000};
const PCG_VEIC=["TRUCK","CARRETA","3/4","TOCO"],PCG_VC={TRUCK:"#103F79",CARRETA:"#F97316","3/4":"#16A34A",TOCO:"#0EA5E9"};
const PCG_ST=[["venda","Em venda","#94A3B8"],["mont","Montada","#0EA5E9"],["sep","Separada","#2563EB"],["fech","Fechada","#16A34A"],["fat","Faturada","#0F766E"]];
const PCG_MN=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
const pcgHoje=()=>{const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");};
const pcgBr=s=>s?String(s).split("-").reverse().join("/"):"";
const pcgId=p=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const pcgN=v=>{if(typeof v==="number")return v;const s=String(v||"").replace(/[^\d,.\-]/g,"");if(!s)return 0;if(s.indexOf(",")>=0)return +s.replace(/\./g,"").replace(",",".")||0;if(/^-?\d{1,3}(\.\d{3})+$/.test(s))return +s.replace(/\./g,"")||0;return +s||0;};
const pcgR$=v=>+v?BRL.format(+v):"";
const pcgVivos=c=>Object.values(PCG.d[c]).filter(x=>!x.del);
const pcgRotas=()=>pcgVivos("rotas").sort((a,b)=>a.n.localeCompare(b.n,"pt-BR"));
const pcgMeta=c=>{const r=PCG.d.rotas[String(c.rota||"").toUpperCase()];return r&&!r.del&&r.meta>0?+r.meta:0;};
const pcgVt=c=>(+c.vmont||0)+(+c.vfat||0);
const pcgFechada=c=>!!(+c.fat||(pcgMeta(c)&&pcgVt(c)>=pcgMeta(c)));
const pcgEtapa=c=>+c.fat?"fat":pcgFechada(c)?"fech":+c.sep?"sep":+c.mont?"mont":"venda";
const pcgPct=c=>{const m=pcgMeta(c);return m?Math.min(1,pcgVt(c)/m):null;};
const pcgPa=a=>{let m=0,v=0;a.forEach(c=>{const mm=pcgMeta(c);if(mm){m+=mm;v+=Math.min(pcgVt(c),mm);}});return m?v/m:null;};
const pcgFalta=a=>a.reduce((t,c)=>t+(pcgMeta(c)?Math.max(0,pcgMeta(c)-pcgVt(c)):0),0);
const pcgCargas=()=>pcgVivos("cargas").filter(c=>!c.arq).sort((a,b)=>String(a.rota).localeCompare(String(b.rota),"pt-BR"));
/* ---------- dados: local + compartilhado ---------- */
function pcgSeed(){const o={rotas:{},cargas:{},reg:{},mot:{}};PCG_RN.forEach(n=>{o.rotas[n]={n,meta:PCG_META0[n]||0,t:1};});return o;}
async function pcgLoad(){if(PCG.ld)return;PCG.ld=true;PCG.ui.m=pcgHoje().slice(0,7);PCG.ui.rm=PCG.ui.m;let o=null;try{o=await cvGet("pcg");}catch(e){}if(o&&o.d){PCG.d=o.d;PCG.ver=o.ver||0;PCG.regDirty=!!o.rd;PCG.regMsg=o.rm||"";}else PCG.d=pcgSeed();["rotas","cargas","reg","mot"].forEach(k=>{if(!PCG.d[k])PCG.d[k]={};});}
/* motoristas: código ↔ nome */
/* lista única: base de motoristas da Liberação + cadastrados no app (planilha Motoristas_Cadastro) + os que ficaram só na Prévia */
const pcgMots=()=>{const m=new Map();try{motTodos().forEach(x=>{const c=String(x.m||"").trim();if(c)m.set(c,{cod:c,nome:String(x.n||"").trim().toUpperCase(),tipo:x.t||"",src:x.novo?"cad":"lib"});});}catch(e){}pcgVivos("mot").forEach(x=>{const c=String(x.cod||"").trim();if(c&&!m.has(c))m.set(c,Object.assign({},x,{cod:c,src:"pcg"}));});return [...m.values()].sort((a,b)=>String(a.nome).localeCompare(String(b.nome),"pt-BR"));};
const pcgMotCod=c=>{c=String(c||"").trim();return c?pcgMots().find(m=>m.cod===c)||null:null;};
const pcgMotNome=n=>{n=norm(n||"").trim();return n?pcgMots().find(m=>norm(m.nome)===n)||null:null;};
const pcgDL=(ia,ib)=>'<datalist id="'+ia+'">'+pcgMots().map(m=>'<option value="'+esc(m.nome)+'">'+esc(m.cod)+'</option>').join("")+'</datalist><datalist id="'+ib+'">'+pcgMots().map(m=>'<option value="'+esc(m.cod)+'">'+esc(m.nome)+'</option>').join("")+'</datalist>';
const pcgMerge=(A,B)=>{const o={};["rotas","cargas","reg","mot"].forEach(k=>{o[k]=Object.assign({},A[k]||{});Object.entries((B&&B[k])||{}).forEach(([id,v])=>{if(v&&(!o[k][id]||(v.t||0)>(o[k][id].t||0)))o[k][id]=v;});});return o;};
const pcgLocal=()=>cvSet("pcg",{d:PCG.d,ver:PCG.ver,rd:PCG.regDirty,rm:PCG.regMsg});
async function pcgGuarda(){try{await pcgLocal();}catch(e){}clearTimeout(PCG.pubT);PCG.pubT=setTimeout(pcgPub,1200);}
function pcgSet(col,id,obj){if(col==="reg"||col==="mot")PCG.regDirty=true;obj.t=Date.now();obj.por=(LOGIN&&LOGIN.nome)||meuMat()||"";PCG.d[col][id]=obj;return pcgGuarda();}
function pcgAviso(er){if(PCG.av)return;PCG.av=true;toast(/inv|desconh|permiss|a[cç][aã]o/i.test(String(er||""))?"Prévia salva só neste aparelho: atualize o Apps Script (versão 78) para compartilhar.":"Prévia salva neste aparelho; não foi possível compartilhar agora.");}
const pcgPode=()=>gPerm("ce_pcg")||gPerm("ce_rtz")||meuMat()==="10000514";
async function pcgPub(){if(DEMO||!LOGIN||!navigator.onLine||!pcgPode())return;try{const j=await ppPost({acao:"painel_ler",painel:"pcg"});if(j&&!j.ok){pcgAviso(j.erro);return;}if(j&&j.dados){const d=await rzUnzip(j.dados);if(d&&d.d)PCG.d=pcgMerge(PCG.d,d.d);}
  const z=await rzZip({d:PCG.d});const w=await ppPost({acao:"painel_salvar",painel:"pcg",dados:Object.assign(z,{n:pcgCargas().length,em:fmtDT(new Date())})});if(w&&w.ok){PCG.ver=w.versao||PCG.ver;await pcgLocal();}else pcgAviso(w&&w.erro);}catch(e){pcgAviso(e.message);}if(PCG.regDirty)await pcgRegPub();}
/* registro de faturadas também gravado na planilha (aba Previa_Cargas_Registro) */
async function pcgRegPub(forca){if(DEMO||!LOGIN||!navigator.onLine)return {ok:false,erro:"sem conexão"};if(forca)PCG.regDirty=true;
  try{const mo=pcgMots().map(x=>({cod:x.cod,nome:x.nome,t:x.t||0,por:x.por||({lib:"Base da Liberação",cad:"Cadastro do app"}[x.src]||""),del:0})),it=Object.values(PCG.d.reg).map(x=>({id:x.id,d:x.d,rota:x.rota,veic:x.veic,mot:x.mot||"",mcod:x.mcod||"",val:+x.val||0,por:x.por||"",carga:x.carga||"",t:x.t||0,del:x.del?1:0}));const j=await ppPost({acao:"pcg_reg_salvar",itens:it,mot:mo});
    if(j&&j.ok){PCG.regDirty=false;PCG.regMsg="Gravado na planilha (aba "+(j.aba||"Previa_Cargas_Registro")+") em "+fmtDT(new Date())+" · "+j.total+" lançamento(s)";}
    else PCG.regMsg="Não gravou na planilha: "+(j&&j.erro&&/inv|desconh|a[cç][aã]o/i.test(j.erro)?"atualize o Apps Script (versão 79)":(j&&j.erro)||"sem resposta")+". Vai tentar de novo na próxima alteração.";
    await pcgLocal();const el=$("pcg-gs");if(el){el.textContent=PCG.regMsg;el.className="pcg-gs"+(PCG.regDirty?" er":"");}return j||{ok:false};}catch(e){return {ok:false,erro:e.message};}}
async function pcgSync(forca){if(DEMO||!LOGIN||!navigator.onLine)return false;try{const v=await ppPost({acao:"painel_ver",painel:"pcg"});if(!v||!v.ok){if(forca)pcgAviso(v&&v.erro);return false;}if(!v.versao||(!forca&&v.versao<=PCG.ver))return false;
  const j=await ppPost({acao:"painel_ler",painel:"pcg"});if(!j||!j.ok||!j.dados)return false;const d=await rzUnzip(j.dados);if(!d||!d.d)return false;PCG.d=pcgMerge(PCG.d,d.d);PCG.ver=j.versao||v.versao;await pcgLocal();return true;}catch(e){return false;}}
/* ---------- visuais ---------- */
const pcgRing=(p,c,sz)=>{sz=sz||46;const r=sz/2-5,C=2*Math.PI*r;return '<svg class="pcg-ring" viewBox="0 0 '+sz+' '+sz+'" width="'+sz+'" height="'+sz+'"><circle cx="'+sz/2+'" cy="'+sz/2+'" r="'+r+'" fill="none" stroke="var(--line)" stroke-width="5"/>'+(p!=null?'<circle cx="'+sz/2+'" cy="'+sz/2+'" r="'+r+'" fill="none" stroke="'+c+'" stroke-width="5" stroke-linecap="round" stroke-dasharray="'+(C*p).toFixed(1)+' '+C.toFixed(1)+'" transform="rotate(-90 '+sz/2+' '+sz/2+')"/>':'')+'<text x="50%" y="54%" text-anchor="middle" dominant-baseline="middle">'+(p==null?"—":Math.round(p*100)+"%")+'</text></svg>';};
const pcgBar=p=>p==null?'<span class="pcg-sm">sem meta</span>':'<span class="pcg-bar"><i style="width:'+(p*100).toFixed(1)+'%;background:'+(p>=1?"#16A34A":p>=0.7?"#F59E0B":"#F97316")+'"></i></span><b>'+Math.round(p*100)+'%</b>';
function pcgKpis(){const C=pcgCargas(),F=C.filter(pcgFechada),N=C.filter(c=>!pcgFechada(c)),tot=F.filter(c=>!+c.fat).reduce((a,c)=>a+pcgVt(c),0),mt=N.filter(c=>+c.mont).length,pa=pcgPa(N),fal=pcgFalta(N),hj=pcgHoje(),rh=pcgVivos("reg").filter(r=>r.d===hj);
  return {C,F,N,tot,mt,pa,fal,fh:rh.length,fv:rh.reduce((s,r)=>s+(+r.val||0),0)};}
function pcgEsteira(C){return '<div class="pcg-est">'+PCG_ST.map(([k,l,c])=>{const L=C.filter(x=>pcgEtapa(x)===k);return '<div class="pcg-col" style="--c:'+c+'"><h4><span>'+l+'</span><b>'+L.length+'</b></h4><div class="pcg-cl">'+(L.length?L.map(x=>{const p=pcgPct(x),m=pcgMeta(x);return '<button type="button" class="pcg-card" data-pcge="'+esc(x.id)+'" data-rztip="'+esc(x.rota+" · "+x.veic+(x.mot?" · "+x.mot:"")+" · vendido "+BRL.format(+x.vend||0)+" · montado "+BRL.format(+x.vmont||0)+" · faturado "+BRL.format(+x.vfat||0)+(m?" · meta "+BRL.format(m)+" · falta "+BRL.format(Math.max(0,m-pcgVt(x))):" · rota sem meta")+" · clique para editar")+'">'+pcgRing(p,c)+'<span class="pcg-ci"><b>'+esc(x.rota)+'</b><small>'+esc(x.veic)+(x.mot?' · '+esc(x.mot):'')+(x.box?' · box '+esc(x.box):'')+'</small><small>'+(+x.fat?"FATURADO":m?(pcgVt(x)>=m?"meta atingida":"falta "+rzBRL(m-pcgVt(x))):"sem meta")+(x.saida?' · sai '+pcgBr(x.saida).slice(0,5):'')+'</small></span><span class="pcg-dots" aria-hidden="true"><i class="'+(+x.mont?"on":"")+'" title="Montado">M</i><i class="'+(+x.sep?"on":"")+'" title="Separado">S</i><i class="'+(+x.fat?"on":"")+'" title="Faturado">F</i></span></button>';}).join(""):'<p class="pcg-vz">—</p>')+'</div></div>';}).join("")+'</div>';}
function pcgTermo(N){const L=N.filter(c=>pcgMeta(c)).sort((a,b)=>pcgPct(b)-pcgPct(a));if(!L.length)return '<p class="note">Nenhuma carga incompleta com meta.</p>';
  return '<div class="pcg-tm">'+L.map(c=>{const m=pcgMeta(c),v=pcgVt(c),vd=+c.vend||0,mx=Math.max(m,v,vd)*1.08,pm=(+c.vmont||0)/mx*100,pf=(+c.vfat||0)/mx*100;return '<div class="pcg-tr" data-pcge="'+esc(c.id)+'" data-rztip="'+esc(c.rota+" · meta "+BRL.format(m)+" · montado "+BRL.format(+c.vmont||0)+" · faturado "+BRL.format(+c.vfat||0)+(vd?" · vendido "+BRL.format(vd):"")+" · falta "+BRL.format(Math.max(0,m-v))+" · clique para editar")+'"><span class="pcg-trn">'+esc(c.rota)+'</span><span class="pcg-trb"><i style="width:'+pm+'%;background:#2563EB"></i><i style="left:'+pm+'%;width:'+pf+'%;background:#0F766E"></i>'+(vd?'<u style="left:'+Math.min(100,vd/mx*100)+'%" title="vendido"></u>':'')+'<em style="left:'+(m/mx*100)+'%"></em></span><b>'+Math.round(Math.min(1,v/m)*100)+'%</b><small>falta '+rzBRL(Math.max(0,m-v))+'</small></div>';}).join("")+'</div><p class="pcg-lg"><i style="background:#2563EB"></i>montado <i style="background:#0F766E"></i>faturado <i class="ln"></i>meta da rota <i class="vd"></i>vendido</p>';}
const pcgTF=(a,dlg)=>'<table class="pcg-t"><thead><tr><th>Carga</th><th>Valor</th><th>Veículo</th><th>Motorista</th><th>Box</th></tr></thead><tbody>'+(a.length?a.map(c=>'<tr'+(dlg?' data-pcge="'+esc(c.id)+'"':'')+'><td><b>'+esc(c.rota)+'</b></td><td>'+(+c.fat?'<span class="pcg-tag ok">FATURADO</span>':BRL.format(pcgVt(c)))+'</td><td>'+esc(c.veic)+'</td><td>'+esc(c.mot||"")+'</td><td>'+esc(c.box||"")+'</td></tr>').join(""):'<tr><td colspan="5" class="pcg-sm">Nenhuma carga fechada.</td></tr>')+'</tbody></table>';
const pcgTN=(a,dlg)=>'<table class="pcg-t"><thead><tr><th>Carga incompleta</th><th>Box</th><th>Vendido</th><th>% da meta</th>'+(dlg?'<th>% montado</th>':'')+'<th>Valor que falta</th><th>Montado</th><th>Separado</th><th>Saída</th></tr></thead><tbody>'+(a.length?a.map(c=>{const m=pcgMeta(c);return '<tr'+(dlg?' data-pcge="'+esc(c.id)+'"':'')+'><td><b>'+esc(c.rota)+'</b></td><td>'+esc(c.box||"")+'</td><td>'+(+c.vend?BRL.format(+c.vend):"—")+'</td><td class="pcg-pc">'+pcgBar(pcgPct(c))+'</td>'+(dlg?'<td class="pcg-pc">'+pcgBar(m?Math.min(1,(+c.vmont||0)/m):null)+'</td>':'')+'<td>'+(m?BRL.format(Math.max(0,m-pcgVt(c))):'<span class="pcg-no">sem meta</span>')+'</td><td class="'+(+c.mont?'':'pcg-no')+'">'+(+c.mont?"SIM":"NÃO")+'</td><td class="'+(+c.sep?'':'pcg-no')+'">'+(+c.sep?"SIM":"NÃO")+'</td><td>'+pcgBr(c.saida)+'</td></tr>';}).join(""):'<tr><td colspan="'+(dlg?9:8)+'" class="pcg-sm">Nenhuma carga incompleta.</td></tr>')+'</tbody></table>';
/* ---------- abas ---------- */
function pcgVPrev(){const k=pcgKpis();
  let h='<div class="cv-kpis pcg-kp">'+[["Fechado",rzBRL(k.tot),"#16A34A","valor das fechadas (sem as faturadas)"],["Cargas fechadas",cvFmt(k.F.length),"#0F766E",""],["Cargas incompletas",cvFmt(k.N.length),k.N.length?"#F97316":"#16A34A",""],["Incompletas montadas",k.mt+"/"+k.N.length,"#0369A1",""],["% das incompletas",k.pa==null?"—":Math.round(k.pa*100)+"%","#B45309","do valor das metas"],["Valor que falta",rzBRL(k.fal),k.fal?"#DC2626":"#16A34A","para fechar as incompletas"],["Faturadas hoje",cvFmt(k.fh),"#103F79",k.fv?rzBRL(k.fv):"no registro"]].map(([t,v,c,s])=>'<div class="cv-k"><span>'+t+'</span><b style="color:'+c+'">'+v+'</b>'+(s?'<small class="muted">'+s+'</small>':'')+'</div>').join("")+'</div>';
  if(!k.C.length)return h+'<div class="block pcg-empty"><h3>Nenhuma carga na prévia</h3><p class="note">Cadastre as cargas do dia para acompanhar quanto falta para cada rota fechar.</p><button type="button" class="save" data-pcga="nova" style="max-width:260px">+ Nova carga</button></div>';
  h+='<div class="block"><div class="pcg-hh"><h3>Esteira das cargas <small>· clique numa carga para editar</small></h3><button type="button" class="btn sm" data-pcga="nova">+ Nova carga</button></div>'+pcgEsteira(k.C)+'</div>';
  h+='<div class="block"><h3>Termômetro das incompletas <small>· quanto cada carga já tem em relação à meta da rota</small></h3>'+pcgTermo(k.N)+'</div>';
  h+='<div class="pcg-g2"><div class="block pcg-tb"><div class="pcg-sub ok"><span>FECHADO</span><span>'+BRL.format(k.tot)+'</span></div><div class="cv-tw">'+pcgTF(k.F,1)+'</div></div><div class="block pcg-tb"><div class="pcg-sub"><span>INCOMPLETO · '+(k.pa==null?"—":Math.round(k.pa*100)+"%")+' · falta '+BRL.format(k.fal)+'</span><span>'+k.N.length+' cargas</span></div><div class="cv-tw">'+pcgTN(k.N,1)+'</div></div></div>';
  return h+'<p class="note">A carga fecha quando o valor montado + faturado chega na meta da rota (aba Rotas) ou quando é marcada como faturada.</p>';}
function pcgVCargas(){const q=norm(PCG.ui.q||"").trim(),C=pcgCargas().filter(c=>!q||norm(c.rota+" "+c.mot+" "+c.box+" "+c.veic).includes(q));
  return '<div class="block"><div class="pcg-hh"><h3>Cargas em aberto <small>· '+C.length+'</small></h3><div class="pcg-ctl"><input class="pcg-in" type="search" id="pcg-q" placeholder="Filtrar rota, motorista, box" value="'+esc(PCG.ui.q)+'"><button type="button" class="save pcg-bt" data-pcga="nova">+ Nova carga</button></div></div><div class="cv-tw"><table class="pcg-t pcg-ed"><thead><tr><th>Rota</th><th>Veículo</th><th>Motorista</th><th>Box</th><th>Vendido</th><th>Montado</th><th>Faturado</th><th>Meta</th><th>% total</th><th>Mont.</th><th>Sep.</th><th>Fat.</th><th>Saída</th><th>Etapa</th></tr></thead><tbody>'+
    (C.length?C.map(c=>{const e=PCG_ST.find(s=>s[0]===pcgEtapa(c)),m=pcgMeta(c);return '<tr data-pcge="'+esc(c.id)+'"><td><b>'+esc(c.rota)+'</b></td><td>'+esc(c.veic)+'</td><td>'+esc(c.mot||"")+'</td><td>'+esc(c.box||"")+'</td><td>'+(+c.vend?BRL.format(+c.vend):"—")+'</td><td>'+(+c.vmont?BRL.format(+c.vmont):"—")+'</td><td>'+(+c.vfat?BRL.format(+c.vfat):"—")+'</td><td>'+(m?BRL.format(m):'<span class="pcg-no">sem meta</span>')+'</td><td class="pcg-pc">'+pcgBar(pcgPct(c))+'</td>'+
      ["mont","sep","fat"].map(f=>'<td><button type="button" class="pcg-tg'+(+c[f]?" on":"")+'" data-pcgt="'+f+'" aria-pressed="'+(!!+c[f])+'" title="'+({mont:"Montado",sep:"Separado",fat:"Faturado (fecha direto)"}[f])+'">'+(+c[f]?"SIM":"NÃO")+'</button></td>').join("")+'<td>'+pcgBr(c.saida)+'</td><td><span class="pcg-tag" style="--c:'+e[2]+'">'+e[1]+'</span></td></tr>';}).join(""):'<tr><td colspan="14" class="pcg-sm">Nenhuma carga em aberto.</td></tr>')+'</tbody></table></div><p class="note">Clique numa linha para editar todos os dados. SIM/NÃO muda na hora.</p></div>';}
function pcgVRotas(){const R=pcgRotas(),reg=pcgVivos("reg"),st={};reg.forEach(r=>{const o=st[r.rota]=st[r.rota]||{n:0,v:0,u:""};o.n++;o.v+=+r.val||0;if(r.d>o.u)o.u=r.d;});const ab={};pcgCargas().forEach(c=>{ab[c.rota]=(ab[c.rota]||0)+1;});
  return '<div class="block pcg-edit"><h3>Nova rota</h3><div class="pcg-ctl"><input class="pcg-in" id="pcg-rn" placeholder="Nome da rota"><input class="pcg-in pcg-money" id="pcg-rmeta" inputmode="decimal" placeholder="Meta por carga (R$ 0,00)"><button type="button" class="save pcg-bt" data-pcga="rota">+ Adicionar rota</button></div></div>'+
    '<div class="block"><h3>Metas por rota <small>· valor para a carga fechar · '+R.length+' rotas · '+R.filter(r=>r.meta>0).length+' com meta</small></h3><div class="cv-tw"><table class="pcg-t"><thead><tr><th>Rota</th><th>Meta por carga (R$)</th><th>Gerente</th><th>Cargas em aberto</th><th>Faturadas no registro</th><th>Média faturada</th><th>Último faturamento</th><th></th></tr></thead><tbody>'+
    R.map(r=>{const s=st[r.n];return '<tr><td><b>'+esc(r.n)+'</b></td><td><input class="pcg-in pcg-nm pcg-money" data-pcgm="'+esc(r.n)+'" inputmode="decimal" value="'+pcgR$(r.meta)+'" placeholder="sem meta"></td><td><input class="pcg-in" data-pcgg="'+esc(r.n)+'" value="'+esc(r.ger||"")+'" placeholder="a definir" list="pcg-gl" style="min-width:170px"></td><td>'+(ab[r.n]||"—")+'</td><td>'+(s?s.n:"—")+'</td><td>'+(s?BRL.format(s.v/s.n):"—")+'</td><td>'+(s?pcgBr(s.u):"—")+'</td><td><button type="button" class="pcg-x" data-pcgrd="'+esc(r.n)+'" aria-label="Excluir rota '+esc(r.n)+'">✕</button></td></tr>';}).join("")+'</tbody></table></div><datalist id="pcg-gl">'+[...new Set(R.map(r=>r.ger).filter(Boolean))].map(g=>'<option value="'+esc(g)+'">').join("")+'</datalist><p class="note">Meta vazia = rota sem meta (a carga só fecha quando for marcada como faturada). O gerente de cada rota alimenta o "Faturado por gerente" nos fechamentos.</p></div>';}
function pcgVReg(){const m=PCG.ui.rm,q=norm(PCG.ui.rq||"").trim(),L=pcgVivos("reg").filter(r=>(!m||String(r.d).slice(0,7)===m)&&(!q||norm(r.rota+" "+r.mot+" "+(r.mcod||"")).includes(q))).sort((a,b)=>String(b.d).localeCompare(String(a.d))||(b.t-a.t)),tv=L.reduce((s,r)=>s+(+r.val||0),0),fe=pcgCargas().filter(pcgFechada).length;
  return '<div class="block pcg-edit"><div class="pcg-hh"><h3>Lançar faturamento</h3><button type="button" class="btn sm" data-pcga="lancar"'+(fe?'':' disabled')+'>⇩ Lançar as '+fe+' fechadas da prévia (hoje)</button></div><div class="pcg-ctl pcg-fr"><label>Data<input class="pcg-in" type="date" id="pcg-gd" value="'+pcgHoje()+'"></label><label>Rota<select class="pcg-in" id="pcg-gr">'+pcgRotas().map(r=>'<option>'+esc(r.n)+'</option>').join("")+'</select></label><label>Veículo<select class="pcg-in" id="pcg-gv">'+PCG_VEIC.map(v=>'<option>'+v+'</option>').join("")+'</select></label><label style="flex:0 1 110px">Cód. motorista<input class="pcg-in" id="pcg-gc" inputmode="numeric" autocomplete="off" placeholder="código"></label><label style="flex:2 1 200px">Motorista<input class="pcg-in" id="pcg-gm" autocomplete="off" placeholder="nome (o código vem sozinho)"></label><label>Valor faturado<input class="pcg-in pcg-money" id="pcg-gval" inputmode="decimal" placeholder="R$ 0,00"></label><button type="button" class="save pcg-bt" data-pcga="reg">Adicionar</button></div><p class="note">Cada linha é um caminhão carregado/faturado; os fechamentos leem esta lista. Ao lançar as fechadas da prévia, elas saem da prévia.</p></div>'+
    '<div class="block"><div class="pcg-hh"><h3>Registro de cargas faturadas <small>· '+L.length+' · '+BRL.format(tv)+'</small></h3><div class="pcg-ctl"><input class="pcg-in" type="month" id="pcg-rm" value="'+esc(m)+'"><input class="pcg-in" type="search" id="pcg-rq" placeholder="Filtrar rota ou motorista" value="'+esc(PCG.ui.rq)+'"><button type="button" class="btn sm" data-pcga="xlsreg">⬇ Excel</button><button type="button" class="btn sm" data-pcga="gs">⇪ Gravar no Google Sheets</button></div></div><p id="pcg-gs" class="pcg-gs'+(PCG.regDirty?" er":"")+'">'+esc(PCG.regMsg||(PCG.regDirty?"Alterações ainda não gravadas na planilha.":"Cada lançamento é gravado na planilha, na aba Previa_Cargas_Registro."))+'</p><div class="cv-tw" style="max-height:560px"><table class="pcg-t"><thead><tr><th>Data</th><th>Rota</th><th>Veículo</th><th>Cód.</th><th>Motorista</th><th>Valor faturado</th><th>Lançado por</th><th></th></tr></thead><tbody>'+
    (L.length?L.slice(0,400).map(r=>'<tr><td>'+pcgBr(r.d)+'</td><td><b>'+esc(r.rota)+'</b></td><td><span class="pcg-vd" style="--c:'+(PCG_VC[r.veic]||"#64748B")+'">'+esc(r.veic)+'</span></td><td>'+esc(r.mcod||"—")+'</td><td>'+esc(r.mot||"")+'</td><td class="n">'+BRL.format(+r.val||0)+'</td><td class="pcg-sm">'+esc(r.por||"")+'</td><td><button type="button" class="pcg-x" data-pcgdr="'+esc(r.id)+'" aria-label="Excluir lançamento">✕</button></td></tr>').join(""):'<tr><td colspan="8" class="pcg-sm">Nenhum lançamento neste mês.</td></tr>')+'</tbody></table></div></div>'+pcgVMot();}
function pcgVMot(){const A=pcgMots(),q=norm(PCG.ui.mq||"").trim(),M=A.filter(m=>!q||norm(m.cod+" "+m.nome).includes(q)),st={};pcgVivos("reg").forEach(r=>{if(!r.mcod)return;const o=st[r.mcod]=st[r.mcod]||{n:0,v:0,u:""};o.n++;o.v+=+r.val||0;if(r.d>o.u)o.u=r.d;});
  return '<div class="block" id="pcg-motb"><h3>Motoristas <small>· '+A.length+' · os mesmos da Liberação de mercadorias; o código preenche o nome nos lançamentos e nas cargas</small></h3><div class="pcg-ctl pcg-fr pcg-edit"><label style="flex:0 1 160px">Código / matrícula<input class="pcg-in" id="pcg-nc" inputmode="numeric" autocomplete="off" placeholder="ex.: 10009845"></label><label style="flex:2 1 260px">Nome do motorista<input class="pcg-in" id="pcg-nn" autocomplete="off" placeholder="Nome completo"></label><button type="button" class="save pcg-bt" data-pcga="mot">+ Cadastrar motorista</button></div><div class="pcg-ctl" style="margin-top:10px"><input class="pcg-in" type="search" id="pcg-mq" placeholder="Buscar código ou nome" value="'+esc(PCG.ui.mq||"")+'" style="max-width:320px"><span class="pcg-sm">'+M.length+' de '+A.length+'</span></div>'+
    (M.length?'<div class="cv-tw" style="max-height:420px;margin-top:10px"><table class="pcg-t"><thead><tr><th>Código</th><th>Nome</th><th>Origem</th><th>Cargas faturadas</th><th>Valor faturado</th><th>Última carga</th><th></th></tr></thead><tbody>'+M.slice(0,300).map(m=>{const s=st[m.cod],ed=m.src==="pcg";return '<tr><td><b>'+esc(m.cod)+'</b></td><td>'+(ed?'<input class="pcg-in" data-pcgmn="'+esc(m.cod)+'" value="'+esc(m.nome)+'" aria-label="Nome do motorista '+esc(m.cod)+'" style="min-width:220px">':esc(m.nome))+'</td><td><span class="pcg-tag" style="--c:'+({lib:"#103F79",cad:"#0F766E",pcg:"#B45309"}[m.src])+'">'+({lib:"Liberação",cad:"Cadastro do app",pcg:"Só na Prévia"}[m.src])+(m.tipo?' · '+esc(m.tipo):'')+'</span></td><td>'+(s?s.n:"—")+'</td><td class="n">'+(s?BRL.format(s.v):"—")+'</td><td>'+(s?pcgBr(s.u):"—")+'</td><td>'+(ed?'<button type="button" class="pcg-x" data-pcgmd="'+esc(m.cod)+'" aria-label="Excluir motorista '+esc(m.nome)+'">✕</button>':'')+'</td></tr>';}).join("")+'</tbody></table></div>'+(M.length>300?'<p class="note">Mostrando 300 de '+M.length+': use a busca.</p>':''):'<p class="note">Nenhum motorista encontrado.</p>')+'</div>';}
function pcgBuckets(){const u=PCG.ui,[y,m]=(u.m||pcgHoje().slice(0,7)).split("-").map(Number),B=[],last=new Date(y,m,0).getDate(),P=n=>String(n).padStart(2,"0"),R=pcgVivos("reg");
  const ag=(l,a,b,p)=>{const o={l,p:p||l,a,b,q:{},v:{},tq:0,tv:0,rot:{}};PCG_VEIC.forEach(k=>{o.q[k]=0;o.v[k]=0;});R.forEach(r=>{if(r.d>=a&&r.d<=b){const k=PCG_VEIC.includes(r.veic)?r.veic:"TRUCK",v=+r.val||0;o.q[k]++;o.v[k]+=v;o.tq++;o.tv+=v;o.rot[r.rota]=(o.rot[r.rota]||0)+v;}});return o;};
  if(u.t==="diario")for(let d=1;d<=last;d++){const s=y+"-"+P(m)+"-"+P(d);B.push(ag(P(d),s,s,pcgBr(s)));}
  else if(u.t==="semanal"){let d=1,k=1;while(d<=last){const w=(new Date(y,m-1,d).getDay()+6)%7,e=Math.min(last,d+6-w);B.push(ag("Sem "+k++,y+"-"+P(m)+"-"+P(d),y+"-"+P(m)+"-"+P(e),P(d)+"/"+P(m)+" a "+P(e)+"/"+P(m)));d=e+1;}}
  else for(let i=1;i<=12;i++)B.push(ag(PCG_MN[i-1].slice(0,3),y+"-"+P(i)+"-01",y+"-"+P(i)+"-31",PCG_MN[i-1]+"/"+y));
  return B;}
function pcgStack(B,key,money){const W=760,H=270,pl=50,pr=8,pt=22,pb=30,n=B.length,tot=x=>key==="q"?x.tq:x.tv,mx=rzNice(Math.max(1,...B.map(tot))*1.08).top,bw=(W-pl-pr)/n,hh=H-pt-pb,fm=v=>money?rzK(v):cvFmt(v);
  let s='<svg class="rz-svg" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="xMidYMid meet">';[0,.25,.5,.75,1].forEach(f=>{const y=H-pb-hh*f;s+='<line x1="'+pl+'" x2="'+(W-pr)+'" y1="'+y+'" y2="'+y+'" stroke="var(--line)"/><text x="'+(pl-6)+'" y="'+(y+4)+'" text-anchor="end" class="rz-ax">'+fm(mx*f)+'</text>';});
  B.forEach((x,i)=>{const X=pl+i*bw+bw*.14,w=bw*.72;let y=H-pb;PCG_VEIC.forEach(k=>{const v=x[key][k],h=hh*v/mx;if(h>0){y-=h;s+='<rect x="'+X.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+h.toFixed(1)+'" fill="'+PCG_VC[k]+'" rx="'+(Math.min(3,w/4))+'"/>';}});
    const t=tot(x);if(t&&(n<=16||w>14))s+='<text x="'+(X+w/2).toFixed(1)+'" y="'+(y-5).toFixed(1)+'" text-anchor="middle" class="pcg-lb">'+fm(t)+'</text>';
    if(n<=16||i%Math.ceil(n/16)===0)s+='<text x="'+(X+w/2).toFixed(1)+'" y="'+(H-10)+'" text-anchor="middle" class="rz-ax">'+esc(x.l)+'</text>';
    s+='<rect class="rz-hd" x="'+(pl+i*bw).toFixed(1)+'" y="'+pt+'" width="'+bw.toFixed(1)+'" height="'+hh+'" fill="transparent" data-rztip="'+esc(x.p+" · "+PCG_VEIC.filter(k=>x.q[k]).map(k=>k+": "+x.q[k]+" · "+BRL.format(x.v[k])).join(" · ")+(x.tq?" · total "+x.tq+" caminhão(ões) · "+BRL.format(x.tv):" · sem faturamento"))+'"/>';});
  return s+'</svg><p class="pcg-lg">'+PCG_VEIC.map(k=>'<i style="background:'+PCG_VC[k]+'"></i>'+k).join(" ")+'</p>';}
function pcgGer(rota){const r=PCG.d.rotas[String(rota||"").toUpperCase()];return r&&!r.del&&r.ger?String(r.ger):"";}
function pcgVFech(){const u=PCG.ui,B=pcgBuckets(),T={q:{},v:{},tq:0,tv:0,rot:{}};PCG_VEIC.forEach(k=>{T.q[k]=0;T.v[k]=0;});B.forEach(x=>{PCG_VEIC.forEach(k=>{T.q[k]+=x.q[k];T.v[k]+=x.v[k];});T.tq+=x.tq;T.tv+=x.tv;Object.entries(x.rot).forEach(([r,v])=>{T.rot[r]=(T.rot[r]||0)+v;});});
  const best=B.reduce((a,x)=>x.tv>(a?a.tv:0)?x:a,null),lbl={diario:"Dia",semanal:"Semana",mensal:"Mês"}[u.t],a0=B.length?B[0].a:"",b0=B.length?B[B.length-1].b:"",RG=pcgVivos("reg").filter(r=>r.d>=a0&&r.d<=b0),dias=new Set(RG.map(r=>r.d)),hj=pcgHoje(),hoje=pcgVivos("reg").filter(r=>r.d===hj).length,K=pcgKpis();
  const G={};RG.forEach(r=>{const g=pcgGer(r.rota)||"Sem gerente definido",o=G[g]=G[g]||{n:0,v:0,rot:new Set()};o.n++;o.v+=+r.val||0;o.rot.add(r.rota);});const GL=Object.entries(G).sort((a,b)=>(a[0]==="Sem gerente definido")-(b[0]==="Sem gerente definido")||b[1].n-a[1].n);
  let h='<div class="block pcg-hh"><div class="pcg-seg">'+[["diario","Diário"],["semanal","Semanal"],["mensal","Mensal (ano)"]].map(([k,l])=>'<button type="button" data-pcgp="'+k+'"'+(u.t===k?' class="on"':'')+'>'+l+'</button>').join("")+'</div><input class="pcg-in" type="month" id="pcg-fm" value="'+esc(u.m)+'" style="max-width:190px"><button type="button" class="btn sm" data-pcga="xlsfech">⬇ Excel</button></div>';
  const kc=a=>'<div class="cv-kpis pcg-kp">'+a.map(([t,v,c,s,tip])=>'<div class="cv-k"'+(tip?' data-rztip="'+esc(tip)+'"':'')+'><span>'+t+'</span><b style="color:'+c+'">'+v+'</b>'+(s?'<small class="muted">'+s+'</small>':'')+'</div>').join("")+'</div>';
  h+=kc([["Caminhões fechados",cvFmt(T.tq),"#103F79","no período · "+rzBRL(T.tv)],["Caminhões fechados por dia",dias.size?cvFmt(T.tq/dias.size,1):"—","#0369A1","média de "+dias.size+" dia(s) com carga · hoje "+hoje,"Média de caminhões fechados (faturados) por dia com carga no período"],["Cargas incompletas",cvFmt(K.N.length),K.N.length?"#F97316":"#16A34A",K.N.length?"agora na prévia · falta "+rzBRL(K.fal):"nenhuma na prévia"],["Faturado",rzBRL(T.tv),"#16A34A",T.tq?rzBRL(T.tv/T.tq)+" por caminhão":""],["Melhor "+lbl.toLowerCase(),best&&best.tv?best.p:"—","#0F766E",best&&best.tv?best.tq+" caminhão(ões) · "+rzBRL(best.tv):""]]);
  h+='<div class="block"><h3>Quantidade por tipo de veículo</h3><div class="pcg-vk">'+PCG_VEIC.map(k=>'<div class="pcg-vki" style="--c:'+PCG_VC[k]+'" data-rztip="'+esc(k+" · "+T.q[k]+" caminhão(ões) · "+BRL.format(T.v[k])+(T.q[k]?" · média "+BRL.format(T.v[k]/T.q[k]):""))+'"><span>'+k+'</span><b>'+cvFmt(T.q[k])+'</b><small>'+(T.tq?cvFmt(T.q[k]/T.tq*100,0)+"% · ":"")+rzBRL(T.v[k])+'</small><i style="width:'+(T.tq?T.q[k]/T.tq*100:0)+'%"></i></div>').join("")+'</div></div>';
  h+='<div class="block"><div class="pcg-hh"><h3>Faturado por gerente <small>· quantidade de cargas faturadas no período</small></h3>'+(GL.some(g=>g[0]==="Sem gerente definido")?'<button type="button" class="btn sm" data-pcgtab="rotas">Definir gerente das rotas →</button>':'')+'</div>'+(GL.length?'<div class="pcg-gk">'+GL.map(([g,o])=>'<div class="pcg-gki'+(g==="Sem gerente definido"?' sem':'')+'" data-rztip="'+esc(g+" · "+o.n+" carga(s) · "+BRL.format(o.v)+" · rotas: "+[...o.rot].join(", "))+'"><span>'+esc(g)+'</span><b>'+cvFmt(o.n)+'</b><small>carga(s) · '+rzBRL(o.v)+'</small></div>').join("")+'</div>':'<p class="note">Sem cargas faturadas no período.</p>')+'</div>';
  if(!T.tq)return h+'<div class="block"><p class="note">Sem lançamentos no registro para este período. Lance as cargas faturadas na aba Registro.</p></div>';
  h+='<div class="rz-two"><div class="block"><h3>Caminhões carregados</h3>'+pcgStack(B,"q")+'</div><div class="block"><h3>Valor faturado</h3>'+pcgStack(B,"v",1)+'</div></div>';
  const RT=Object.entries(T.rot).sort((a,b)=>b[1]-a[1]).slice(0,10);
  h+='<div class="rz-two"><div class="block"><h3>Por tipo de veículo</h3>'+rzDonut(PCG_VEIC.filter(k=>T.q[k]).map(k=>({l:k+" · "+T.q[k]+" caminhão(ões)",lb:rzBRL(T.v[k]),v:T.v[k],c:PCG_VC[k],t:k+" · "+T.q[k]+" caminhão(ões) · "+BRL.format(T.v[k])+" · média "+BRL.format(T.v[k]/T.q[k])+" por caminhão · "+cvFmt(T.v[k]/T.tv*100,1)+"% do valor"})),rzBRL(T.tv),"faturado")+'</div>'+
    '<div class="block"><h3>Rotas que mais faturaram</h3>'+rzSvgCols(RT.map(([r,v],i)=>({l:r.length>12?r.slice(0,11)+"…":r,v,lb:rzK(v),c:i<3?"#103F79":"#2563EB",t:r+" · "+BRL.format(v)+" · "+cvFmt(v/T.tv*100,1)+"% do período"})),{h:270,w:560,todos:true,norot:true,pb:44})+'</div></div>';
  const row=x=>PCG_VEIC.map(k=>'<td class="n">'+(x.q[k]||"")+'</td>').join("")+'<td class="n"><b>'+x.tq+'</b></td>'+PCG_VEIC.map(k=>'<td class="n">'+(x.v[k]?BRL.format(x.v[k]):"")+'</td>').join("")+'<td class="n"><b>'+BRL.format(x.tv)+'</b></td>';
  h+='<div class="block"><h3>Tabela do período</h3><div class="cv-tw"><table class="pcg-t"><thead><tr><th>'+lbl+'</th>'+PCG_VEIC.map(k=>'<th>'+k+'</th>').join("")+'<th>Total</th>'+PCG_VEIC.map(k=>'<th>Fat. '+k+'</th>').join("")+'<th>Fat. total</th></tr></thead><tbody>'+B.filter(x=>x.tq||u.t!=="diario").map(x=>'<tr><td>'+esc(x.p)+'</td>'+row(x)+'</tr>').join("")+'</tbody><tfoot><tr><td><b>TOTAL</b></td>'+row(T)+'</tr></tfoot></table></div></div>';
  return h;}
