    const md=e.target.closest("[data-pcgmd]");if(md){const m=pcgMotCod(md.dataset.pcgmd);if(!m||m.src!=="pcg"||!confirm("Excluir o motorista "+m.nome+" (código "+m.cod+")? Os lançamentos já feitos continuam com o nome dele."))return;await pcgSet("mot",m.cod,Object.assign({},m,{del:1}));pcgPaint();return;}
    const dr=e.target.closest("[data-pcgdr]");if(dr){const r=PCG.d.reg[dr.dataset.pcgdr];if(!r||!confirm("Excluir o lançamento de "+r.rota+" ("+pcgBr(r.d)+", "+BRL.format(+r.val||0)+")?"))return;await pcgSet("reg",r.id,Object.assign({},r,{del:1}));pcgPaint();return;}
    const a=e.target.closest("[data-pcga]");if(!a)return;const ac=a.dataset.pcga;
