const cvlPodeSol=()=>temPerm("vc_sol")||temPerm("vc_apr")||temPerm("aud_adm");
const cvlD=s=>{const m=String(s||"").match(/^(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d{2}):(\d{2}))?/);return m?new Date(+m[3],+m[2]-1,+m[1],+(m[4]||0),+(m[5]||0)).getTime():0;};
const cvlMes=s=>{const m=String(s||"").match(/^\d{2}\/(\d{2})\/(\d{4})/);return m?m[2]+"-"+m[1]:"";};
const cvlHa=s=>{const t=cvlD(s);if(!t)return "";const m=Math.round((Date.now()-t)/60000);return m<1?"agora":m<60?"há "+m+" min":m<1440?"há "+Math.round(m/60)+" h":"há "+Math.round(m/1440)+" dia(s)";};
const cvlChip=s=>'<span class="cvl-st" style="--c:'+(CVL_ST[s]||"#64748B")+'">'+esc(s||"—")+'</span>';
const cvlVal=r=>+String(r.Valor||"0").replace(",",".")||0;
const cvlIt=r=>{try{const a=JSON.parse(r.Itens||"[]");return Array.isArray(a)?a:[];}catch(e){return [];}};
const cvlQ=n=>(+n||0).toLocaleString("pt-BR",{maximumFractionDigits:3});
const cvlUn=i=>i.un||unDe(i.cod);
const cvlItResumo=r=>{const I=cvlIt(r);return I.length?I.slice(0,3).map(i=>i.desc+" ("+unQtd(i.qtd,cvlUn(i))+")").join(" · ")+(I.length>3?" · +"+(I.length-3)+" item(ns)":""):"";};
async function cvlCarregar(quieto){if(DEMO||!LOGIN){CVL.ld=true;return false;}try{const j=await ppPost({acao:"vc_listar"});if(!j||!j.ok){CVL.erro=(j&&j.erro)||"Não foi possível carregar os vales.";if(/desconh|inv/i.test(CVL.erro))CVL.erro="Atualize o Apps Script (versão 83) para usar a Central de Vales.";CVL.ld=true;return false;}
  const sig=JSON.stringify(j.vales).length+"|"+(j.vales||[]).map(v=>v.ID+v.Status).join(",").length+"|"+(j.minhaAssinatura||"");const mud=sig!==CVL.sig;CVL.sig=sig;CVL.rows=j.vales||[];CVL.apr=!!j.aprovador;CVL.emi=!!j.emissor;CVL.todos=!!j.todos;Object.assign(CVL.sigs,j.assinaturas||{});CVL.minhaSig=j.minhaAssinatura||"";CVL.erro="";CVL.ld=true;cvlBadge();return mud||!quieto;}catch(e){CVL.erro="Sem conexão com a planilha agora.";CVL.ld=true;return false;}}
function cvlBadge(){const b=document.querySelector('nav button[data-v="cvl"]');if(!b)return;const n=CVL.apr&&VALE_APROVADORES.includes(meuMat())?CVL.rows.filter(r=>r.Status==="Pendente"&&String(r.Colaborador_Mat)!==meuMat()).length:0;let s=b.querySelector(".cvl-bd");if(n){if(!s){s=document.createElement("b");s.className="cvl-bd";b.appendChild(s);}s.textContent=n;}else if(s)s.remove();}
/* ---------- sugestões (colaborador e produto) só depois que para de digitar ---------- */
function cvlColabs(q){q=norm(q||"").trim();if(q.length<3)return [];const d=q.replace(/\D/g,""),R=[];for(let i=0;i<C.mat.length&&R.length<60;i++){const m=String(C.mat[i]),n=norm(C.nome[i]||"");if((d&&d.length>=3&&m.startsWith(d))||(!d&&(n.startsWith(q)||n.split(/\s+/).some(p=>p.startsWith(q)))))R.push({m,n:C.nome[i],f:C.fun[i]||""});}return R.sort((a,b)=>(norm(b.n).startsWith(q)?1:0)-(norm(a.n).startsWith(q)?1:0)).slice(0,7);}
function cvlColabAchar(v){const d=String(v||"").replace(/\D/g,"");if(d&&cIdx.has(d)){const i=cIdx.get(d);return {m:d,n:C.nome[i],f:C.fun[i]||""};}const n=norm(v||"").trim();if(!n)return null;const i=C.nome.findIndex(x=>norm(x||"")===n);return i>=0?{m:String(C.mat[i]),n:C.nome[i],f:C.fun[i]||""}:null;}
const cvlProd=i=>({cod:String(P.cod[i]),desc:P.desc[i]||"",custo:+P.vl[i]||0,un:unDe(P.cod[i])});
function cvlProdAchar(v){const d=String(v||"").trim().replace(/^0+/,"");if(/^\d+$/.test(d)&&pIdx.has(d))return cvlProd(pIdx.get(d));return null;}
function cvlProds(q){const t=norm(q||"").trim();if(t.length<3)return [];const d=t.replace(/\D/g,""),R=[];if(/^\d+$/.test(t)){for(let i=0;i<P.cod.length&&R.length<8;i++)if(String(P.cod[i]).startsWith(d))R.push(cvlProd(i));return R;}
  const w=t.split(/\s+/).filter(Boolean);for(let i=0;i<P.cod.length&&R.length<40;i++){const n=P.n[i]||"";if(w.every(x=>n.includes(x)))R.push(cvlProd(i));}return R.sort((a,b)=>(norm(b.desc).startsWith(t)?1:0)-(norm(a.desc).startsWith(t)?1:0)).slice(0,8);}
let CVL_SUG={t:null,box:null};function cvlSugFecha(){clearTimeout(CVL_SUG.t);if(CVL_SUG.box)CVL_SUG.box.remove();CVL_SUG.box=null;}
function cvlSugMostra(inp,L,lin,usa,vazio){cvlSugFecha();const r=inp.getBoundingClientRect(),b=document.createElement("div");b.className="pcg-sug";b.style.left=Math.max(8,Math.min(r.left,innerWidth-380))+"px";b.style.top=(r.bottom+4)+"px";b.style.minWidth=Math.max(r.width,320)+"px";
  b.innerHTML=L.length?L.map((x,i)=>'<button type="button" data-i="'+i+'">'+lin(x)+'</button>').join(""):'<small>'+vazio+'</small>';b.addEventListener("mousedown",ev=>{ev.preventDefault();const o=ev.target.closest("[data-i]");if(o){cvlSugFecha();usa(L[+o.dataset.i]);}});document.body.appendChild(b);CVL_SUG.box=b;}
function cvlUsaColab(c){CVL.sel=c;const i=$("cvl-col");if(i)i.value=c.n;const s=$("cvl-colinfo");if(s)s.innerHTML=cvlColabInfo(c);cvlSugFecha();}
function cvlUsaProd(p){CVL.psel=p;const i=$("cvl-prod");if(i)i.value=p.cod+" – "+p.desc;const s=$("cvl-pinfo");if(s)s.innerHTML=cvlPInfo(p);cvlQtdLab(p);cvlSugFecha();const q=$("cvl-qtd");if(q){q.focus();q.select();}}
const cvlPInfo=p=>p?'<span class="cvl-unb">Vendido em: <b>'+esc(unNome(p.un))+'</b></span> <b>'+esc(p.cod)+'</b> · '+esc(p.desc)+' · custo '+(p.custo?BRL.format(p.custo)+' '+unPor(p.un):'<span class="cvl-warn">sem custo na 286</span>'):'<span class="pcg-sm">Código ou descrição do produto (base 286) e aguarde as sugestões.</span>';
