function cvlSigImg(id,cls){const s=id&&CVL.sigs[id];return s?'<img class="'+(cls||"cvl-sig")+'" src="'+s+'" alt="Assinatura digital">':'';}
function cvlSigPad(cb){const ov=document.createElement("div");ov.className="pcg-ov";ov.innerHTML='<div class="pcg-dlg cvl-sp" role="dialog" aria-modal="true" aria-labelledby="cvl-spt"><header><div><h3 id="cvl-spt">Sua assinatura digital</h3><p class="pcg-dp">Assine no quadro com o dedo, a caneta ou o mouse. Ela fica salva e entra sozinha em cada vale que você aprovar ou recusar.</p></div><button type="button" class="pcg-dx" data-x aria-label="Fechar">×</button></header><div class="cvl-spb"><canvas width="900" height="300" aria-label="Quadro de assinatura"></canvas><span class="cvl-spl">'+esc((LOGIN&&LOGIN.nome)||"")+' · '+esc(meuMat())+'</span></div><footer><button type="button" class="btn sm" data-l>Limpar</button><span></span><button type="button" class="btn sm" data-x>Cancelar</button><button type="button" class="save pcg-bt" data-ok>Salvar assinatura</button></footer></div>';
  document.body.appendChild(ov);document.documentElement.classList.add("shl-lock");const cv=ov.querySelector("canvas"),g=cv.getContext("2d");let des=false,tem=false,ult=null;g.lineWidth=5;g.lineCap="round";g.lineJoin="round";g.strokeStyle="#0B2A55";
  const pt=e=>{const r=cv.getBoundingClientRect();return [(e.clientX-r.left)*cv.width/r.width,(e.clientY-r.top)*cv.height/r.height];};
  cv.addEventListener("pointerdown",e=>{e.preventDefault();cv.setPointerCapture(e.pointerId);des=true;ult=pt(e);g.beginPath();g.arc(ult[0],ult[1],2.4,0,7);g.fillStyle="#0B2A55";g.fill();tem=true;});
  cv.addEventListener("pointermove",e=>{if(!des)return;const p=pt(e);g.beginPath();g.moveTo(ult[0],ult[1]);g.lineTo(p[0],p[1]);g.stroke();ult=p;});
  ["pointerup","pointercancel","pointerleave"].forEach(k=>cv.addEventListener(k,()=>{des=false;}));
  const fecha=()=>{ov.remove();document.documentElement.classList.remove("shl-lock");};
  ov.addEventListener("click",async e=>{if(e.target.closest("[data-x]")){fecha();return;}if(e.target.closest("[data-l]")){g.clearRect(0,0,cv.width,cv.height);tem=false;return;}
    if(e.target.closest("[data-ok]")){if(!tem){toast("Faça a sua assinatura no quadro.");return;}
      /* recorta, reduz e grava em PNG (cabe numa célula da planilha) */
      const d=g.getImageData(0,0,cv.width,cv.height).data;let x0=cv.width,y0=cv.height,x1=0,y1=0;for(let y=0;y<cv.height;y+=2)for(let x=0;x<cv.width;x+=2)if(d[(y*cv.width+x)*4+3]>0){if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y;}
      x0=Math.max(0,x0-12);y0=Math.max(0,y0-12);x1=Math.min(cv.width,x1+12);y1=Math.min(cv.height,y1+12);const w=x1-x0,h=y1-y0,k=Math.min(1,420/w,140/h),o=document.createElement("canvas");o.width=Math.max(1,Math.round(w*k));o.height=Math.max(1,Math.round(h*k));o.getContext("2d").drawImage(cv,x0,y0,w,h,0,0,o.width,o.height);
      let img=o.toDataURL("image/png");if(img.length>45000){const o2=document.createElement("canvas");o2.width=o.width;o2.height=o.height;const g2=o2.getContext("2d");g2.fillStyle="#fff";g2.fillRect(0,0,o2.width,o2.height);g2.drawImage(o,0,0);img=o2.toDataURL("image/jpeg",0.7);}
      const b=e.target.closest("[data-ok]");b.disabled=true;b.textContent="Salvando…";const j=await ppPost({acao:"vc_assinatura_salvar",img});
      if(!j||!j.ok){b.disabled=false;b.textContent="Salvar assinatura";toast((j&&j.erro)||"Não foi possível salvar a assinatura.");return;}
      CVL.sigs[j.id]=img;CVL.minhaSig=j.id;fecha();toast("Assinatura digital salva.");if(cb)cb(j.id);else cvlPaint();}});}
/* ---------- termo do vale (impressão) ---------- */
let CVL_LOGO="";async function cvlLogo(){if(CVL_LOGO)return CVL_LOGO;try{const b=await (await fetch("icon-192.png")).blob();CVL_LOGO=await new Promise(ok=>{const r=new FileReader();r.onload=()=>ok(String(r.result));r.onerror=()=>ok("");r.readAsDataURL(b);});}catch(e){CVL_LOGO="";}return CVL_LOGO;}
async function cvlTermo(id){const r=CVL.rows.find(x=>x.ID===id);if(!r)return;const w=window.open("","_blank");if(!w){toast("O navegador bloqueou a janela do termo: permita pop-ups para este site.");return;}w.document.write('<p style="font:16px sans-serif;padding:20px">Montando o termo…</p>');
  const logo=await cvlLogo(),I=cvlIt(r),v=cvlVal(r),np=Math.max(1,+r.Parcelas||1),st=r.Status,sig=r.Assinatura_ID&&CVL.sigs[r.Assinatura_ID];
  const linhas=I.length?I.map((i,k)=>'<tr><td>'+(k+1)+'</td><td>'+esc(i.cod)+'</td><td class="l">'+esc(i.desc)+'</td><td>'+cvlQ(i.qtd)+'</td><td>'+esc(cvlUn(i)?(UN_NOME[cvlUn(i)]?UN_NOME[cvlUn(i)][0]:cvlUn(i)):"—")+'</td><td class="r">'+BRL.format(+i.custo||0)+'</td><td class="r">'+BRL.format((+i.qtd||0)*(+i.custo||0))+'</td></tr>').join(""):'<tr><td colspan="7" class="l">'+esc(r.Tipo||"Vale")+' · '+BRL.format(v)+'</td></tr>';
  const aprov=st==="Aprovado"||st==="Recusado"?'<div class="ap '+(st==="Aprovado"?"ok":"no")+'"><div class="apt">'+(st==="Aprovado"?"VALE AUTORIZADO":"VALE RECUSADO")+'</div><div class="apg">'+(sig?'<img src="'+sig+'" alt="Assinatura digital">':'<i>sem assinatura registrada</i>')+'</div><div class="apn"><b>'+esc(r.Decidido_Por||"")+'</b> · matrícula '+esc(r.Decidido_Por_Mat||"")+'<br>Assinado digitalmente em '+esc(r.Decidido_Em||"")+(r.Codigo_Validacao?'<br>Código de validação: <b>'+esc(r.Codigo_Validacao)+'</b>':'')+(r.Obs_Decisao?'<br>Observação: '+esc(r.Obs_Decisao):'')+'</div></div>':'<div class="ap pe"><div class="apt">'+(st==="Cancelado"?"PEDIDO CANCELADO":"AGUARDANDO APROVAÇÃO")+'</div><div class="apn">Aprovação: '+CVL_APRS+'.</div></div>';
  const css='@page{size:A4 portrait;margin:12mm}*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}body{margin:0;font:13px/1.45 Calibri,Inter,Arial,sans-serif;color:#0F172A;background:#E2E8F0}.pg{width:186mm;min-height:270mm;margin:8mm auto;background:#fff;padding:12mm;position:relative;box-shadow:0 4px 18px rgba(0,0,0,.15)}'+
    '.hd{display:flex;align-items:center;gap:14px;border-bottom:3px solid #103F79;padding-bottom:10px}.hd img{width:54px;height:54px;object-fit:contain}.hd div{flex:1}.hd b{display:block;font-size:19px;color:#103F79}.hd span{font-size:12px;color:#475569}.hd .id{text-align:right;font-size:12px;color:#475569}.hd .id b{font-size:14px;color:#0F172A}'+
    'h1{font-size:17px;text-align:center;margin:16px 0 12px;letter-spacing:.03em}.dd{display:grid;grid-template-columns:1fr 1fr;gap:6px 18px;background:#F1F5F9;border-radius:8px;padding:10px 14px;margin-bottom:12px}.dd div span{display:block;font-size:10.5px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.04em}.dd div b{font-size:13.5px}'+
    'table{width:100%;border-collapse:collapse;margin:6px 0}th{background:#103F79;color:#fff;font-size:11.5px;padding:6px 7px}td{border-bottom:1px solid #CBD5E1;padding:5px 7px;text-align:center;font-size:12.5px}td.l{text-align:left}td.r{text-align:right}tfoot td{font-weight:800;font-size:14px;border-top:2px solid #103F79;border-bottom:0}'+
    '.tx{text-align:justify;margin:12px 0}.mot{border-left:4px solid #94A3B8;padding:4px 10px;color:#334155;margin:8px 0;font-style:italic}.ap{border:2px solid;border-radius:10px;padding:10px 14px;margin:14px 0;display:grid;grid-template-columns:160px 1fr;gap:4px 16px;align-items:center}.ap.ok{border-color:#16A34A}.ap.no{border-color:#DC2626}.ap.pe{border-color:#B45309;grid-template-columns:1fr}.apt{grid-column:1/-1;font-weight:800;letter-spacing:.06em}.ok .apt{color:#16A34A}.no .apt{color:#DC2626}.pe .apt{color:#B45309}.apg{height:64px;display:flex;align-items:center;justify-content:center;border-bottom:1px solid #94A3B8}.apg img{max-height:62px;max-width:160px}.apn{font-size:11.5px;color:#334155}'+
    '.as{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:46px}.as div{border-top:1px solid #0F172A;padding-top:4px;text-align:center;font-size:11.5px}.as b{display:block;font-size:12px}.rod{position:absolute;left:12mm;right:12mm;bottom:8mm;font-size:9.5px;color:#64748B;text-align:center}'+
    '.mk{position:absolute;top:42%;left:0;right:0;text-align:center;font-size:64px;font-weight:900;color:rgba(180,83,9,.12);transform:rotate(-22deg);pointer-events:none}@media print{body{background:#fff}.pg{margin:0;box-shadow:none;min-height:auto}}';
  const html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Termo de vale '+esc(r.ID)+'</title><style>'+css+'</style></head><body><div class="pg">'+(st==="Aprovado"?'':'<div class="mk">'+(st==="Pendente"?"PENDENTE":st.toUpperCase())+'</div>')+
    '<div class="hd">'+(logo?'<img src="'+logo+'" alt="">':'')+'<div><b>Santa Therezinha Atacadista</b><span>Centro de Distribuição · Central de Vales</span></div><div class="id">Vale nº<br><b>'+esc(r.ID)+'</b><br>'+esc(r.Data_Solicitacao||"")+'</div></div>'+
    '<h1>TERMO DE VALE DE MERCADORIAS</h1><div class="dd"><div><span>Colaborador</span><b>'+esc(r.Colaborador_Nome)+'</b></div><div><span>Matrícula</span><b>'+esc(r.Colaborador_Mat)+'</b></div><div><span>Função</span><b>'+esc(r.Funcao||"—")+'</b></div><div><span>Solicitado por</span><b>'+esc(r.Solicitante_Nome||r.Solicitante_Mat)+'</b></div></div>'+
    '<table><thead><tr><th>#</th><th>Código</th><th>Descrição</th><th>Quantidade</th><th>Venda</th><th>Custo unit.</th><th>Subtotal</th></tr></thead><tbody>'+linhas+'</tbody><tfoot><tr><td colspan="6" class="r">Valor total do vale</td><td class="r">'+BRL.format(v)+'</td></tr></tfoot></table>'+
    '<p class="tx">Eu, <b>'+esc(r.Colaborador_Nome)+'</b>, matrícula <b>'+esc(r.Colaborador_Mat)+'</b>, declaro ter recebido as mercadorias relacionadas acima, no valor total de <b>'+BRL.format(v)+'</b>, e autorizo o desconto desse valor em minha folha de pagamento em <b>'+np+' parcela(s)</b> de <b>'+BRL.format(v/np)+'</b>.</p>'+(r.Motivo?'<div class="mot">Motivo: '+esc(r.Motivo)+'</div>':'')+aprov+
    '<div class="as"><div><b>'+esc(r.Colaborador_Nome)+'</b>Colaborador · matrícula '+esc(r.Colaborador_Mat)+'</div><div><b>'+esc(r.Solicitante_Nome||r.Solicitante_Mat)+'</b>Solicitante (encarregado/líder)</div></div>'+
    '<div class="rod">Termo gerado pela Central de Vales em '+new Date().toLocaleString("pt-BR")+' · '+esc(r.ID)+(r.Codigo_Validacao?' · validação '+esc(r.Codigo_Validacao):'')+'</div></div><scr'+'ipt>window.onload=function(){setTimeout(function(){window.print();},400);};<\/script></body></html>';
  w.document.open();w.document.write(html);w.document.close();}
